from typing import Dict, List, TypedDict, Optional
import datetime
from typing import Dict, List, Optional
from datetime import datetime



class DocumentInfo(TypedDict):
    document_id: str
    title: str
    content: str
    creation_date: str
    last_modified_date: str
    version: int
    status: str
    owner_id: str
    access_permission: str  # Could be a string like "read,write" or we use AccessControlEntry instead

class UserInfo(TypedDict):
    _id: str
    name: str
    role: str
    department: str

class AccessControlEntryInfo(TypedDict):
    document_id: str
    user_id: str
    permissions: List[str]  # e.g., ["read"], ["read", "write"], etc.

class DocumentVersionInfo(TypedDict):
    version_id: str
    document_id: str
    version_number: int
    content_snapshot: str
    timestamp: str
    modified_by: str


class DocumentManagementSystem:
    def __init__(self):
        """
        A document management system for managing electronic documents with access control and versioning.
        """

        # Documents: {document_id: DocumentInfo}
        self.documents: Dict[str, DocumentInfo] = {}

        # Users: {user_id: UserInfo}
        self.users: Dict[str, UserInfo] = {}

        # Access control: {document_id: {user_id: permissions_list}}
        self.access_control: Dict[str, Dict[str, List[str]]] = {}

        # Document versions: {version_id: DocumentVersionInfo}
        self.versions: Dict[str, DocumentVersionInfo] = {}

        # Constraints reminder:
        # - Only documents with status = "active" can be retrieved
        # - A user must have 'read' permission on a document to retrieve it
        # - Each document must have a unique document_id
        # - The system maintains at least one version (current) for each document
        # - Access permissions are enforced during retrieval operations

    def get_document_by_id(self, document_id: str, user_id: str) -> dict:
        """
        Retrieve a document's metadata and content by document_id, only if the document status is "active"
        and the requesting user has 'read' permission.

        Args:
            document_id (str): The unique ID of the document to retrieve.
            user_id (str): The ID of the user attempting to access the document.

        Returns:
            dict: {
                "success": True,
                "data": DocumentInfo
            }
            or
            {
                "success": False,
                "error": str  # Explanation of why access was denied or failed
            }

        Constraints:
            - Only documents with status = "active" can be retrieved.
            - A user must have 'read' permission on the document to retrieve it.
            - Access permissions are enforced during retrieval.
        """
        # Check if document exists
        if document_id not in self.documents:
            return {"success": False, "error": "Document not found"}

        document = self.documents[document_id]

        # Check if document is active
        if document["status"] != "active":
            return {"success": False, "error": "Document is not active"}

        # Check if user exists
        if user_id not in self.users:
            return {"success": False, "error": "User not found"}

        # Check if user has read permission via access_control
        doc_access = self.access_control.get(document_id, {})
        user_permissions = doc_access.get(user_id, [])

        if "read" not in user_permissions:
            return {"success": False, "error": "User does not have read permission on this document"}

        # All checks passed, return document info
        return {"success": True, "data": document}

    def list_active_documents(self) -> dict:
        """
        List all documents in the system with status "active".

        Returns:
            dict: {
                "success": True,
                "data": List[DocumentInfo]  # List of documents where status == "active"
            }
            or, in case of no matches, an empty list is returned under "data".

        Constraints:
            - Only documents with status = "active" are included.
            - Each document in the result must have a unique document_id (enforced by system invariant).
        """
        active_docs = [
            doc_info for doc_info in self.documents.values()
            if doc_info["status"] == "active"
        ]
        return {"success": True, "data": active_docs}

    def check_document_status(self, document_id: str) -> dict:
        """
        Return the current status of a document (e.g., 'active', 'archived', 'deleted').

        Args:
            document_id (str): The unique identifier of the document.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "status": str  # Current status of the document
                }
            }
            or
            {
                "success": False,
                "error": str  # Explanation, e.g., "Document not found"
            }

        Constraints:
            - The document must exist in the system.
            - This operation does not require read permission; status is accessible metadata.
        """
        document = self.documents.get(document_id)
        if not document:
            return {"success": False, "error": "Document not found"}

        return {"success": True, "data": {"status": document["status"]}}

    def get_document_permissions(self, document_id: str) -> dict:
        """
        Retrieve the list of users and their access permissions (read, write, delete) for a given document.

        Args:
            document_id (str): The unique identifier of the document.

        Returns:
            dict: {
                "success": bool,
                "data": List[{
                    "user": UserInfo,
                    "permissions": List[str]  # e.g., ["read"], ["read", "write"]
                }]  # Empty list if no users have permissions
            }
            or {
                "success": False,
                "error": str
            }

        Constraints:
            - The document must exist in the system.
            - No active status requirement for this meta-operation (permission inspection allowed even for inactive docs).
            - Access to view permissions is assumed to be unrestricted (e.g., admin or owner functionality).
        """
        if document_id not in self.documents:
            return {"success": False, "error": "Document does not exist"}

        # Get permission entries for this document
        user_permission_entries = self.access_control.get(document_id, {})

        result = []
        for user_id, permissions in user_permission_entries.items():
            user_info = self.users.get(user_id)
            # Even if user doesn't exist (edge case), include minimal info
            if user_info is None:
                user_info = {
                    "_id": user_id,
                    "name": "<unknown>",
                    "role": "<unknown>",
                    "department": "<unknown>"
                }
            result.append({
                "user": user_info,
                "permissions": permissions
            })

        return {
            "success": True,
            "data": result
        }

    def check_user_access(self, user_id: str, document_id: str, permission: str) -> dict:
        """
        Determine whether a specific user has a given permission (e.g., 'read') on a document.

        Args:
            user_id (str): The ID of the user.
            document_id (str): The ID of the document.
            permission (str): The permission to check (e.g., 'read', 'write', 'delete').

        Returns:
            dict: {
                "success": bool,
                "data": bool  # True if user has the permission, False otherwise
            }
            or
            {
                "success": False,
                "error": str  # Description of validation or lookup error
            }

        Constraints:
            - The user must exist in the system.
            - The document must exist in the system.
            - Access is determined by entries in the access control list.
        """
        # Validate inputs
        if not user_id or not isinstance(user_id, str):
            return {"success": False, "error": "Invalid user_id: must be a non-empty string"}
        if not document_id or not isinstance(document_id, str):
            return {"success": False, "error": "Invalid document_id: must be a non-empty string"}
        if not permission or not isinstance(permission, str):
            return {"success": False, "error": "Invalid permission: must be a non-empty string"}

        # Check if document exists
        if document_id not in self.documents:
            return {"success": False, "error": f"Document with ID '{document_id}' does not exist"}

        # Check if user exists
        if user_id not in self.users:
            return {"success": False, "error": f"User with ID '{user_id}' does not exist"}

        # Check access control
        doc_acl = self.access_control.get(document_id)
        if not doc_acl:
            return {"success": True, "data": False}  # No ACL defined for this document → no access

        user_permissions = doc_acl.get(user_id)
        if not user_permissions:
            return {"success": True, "data": False}  # User has no permissions on this document

        # Check if the requested permission is in the user's permissions
        has_permission = permission in user_permissions
        return {"success": True, "data": has_permission}

    def get_document_version_history(self, document_id: str, user_id: str) -> dict:
        """
        Retrieve the version history of a document, including version numbers, timestamps, and modifiers.

        Args:
            document_id (str): The unique identifier of the document.
            user_id (str): The ID of the user requesting the version history (for access control).

        Returns:
            dict: {
                "success": bool,
                "data": List[DocumentVersionInfo]  # Sorted by version_number ascending
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure: document not found, not active, access denied, etc.
            }

        Constraints:
            - Only documents with status = "active" can be retrieved.
            - A user must have 'read' permission on the document to retrieve its version history.
            - The system maintains at least one version for each document (guaranteed).
        """
        # Check if document exists
        if document_id not in self.documents:
            return {"success": False, "error": "Document not found"}

        document = self.documents[document_id]

        # Check if document is active
        if document["status"] != "active":
            return {"success": False, "error": "Document is not active"}

        # Check if user has read permission
        doc_access = self.access_control.get(document_id, {})
        user_permissions = doc_access.get(user_id, [])
        if "read" not in user_permissions:
            return {"success": False, "error": "User does not have read permission on this document"}

        # Retrieve all versions for this document
        versions = [
            version_info for version_info in self.versions.values()
            if version_info["document_id"] == document_id
        ]

        # Sort versions by version_number ascending (oldest first)
        versions.sort(key=lambda v: v["version_number"])

        return {
            "success": True,
            "data": versions
        }

    def get_document_current_version(self, document_id: str) -> dict:
        """
        Retrieve the current (latest) version of a document, including metadata and content snapshot.

        Args:
            document_id (str): The unique identifier of the document.

        Returns:
            dict: {
                "success": bool,
                "data": DocumentVersionInfo  # If successful
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - The document must exist and have status "active".
            - The system must maintain at least one version per document (if none, it's an error).
        """
        # Check if document exists
        if document_id not in self.documents:
            return {"success": False, "error": "Document does not exist"}

        document = self.documents[document_id]

        # Check if document is active
        if document["status"] != "active":
            return {"success": False, "error": "Document is not active and cannot be retrieved"}

        # Find all versions for the document
        document_versions = [
            version for version in self.versions.values()
            if version["document_id"] == document_id
        ]

        # Check if there is at least one version (required by constraint)
        if not document_versions:
            return {"success": False, "error": "No versions found for the document"}

        # Get the version with the highest version_number (latest)
        current_version = max(document_versions, key=lambda v: v["version_number"])

        return {"success": True, "data": current_version}

    def get_document_content(self, document_id: str, user_id: str) -> dict:
        """
        Retrieve the content of a document if it is active and the user has read permission.

        Args:
            document_id (str): The unique identifier of the document.
            user_id (str): The ID of the user requesting access.

        Returns:
            dict: {
                "success": True,
                "data": str  # The content of the document
            }
            or
            {
                "success": False,
                "error": str  # Explanation of why access was denied
            }

        Constraints:
            - Only documents with status = "active" can be retrieved.
            - A user must have 'read' permission on the document to retrieve it.
            - Access permissions are enforced during retrieval.
        """
        # Check if document exists
        if document_id not in self.documents:
            return { "success": False, "error": "Document not found" }

        document = self.documents[document_id]

        # Check if document is active
        if document["status"] != "active":
            return { "success": False, "error": "Document is not active" }

        # Check if user exists
        if user_id not in self.users:
            return { "success": False, "error": "User not found" }

        # Check access control: document must have an entry and user must have 'read' permission
        doc_access = self.access_control.get(document_id, {})
        user_permissions = doc_access.get(user_id, [])

        if "read" not in user_permissions:
            return { "success": False, "error": "User does not have read permission on this document" }

        # All checks passed: return the content
        return { "success": True, "data": document["content"] }

    def search_documents_by_title(self, title_query: str) -> dict:
        """
        Search for documents by title using case-insensitive substring matching.
        Only documents with status "active" are included in the search results.

        Args:
            title_query (str): The substring to search for in document titles.

        Returns:
            dict: {
                "success": True,
                "data": List[DocumentInfo]  # List of matching active documents (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Only if an unexpected issue occurs (not expected here)
            }

        Constraints:
            - Only documents with status == "active" are returned.
            - Case-insensitive matching is performed on the title.
            - No access control check is performed due to absence of user_id in parameters.
        """
        try:
            result = []
            query_lower = title_query.lower()

            for doc_info in self.documents.values():
                # Only include active documents
                if doc_info["status"] != "active":
                    continue
                # Case-insensitive substring match in title
                if query_lower in doc_info["title"].lower():
                    result.append(doc_info)

            return { "success": True, "data": result }
        except Exception as e:
            return { "success": False, "error": f"Unexpected error during search: {str(e)}" }


    def create_document(
        self,
        title: str,
        content: str,
        owner_id: str,
        permissions: Optional[List[str]] = None
    ) -> Dict[str, str]:
        """
        Create a new document with initial metadata and version.

        Args:
            title (str): The title of the document.
            content (str): The initial content of the document.
            owner_id (str): The ID of the user who will own the document.
            permissions (List[str], optional): List of initial permissions for the owner.
                Defaults to ["read", "write"].

        Returns:
            dict: {
                "success": True,
                "message": "Document created successfully with ID: <document_id>"
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - owner_id must correspond to an existing user.
            - document_id must be unique.
            - A document is created with status "active".
            - The first version is recorded in version history.
            - Owner is granted read (and optionally write) access.
        """
        # Validate required fields
        if not title or not content or not owner_id:
            return { "success": False, "error": "Title, content, and owner_id are required" }

        # Check if owner exists
        if owner_id not in self.users:
            return { "success": False, "error": f"Owner with ID '{owner_id}' does not exist" }

        # Generate unique document_id
        doc_id_counter = 1
        document_id = f"doc_{doc_id_counter}"
        while document_id in self.documents:
            doc_id_counter += 1
            document_id = f"doc_{doc_id_counter}"

        # Set default permissions
        if permissions is None:
            permissions = ["read", "write"]

        if "read" not in permissions:
            # Enforce that owner must at least have read permission
            permissions.append("read")

        # Get current timestamp
        current_time = datetime.datetime.utcnow().isoformat() + "Z"

        # Create the document
        document: DocumentInfo = {
            "document_id": document_id,
            "title": title,
            "content": content,
            "creation_date": current_time,
            "last_modified_date": current_time,
            "version": 1,
            "status": "active",
            "owner_id": owner_id,
            "access_permission": ",".join(permissions)  # Store as comma-separated string; fine-grained via access_control
        }
        self.documents[document_id] = document

        # Create first version
        version_id = f"v_{document_id}_1"
        version: DocumentVersionInfo = {
            "version_id": version_id,
            "document_id": document_id,
            "version_number": 1,
            "content_snapshot": content,
            "timestamp": current_time,
            "modified_by": owner_id
        }
        self.versions[version_id] = version

        # Set access control for owner
        if document_id not in self.access_control:
            self.access_control[document_id] = {}
        self.access_control[document_id][owner_id] = permissions

        return {
            "success": True,
            "message": f"Document created successfully with ID: {document_id}"
        }

    def update_document(
        self,
        document_id: str,
        user_id: str,
        title: Optional[str] = None,
        content: Optional[str] = None
    ) -> dict:
        """
        Update a document's title or content, increment its version, and create a new version snapshot.

        Args:
            document_id (str): The ID of the document to update.
            user_id (str): The ID of the user making the update.
            title (str, optional): New title for the document.
            content (str, optional): New content for the document.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: description of update and new version
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Document must exist and have status "active".
            - User must have "write" permission on the document.
            - At least one of title or content must be provided.
            - A new version entry is created with the updated content or current content.
        """
        if not document_id or not user_id:
            return {"success": False, "error": "Document ID and User ID are required"}

        if document_id not in self.documents:
            return {"success": False, "error": "Document does not exist"}

        document = self.documents[document_id]

        if document["status"] != "active":
            return {"success": False, "error": "Document is not active and cannot be updated"}

        if user_id not in self.users:
            return {"success": False, "error": "User does not exist"}

        # Check write permission
        if (
            document_id not in self.access_control or
            user_id not in self.access_control[document_id] or
            "write" not in self.access_control[document_id][user_id]
        ):
            return {"success": False, "error": "User does not have write permission on this document"}

        # Ensure at least one field is being updated
        if title is None and content is None:
            return {"success": False, "error": "No updates provided; at least one of title or content must be specified"}

        # Use current time (simulate ISO format)
        current_time = "2024-04-01T12:00:00Z"  # In production: datetime.utcnow().isoformat() + 'Z'

        # Update document metadata
        old_version = document["version"]
        new_version = old_version + 1

        # Update document fields if provided
        if title is not None:
            document["title"] = title
        if content is not None:
            document["content"] = content

        document["last_modified_date"] = current_time
        document["version"] = new_version

        # Create new version snapshot
        # If content is not updated, use current content from document
        snapshot_content = document["content"]

        version_id = f"{document_id}_v{new_version}"

        new_version_entry: DocumentVersionInfo = {
            "version_id": version_id,
            "document_id": document_id,
            "version_number": new_version,
            "content_snapshot": snapshot_content,
            "timestamp": current_time,
            "modified_by": user_id
        }

        self.versions[version_id] = new_version_entry

        return {
            "success": True,
            "message": f"Document updated successfully and version incremented to {new_version}."
        }

    def delete_document(self, document_id: str, user_id: str) -> dict:
        """
        Mark a document as deleted (soft delete) so it can no longer be accessed.
        The document status is set to 'deleted'. Access is revoked and it will not appear in active queries.

        Args:
            document_id (str): The unique identifier of the document to delete.
            user_id (str): The ID of the user attempting the deletion (must have delete or write permission).

        Returns:
            dict: {
                "success": True,
                "message": "Document deleted successfully."
            }
            or
            {
                "success": False,
                "error": str  # e.g., "Document not found", "User does not have permission", etc.
            }

        Constraints:
            - The user must have 'delete' or appropriate permission (e.g., write and ownership) to delete.
            - Only active documents can be deleted (not already deleted).
            - Document ID must exist.
            - After deletion, document is no longer retrievable (status becomes 'deleted').
        """
        # Check if document exists
        if document_id not in self.documents:
            return {"success": False, "error": "Document not found"}

        document = self.documents[document_id]

        # Check if document is already deleted
        if document["status"] == "deleted":
            return {"success": True, "message": "Document deleted successfully."}  # Idempotent behavior

        # Check if user exists
        if user_id not in self.users:
            return {"success": False, "error": "User not found"}

        # Check if user has delete permission
        # Access control: check if user has 'delete' or 'write' (assuming write implies delete capability)
        doc_acl = self.access_control.get(document_id, {})
        user_permissions = doc_acl.get(user_id, [])

        if "delete" not in user_permissions and "write" not in user_permissions:
            return {"success": False, "error": "User does not have permission to delete this document"}

        # Perform soft delete: update status
        document["status"] = "deleted"
        # Optionally: last_modified_date could be updated, but not required here

        # Note: We do not remove access control or versions per soft-delete policy
        # The versions are preserved as per constraint: at least one version exists per document

        return {"success": True, "message": "Document deleted successfully."}

    def restore_document(self, document_id: str) -> dict:
        """
        Restore a document to "active" status if it exists and has at least one version.

        Args:
            document_id (str): The unique identifier of the document to restore.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            } or {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - The document must exist.
            - The document must have at least one version (in self.versions) linked to it.
            - After restore, status becomes "active".
        """
        if document_id not in self.documents:
            return {"success": False, "error": "Document does not exist"}

        # Check if the document has at least one version
        document_has_version = any(
            version["document_id"] == document_id
            for version in self.versions.values()
        )
        if not document_has_version:
            return {"success": False, "error": "Document has no versions; cannot restore"}

        # Update status to active
        self.documents[document_id]["status"] = "active"

        return {"success": True, "message": "Document restored successfully."}

    def set_document_permissions(self, document_id: str, user_id: str, permissions: List[str]) -> dict:
        """
        Define or update access permissions for a user on a specific document.

        Args:
            document_id (str): The unique identifier of the document.
            user_id (str): The unique identifier of the user.
            permissions (List[str]): List of permissions to grant. Valid values: 'read', 'write', 'delete'.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": bool,
                "error": str  # On failure
            }

        Constraints:
            - The document must exist.
            - The user must exist.
            - Permissions must be a subset of ['read', 'write', 'delete'].
            - Setting permissions does not require the document to be active.

        Note:
            This operation overwrites existing permissions for the user on the document.
        """
        # Validate inputs
        if not isinstance(permissions, list):
            return { "success": False, "error": "Permissions must be a list of strings" }

        valid_permissions = {"read", "write", "delete"}
        if not all(perm in valid_permissions for perm in permissions):
            return { "success": False, "error": f"Invalid permission in list. Allowed: {list(valid_permissions)}" }

        if document_id not in self.documents:
            return { "success": False, "error": "Document does not exist" }

        if user_id not in self.users:
            return { "success": False, "error": "User does not exist" }

        # Ensure the document entry exists in access_control
        if document_id not in self.access_control:
            self.access_control[document_id] = {}

        # Set or update permissions for the user
        self.access_control[document_id][user_id] = permissions

        return { "success": True, "message": "Permissions set successfully" }

    def revoke_user_access(self, document_id: str, user_id: str) -> dict:
        """
        Remove a user’s access permissions to a specific document.

        Args:
            document_id (str): The unique identifier of the document.
            user_id (str): The unique identifier of the user whose access is to be revoked.

        Returns:
            dict: {
                "success": True,
                "message": str  # Describes the revocation result
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g. document or user not found)
            }

        Constraints:
            - The document must exist in the system.
            - The user must exist in the system.
            - After revocation, the user will no longer have any permissions on the document.
            - Revoking non-granted access is allowed and treated as success.
        """
        if document_id not in self.documents:
            return { "success": False, "error": f"Document with ID '{document_id}' does not exist." }

        if user_id not in self.users:
            return { "success": False, "error": f"User with ID '{user_id}' does not exist." }

        # Check if this document has any access control entries
        if document_id in self.access_control:
            # Remove the user's access if it exists
            if user_id in self.access_control[document_id]:
                del self.access_control[document_id][user_id]
                # Optional: clean up document entry if empty
                if not self.access_control[document_id]:
                    del self.access_control[document_id]

        return {
            "success": True,
            "message": f"Access revoked for user '{user_id}' on document '{document_id}'."
        }

    def archive_document(self, document_id: str) -> dict:
        """
        Change the status of a document to 'archived', making it non-retrievable in normal queries.

        Args:
            document_id (str): The unique identifier of the document to archive.

        Returns:
            dict: {
                "success": True,
                "message": "Document archived successfully"
            }
            or
            {
                "success": False,
                "error": "Document not found"
            }

        Constraints:
            - The document must exist in the system.
            - After archiving, the document will no longer be retrievable by operations that require status = 'active'.
            - This operation does not require explicit permission checks as per current constraints (only retrieval enforces access).
        """
        if document_id not in self.documents:
            return {"success": False, "error": "Document not found"}

        self.documents[document_id]["status"] = "archived"

        return {"success": True, "message": "Document archived successfully"}


    def revert_to_version(self, document_id: str, version_id: str, user_id: str) -> dict:
        """
        Restore a document to a previous version by creating a new version based on a past snapshot.

        Args:
            document_id (str): The ID of the document to revert.
            version_id (str): The ID of the version to revert to.
            user_id (str): The ID of the user performing the revert.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: description of revert
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Document must exist and have status "active".
            - The version must exist and belong to the document.
            - User must have "write" permission on the document.
            - A new version entry is created; document version and content are updated.
        """
        # Check if document exists and is active
        document = self.documents.get(document_id)
        if not document:
            return {"success": False, "error": "Document not found"}
        if document["status"] != "active":
            return {"success": False, "error": "Cannot revert: document is not active"}

        # Check if user exists
        if user_id not in self.users:
            return {"success": False, "error": "User not found"}

        # Check if user has write permission
        doc_acl = self.access_control.get(document_id, {})
        user_permissions = doc_acl.get(user_id, [])
        if "write" not in user_permissions:
            return {"success": False, "error": "Permission denied: user does not have write access to the document"}

        # Check if the version exists and belongs to the document
        version = self.versions.get(version_id)
        if not version:
            return {"success": False, "error": "Version not found"}
        if version["document_id"] != document_id:
            return {"success": False, "error": "Version does not belong to the specified document"}

        # Get current document version and prepare new version
        current_version_number = document["version"]
        new_version_number = current_version_number + 1
        current_time = datetime.utcnow().isoformat()

        # Create new version based on the old snapshot
        new_version_id = f"ver-{document_id}-{new_version_number}"  # Simple deterministic version ID

        new_version: DocumentVersionInfo = {
            "version_id": new_version_id,
            "document_id": document_id,
            "version_number": new_version_number,
            "content_snapshot": version["content_snapshot"],
            "timestamp": current_time,
            "modified_by": user_id
        }

        # Update document metadata
        document["content"] = version["content_snapshot"]
        document["last_modified_date"] = current_time
        document["version"] = new_version_number

        # Save the new version
        self.versions[new_version_id] = new_version

        return {
            "success": True,
            "message": f"Document reverted to version {version['version_number']} and saved as version {new_version_number}."
        }

    def publish_document(self, document_id: str) -> dict:
        """
        Set a document's status to "active", enabling it to be retrieved by authorized users.

        Args:
            document_id (str): The unique identifier of the document to publish.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure (e.g., document not found)
            }

        Constraints:
            - The document must exist.
            - After publishing, the document becomes retrievable (if status == "active").
            - This operation does not verify user permissions; assumes caller has appropriate rights.
        """
        if document_id not in self.documents:
            return { "success": False, "error": "Document not found" }

        self.documents[document_id]["status"] = "active"

        return { "success": True, "message": "Document published successfully" }

