    This operation overwrites existing permissions for the user on the document.", "source_code": "    def set_document_permissions(self, document_id: str, user_id: str, permissions: List[str]) -> dict:
        """
        Define or update access permissions for a user on a specific document.

        Args:
            document_id (str): The unique identifier of the document.
            user_id (str): The unique identifier of the user.
            permissions (List[str]): List of permissions to grant. Valid values: 'read', 'write', 'delete'.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": bool,
                "error": str  # On failure
            }

        Constraints:
            - The document must exist.
            - The user must exist.
            - Permissions must be a subset of ['read', 'write', 'delete'].
            - Setting permissions does not require the document to be active.

        Note:
            This operation overwrites existing permissions for the user on the document.
        """
        # Validate inputs
        if not isinstance(permissions, list):
            return { "success": False, "error": "Permissions must be a list of strings" }

        valid_permissions = {"read", "write", "delete"}
        if not all(perm in valid_permissions for perm in permissions):
            return { "success": False, "error": f"Invalid permission in list. Allowed: {list(valid_permissions)}" }

        if document_id not in self.documents:
            return { "success": False, "error": "Document does not exist" }

        if user_id not in self.users:
            return { "success": False, "error": "User does not exist" }

        # Ensure the document entry exists in access_control
        if document_id not in self.access_control:
            self.access_control[document_id] = {}

        # Set or update permissions for the user
        self.access_control[document_id][user_id] = permissions

        return { "success": True, "message": "Permissions set successfully" }"}, "revoke_user_access": {"signature": {"parameters": [{"name": "document_id", "type": "str", "default": null, "kind": "positional-or-keyword"}, {"name": "user_id", "type": "str", "default": null, "kind": "positional-or-keyword"}], "return": "dict"}, "doc": "Remove a user’s access permissions to a specific document.

