    hyperparameters: dict  # e.g., {'learning_rate': 0.01, 'n_estimators': 100}
    feature_set: List[str]
    description: str

class ExperimentInfo(TypedDict):
    experiment_id: str
    dataset_id: str
    config_id: str
    status: str  # e.g., 'pending', 'running', 'completed', 'failed'
    start_time: str  # ISO format
    end_time: str  # ISO format
    current_iteration: int

class FeatureSelectionResultInfo(TypedDict):
    selection_id: str
    experiment_id: str
    method: str  # e.g., 'SHAP', 'Permutation Importance'
    importance_scores: Dict[str, float]
    selected_features: List[str]
    threshold: float

class EvaluationResultInfo(TypedDict):
    evaluation_id: str
    experiment_id: str
    iteration: int
    metrics: Dict[str, float]  # e.g., {'RMSE': 1.2, 'MAE': 0.8}
    evaluated_at: str  # ISO format timestamp

class MachineLearningExperimentManagementSystem:
    def __init__(self):
        """
        The environment for managing machine learning experiments.
        """

        # Datasets: {dataset_id: DatasetInfo}
        self.datasets: Dict[str, DatasetInfo] = {}

        # Model Configurations: {config_id: ModelConfigurationInfo}
        self.model_configurations: Dict[str, ModelConfigurationInfo] = {}

        # Experiments: {experiment_id: ExperimentInfo}
        self.experiments: Dict[str, ExperimentInfo] = {}

        # Feature Selection Results: {selection_id: FeatureSelectionResultInfo}
        self.feature_selection_results: Dict[str, FeatureSelectionResultInfo] = {}

        # Evaluation Results: {evaluation_id: EvaluationResultInfo}
        self.evaluation_results: Dict[str, EvaluationResultInfo] = {}

        # Constraints reminder:
        # - Feature selection must be completed before model training begins
        # - Evaluation must occur at specified intervals (e.g., midway, every 10 days)
        # - Model training cannot start if the dataset file_path does not exist or is invalid
        # - Hyperparameters must be validated against model type constraints
        # - Experiment status must reflect current phase ('pending', 'running', 'completed', 'failed')

    def get_dataset_by_id(self, dataset_id: str) -> dict:
        """
        Retrieve dataset metadata (name, file_path, schema, version, created_at) by dataset_id.

        Args:
            dataset_id (str): The unique identifier of the dataset.

        Returns:
            dict: {
                "success": bool,
                "data": DatasetInfo  # If found
            }
            or
            {
                "success": False,
                "error": str  # If not found or invalid input
            }

        Constraints:
            - None beyond existence of the dataset.
        """
        if not dataset_id:
            return { "success": False, "error": "Invalid input: dataset_id cannot be empty or None" }

        dataset = self.datasets.get(dataset_id)
        if not dataset:
            return { "success": False, "error": "Dataset not found" }

        return { "success": True, "data": dataset }

    def get_dataset_by_file_path(self, file_path: str) -> dict:
        """
        Find and return the dataset information associated with the given file path.

        Args:
            file_path (str): The file path (e.g., 'rental_prices.csv') to search for.

        Returns:
            dict: {
                "success": True,
                "data": DatasetInfo  # Full dataset information
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. "No dataset found with the given file path"
            }

        Constraints:
            - This is a query operation; no state changes occur.
            - Multiple datasets may have the same file_path; returns the first match.
        """
        if not file_path:
            return { "success": False, "error": "File path cannot be empty" }

        for dataset in self.datasets.values():
            if dataset["file_path"] == file_path:
                return { "success": True, "data": dataset }

        return { "success": False, "error": "No dataset found with the given file path" }

    def list_all_datasets(self) -> dict:
        """
        Retrieve all registered datasets in the system for exploration or audit.

        Returns:
            dict: {
                "success": True,
                "data": List[DatasetInfo]  # List of all dataset records; empty if none exist
            }

        Constraints:
            - This operation always succeeds as it only reads internal state.
            - No constraints from rules block apply to reading dataset list.
        """
        dataset_list = list(self.datasets.values())
        return { "success": True, "data": dataset_list }

    def get_model_configuration_by_id(self, config_id: str) -> dict:
        """
        Retrieve a model configuration by its unique configuration ID.

        Args:
            config_id (str): The unique identifier of the model configuration.

        Returns:
            dict: {
                "success": bool,
                "data": ModelConfigurationInfo  # Only present if success is True
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Model configuration not found"
            }

        Constraints:
            - The config_id must exist in the system.
        """
        if not config_id:
            return {"success": False, "error": "Invalid input: config_id cannot be empty or None"}

        config = self.model_configurations.get(config_id)
        if config is None:
            return {"success": False, "error": "Model configuration not found"}

        return {"success": True, "data": config}

    def list_configurations_by_model_type(self, model_type: str) -> dict:
        """
        List all model configurations that match the specified model type.

        Args:
            model_type (str): The type of model to filter by (e.g., 'RandomForest', 'LinearRegression').

        Returns:
            dict: {
                "success": True,
                "data": List[ModelConfigurationInfo]  # List of configurations matching the model_type
            }
            or in case of invalid input:
            {
                "success": False,
                "error": str
            }

        Constraints:
            - None directly apply; this is a read-only query operation.
            - Input should be a non-empty string. If empty or None, returns empty list.

        Note:
            - Returns an empty list if no configurations match the model type.
            - Case-sensitive match on model_type.
        """
        if not model_type:
            return { "success": False, "error": "model_type must be a non-empty string" }

        result = [
            config for config in self.model_configurations.values()
            if config["model_type"] == model_type
        ]

        return { "success": True, "data": result }

    def get_experiment_status(self, experiment_id: str) -> dict:
        """
        Query the current status of an experiment.

        Args:
            experiment_id (str): The unique identifier of the experiment.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "status": str  # One of 'pending', 'running', 'completed', 'failed'
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., 'Experiment not found'
            }

        Constraints:
            - The experiment must exist in the system.
        """
        experiment = self.experiments.get(experiment_id)
        if not experiment:
            return {"success": False, "error": "Experiment not found"}

        return {"success": True, "data": {"status": experiment["status"]}}

    def get_experiment_by_id(self, experiment_id: str) -> dict:
        """
        Retrieve full details of an experiment by its ID, including associated dataset and model configuration.

        Args:
            experiment_id (str): The unique identifier of the experiment.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "experiment": ExperimentInfo,
                    "dataset": DatasetInfo,
                    "model_configuration": ModelConfigurationInfo
                }
            }
            or
            {
                "success": False,
                "error": str  # e.g., "Experiment not found", "Associated dataset not found", etc.
            }

        Constraints:
            - The experiment must exist.
            - The associated dataset and model configuration must exist; otherwise, the experiment state is inconsistent.
        """
        if experiment_id not in self.experiments:
            return {"success": False, "error": "Experiment not found"}

        experiment = self.experiments[experiment_id]
        dataset_id = experiment["dataset_id"]
        config_id = experiment["config_id"]

        dataset = self.datasets.get(dataset_id)
        if dataset is None:
            return {"success": False, "error": "Associated dataset not found"}

        model_config = self.model_configurations.get(config_id)
        if model_config is None:
            return {"success": False, "error": "Associated model configuration not found"}

        return {
            "success": True,
            "data": {
                "experiment": experiment,
                "dataset": dataset,
                "model_configuration": model_config
            }
        }

    def list_experiments_by_status(self, status: str) -> dict:
        """
        Retrieve all experiments filtered by their current status.

        Args:
            status (str): The status to filter experiments by (e.g., 'pending', 'running', 'completed', 'failed').

        Returns:
            dict: {
                "success": True,
                "data": List[ExperimentInfo]  # List of experiment details matching the status; may be empty
            }

        Constraints:
            None directly enforced during query — returns all experiments matching the status string.
            Status values are expected to be one of: 'pending', 'running', 'completed', 'failed',
            but any string is accepted for filtering.

        Note:
            This operation does not validate the semantic correctness of the status string,
            and will return an empty list if no experiments match.
        """
        if not isinstance(status, str):
            return { "success": False, "error": "Status must be a string" }

        result = [
            experiment for experiment in self.experiments.values()
            if experiment["status"] == status
        ]

        return { "success": True, "data": result }

    def get_feature_selection_result(self, experiment_id: str) -> dict:
        """
        Retrieve the feature selection result (e.g., selected features, importance scores) 
        for a given experiment.

        Args:
            experiment_id (str): The unique identifier of the experiment.

        Returns:
            dict: {
                "success": bool,
                "data": FeatureSelectionResultInfo or None
            }
            If found, returns the feature selection result; if not found, returns data=None.
            If an error occurs (e.g., invalid input), returns success=False with error message.

        Constraints:
            - The operation only retrieves existing results; it does not trigger feature selection.
            - Feature selection must be completed before training (enforced elsewhere).
        """
        if not isinstance(experiment_id, str) or not experiment_id.strip():
            return {"success": False, "error": "Invalid experiment_id: must be a non-empty string"}

        experiment_id = experiment_id.strip()

        # Search for feature selection result associated with the given experiment_id
        for result in self.feature_selection_results.values():
            if result["experiment_id"] == experiment_id:
                return {"success": True, "data": result}

        # Not found is not an error — just no result yet
        return {"success": True, "data": None}

    def get_evaluation_results(self, experiment_id: str, iteration: int = None) -> dict:
        """
        Retrieve all evaluation metrics logged for a specific experiment, optionally filtered by iteration.

        Args:
            experiment_id (str): The ID of the experiment to retrieve evaluation results for.
            iteration (int, optional): If provided, only return evaluation results for this iteration.

        Returns:
            dict: {
                "success": bool,
                "data": List[EvaluationResultInfo]  # List of evaluation results (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g., experiment not found)
            }

        Constraints:
            - The experiment_id must exist in the system.
            - If iteration is provided, results are filtered to that iteration only.
        """
        # Check if the experiment exists
        if experiment_id not in self.experiments:
            return { "success": False, "error": "Experiment does not exist" }

        # Filter evaluation results by experiment_id
        results = [
            eval_result for eval_result in self.evaluation_results.values()
            if eval_result["experiment_id"] == experiment_id
        ]

        # Further filter by iteration if specified
        if iteration is not None:
            results = [r for r in results if r["iteration"] == iteration]

        return { "success": True, "data": results }

    def check_dataset_validity(self, dataset_id: str) -> dict:
        """
        Verify whether the dataset's file_path points to an existing and accessible file.

        Args:
            dataset_id (str): The ID of the dataset to validate.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "valid": bool  # True if file_path exists and is accessible in simulation
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. dataset not found
            }

        Constraints:
            - The dataset must exist in the system.
            - The file_path is considered valid if it is non-empty and starts with '/' (simulated).
        """
        if dataset_id not in self.datasets:
            return { "success": False, "error": f"Dataset with ID '{dataset_id}' not found" }

        dataset_info = self.datasets[dataset_id]
        file_path = dataset_info.get("file_path", "")

        # Simulated validity: non-empty and starts with '/' to mimic absolute path
        is_valid = bool(file_path) and file_path.startswith("/")

        return { "success": True, "data": { "valid": is_valid } }

    def get_current_iteration(self, experiment_id: str) -> dict:
        """
        Retrieve the current training iteration of a running experiment.

        Args:
            experiment_id (str): The unique identifier of the experiment.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "current_iteration": int  # The current iteration count of the experiment
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g. experiment not found)
            }

        Constraints:
            - The experiment must exist in the system.
        """
        if experiment_id not in self.experiments:
            return {"success": False, "error": "Experiment not found"}

        experiment = self.experiments[experiment_id]
        return {
            "success": True,
            "data": {"current_iteration": experiment["current_iteration"]}
        }

    def create_model_configuration(
        self,
        config_id: str,
        model_type: str,
        hyperparameters: dict,
        feature_set: List[str],
        description: str = ""
    ) -> dict:
        """
        Define a new model configuration with model type, hyperparameters, and feature set.
        Performs validation to ensure hyperparameters are compatible with the model type.

        Args:
            config_id (str): Unique identifier for the model configuration.
            model_type (str): Type of model (e.g., 'RandomForest', 'LinearRegression').
            hyperparameters (dict): Key-value pairs of model hyperparameters.
            feature_set (List[str]): List of feature names used by the model.
            description (str): Optional description of the configuration.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            } or {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - config_id must be unique.
            - hyperparameters must be valid for the model type (e.g., 'learning_rate' only for iterative models).
            - feature_set must be a list of strings.
            - Model types that are iterative (e.g., 'NeuralNetwork', 'GradientBoosting') may accept 'learning_rate'.
            - Non-iterative models (e.g., 'RandomForest', 'LinearRegression') must not have 'learning_rate'.
        """
        # Validate config_id
        if not isinstance(config_id, str) or not config_id.strip():
            return {"success": False, "error": "config_id must be a non-empty string"}
        config_id = config_id.strip()

        if config_id in self.model_configurations:
            return {"success": False, "error": f"Model configuration with id '{config_id}' already exists"}

        # Validate model_type
        if not isinstance(model_type, str) or not model_type.strip():
            return {"success": False, "error": "model_type must be a non-empty string"}
        model_type = model_type.strip()

        # Validate hyperparameters
        if not isinstance(hyperparameters, dict):
            return {"success": False, "error": "hyperparameters must be a dictionary"}

        # Define which models are considered iterative and can have 'learning_rate'
        iterative_models = {"NeuralNetwork", "GradientBoosting", "XGBoost", "SGD", "AdaBoost"}
        if model_type in iterative_models:
            # Allow 'learning_rate'
            pass
        else:
            # For non-iterative models, disallow 'learning_rate'
            if "learning_rate" in hyperparameters:
                return {
                    "success": False,
                    "error": f"Model type '{model_type}' does not support 'learning_rate' hyperparameter"
                }

        # Validate feature_set
        if not isinstance(feature_set, list):
            return {"success": False, "error": "feature_set must be a list of strings"}
        if not all(isinstance(f, str) for f in feature_set):
            return {"success": False, "error": "All features in feature_set must be strings"}

        # Validate description
        if not isinstance(description, str):
            return {"success": False, "error": "description must be a string"}
        description = description.strip()

        # Create new configuration
        new_config: ModelConfigurationInfo = {
            "config_id": config_id,
            "model_type": model_type,
            "hyperparameters": hyperparameters,
            "feature_set": feature_set,
            "description": description
        }

        self.model_configurations[config_id] = new_config

        return {"success": True, "message": "Model configuration created successfully"}

    def run_feature_selection(self, experiment_id: str, method: str, threshold: float) -> dict:
        """
        Execute feature selection on the dataset associated with the given experiment
        using its model configuration, and store the importance scores and selected features.

        Args:
            experiment_id (str): Unique identifier for the experiment.
            method (str): Feature selection method (e.g., 'SHAP', 'Permutation Importance', 'Gain-based').
            threshold (float): Minimum importance score for a feature to be selected.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: description of result
            }
            or {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Feature selection must occur before training begins (experiment status must be 'pending').
            - Dataset must exist and be valid (file_path accessible).
            - Model configuration must exist and have a non-empty feature_set.
            - Threshold must be positive.
            - Method must be a non-empty string.
        """
        # Validate inputs
        if not isinstance(experiment_id, str) or not experiment_id:
            return {"success": False, "error": "Invalid experiment_id: must be a non-empty string"}
        if not isinstance(method, str) or not method:
            return {"success": False, "error": "Invalid method: must be a non-empty string"}
        if not isinstance(threshold, (float, int)) or threshold <= 0:
            return {"success": False, "error": "Invalid threshold: must be a positive number"}

        # Check if experiment exists
        if experiment_id not in self.experiments:
            return {"success": False, "error": f"Experiment with ID '{experiment_id}' not found"}

        experiment = self.experiments[experiment_id]

        # Check experiment status: must be 'pending' (before training)
        if experiment["status"] != "pending":
            return {
                "success": False,
                "error": f"Feature selection can only be run in 'pending' status, but current status is '{experiment['status']}'"
            }

        # Check dataset exists and is valid
        dataset_id = experiment["dataset_id"]
        if dataset_id not in self.datasets:
            return {"success": False, "error": f"Dataset with ID '{dataset_id}' not found"}

        dataset = self.datasets[dataset_id]
        # Simulate file validity check
        try:
            # In real system, check file_path exists and is readable
            if not dataset["file_path"]:
                return {"success": False, "error": "Dataset file_path is missing"}
            # For simulation, we assume file_path is valid if non-empty
        except Exception:
            return {"success": False, "error": "Dataset file_path is invalid or inaccessible"}

        # Get model configuration
        config_id = experiment["config_id"]
        if config_id not in self.model_configurations:
            return {"success": False, "error": f"Model configuration with ID '{config_id}' not found"}

        config = self.model_configurations[config_id]
        feature_set = config["feature_set"]
        if not feature_set:
            return {"success": False, "error": "Model configuration has no feature set defined"}

        # Simulate importance scoring (in real system, this would be computed)
        # Here we assign mock scores (e.g., based on feature name hash for determinism)
        importance_scores = {}
        for feature in feature_set:
            # Mock importance score: deterministic based on feature name
            score = abs(hash(feature)) % 100 / 100.0  # Random-like float between 0 and 1
            importance_scores[feature] = round(score, 4)

        # Select features above threshold
        selected_features = [feat for feat, score in importance_scores.items() if score >= threshold]

        # Generate selection_id
        selection_id = f"{experiment_id}_fs_{method.lower().replace(' ', '_')}"

        # Store result
        feature_selection_result: FeatureSelectionResultInfo = {
            "selection_id": selection_id,
            "experiment_id": experiment_id,
            "method": method,
            "importance_scores": importance_scores,
            "selected_features": selected_features,
            "threshold": threshold
        }

        self.feature_selection_results[selection_id] = feature_selection_result

        return {
            "success": True,
            "message": f"Feature selection completed using '{method}' method for experiment '{experiment_id}'. "
                       f"{len(selected_features)} features selected out of {len(feature_set)} using threshold {threshold}."
        }


    def start_experiment(self, experiment_id: str) -> dict:
        """
        Initialize and start a pending experiment by setting its status to "running" and recording the start time.

        Args:
            experiment_id (str): The ID of the experiment to start.

        Returns:
            dict: {
                "success": True,
                "message": "Experiment started successfully"
            }
            or
            {
                "success": False,
                "error": str  # Description of failure reason
            }

        Constraints:
            - Experiment must exist and be in "pending" status.
            - Dataset referenced by experiment must exist and have a valid file_path.
            - Model configuration must exist.
            - Feature selection must have been completed for the experiment.
        """
        # Get experiment
        experiment = self.experiments.get(experiment_id)
        if not experiment:
            return { "success": False, "error": "Experiment does not exist" }

        if experiment["status"] != "pending":
            return { "success": False, "error": f"Experiment cannot be started; current status is '{experiment['status']}'" }

        # Check dataset exists and is valid
        dataset_id = experiment["dataset_id"]
        dataset = self.datasets.get(dataset_id)
        if not dataset:
            return { "success": False, "error": "Dataset referenced by experiment does not exist" }
        if not dataset["file_path"]:
            return { "success": False, "error": "Dataset file_path is invalid or missing" }

        # Check model configuration exists
        config_id = experiment["config_id"]
        if config_id not in self.model_configurations:
            return { "success": False, "error": "Model configuration referenced by experiment does not exist" }

        # Check feature selection has been completed
        has_feature_selection = any(
            result["experiment_id"] == experiment_id
            for result in self.feature_selection_results.values()
        )
        if not has_feature_selection:
            return { "success": False, "error": "Feature selection must be completed before starting training" }

        # Update experiment state
        experiment["status"] = "running"
        experiment["start_time"] = datetime.now().isoformat()
        if experiment["current_iteration"] is None:
            experiment["current_iteration"] = 0

        return { "success": True, "message": "Experiment started successfully" }

    def update_experiment_status(self, experiment_id: str, new_status: str) -> dict:
        """
        Change the status of an experiment based on execution outcome.

        Args:
            experiment_id (str): The unique identifier of the experiment to update.
            new_status (str): The new status to assign. Must be one of: 'pending', 'running', 'completed', 'failed'.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The experiment must exist.
            - The new_status must be a valid state: 'pending', 'running', 'completed', 'failed'.
        """
        valid_statuses = {"pending", "running", "completed", "failed"}

        if experiment_id not in self.experiments:
            return {"success": False, "error": "Experiment not found."}

        if new_status not in valid_statuses:
            return {"success": False, "error": "Invalid status value."}

        self.experiments[experiment_id]["status"] = new_status

        return {"success": True, "message": "Experiment status updated successfully."}

    def log_evaluation_result(
        self,
        evaluation_id: str,
        experiment_id: str,
        iteration: int,
        metrics: dict,
        evaluated_at: str
    ) -> dict:
        """
        Record evaluation metrics at a specific iteration and timestamp during training.

        Args:
            evaluation_id (str): Unique identifier for this evaluation record.
            experiment_id (str): ID of the associated experiment.
            iteration (int): Training iteration at which evaluation was performed.
            metrics (dict): Dictionary of performance metrics, e.g., {'RMSE': 1.2, 'MAE': 0.8}.
            evaluated_at (str): ISO format timestamp indicating when the evaluation was done.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present if success is True
                "error": str     # Present if success is False
            }

        Constraints:
            - The experiment_id must refer to an existing experiment.
            - The evaluation_id must be unique (cannot already exist).
            - Iteration should be non-negative.
        """
        # Validate iteration
        if iteration < 0:
            return { "success": False, "error": "Iteration must be non-negative" }

        # Check if experiment exists
        if experiment_id not in self.experiments:
            return { "success": False, "error": f"Experiment with ID '{experiment_id}' does not exist" }

        # Check for duplicate evaluation_id
        if evaluation_id in self.evaluation_results:
            return { "success": False, "error": f"Evaluation result with ID '{evaluation_id}' already exists" }

        # Create new evaluation result entry
        evaluation_result: EvaluationResultInfo = {
            "evaluation_id": evaluation_id,
            "experiment_id": experiment_id,
            "iteration": iteration,
            "metrics": metrics,
            "evaluated_at": evaluated_at
        }

        # Store in evaluation results
        self.evaluation_results[evaluation_id] = evaluation_result

        return { "success": True, "message": "Evaluation result logged successfully" }

    def pause_experiment(self, experiment_id: str) -> dict:
        """
        Temporarily halt a running experiment by updating its status to "paused".

        Args:
            experiment_id (str): The unique identifier of the experiment to pause.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., not found, not running)
            }

        Constraints:
            - Only experiments with status "running" can be paused.
            - Experiment must exist.
        """
        experiment = self.experiments.get(experiment_id)
        if not experiment:
            return { "success": False, "error": f"Experiment '{experiment_id}' not found." }

        if experiment["status"] != "running":
            return {
                "success": False,
                "error": f"Experiment '{experiment_id}' cannot be paused. "
                         f"Current status is '{experiment['status']}', but 'running' is required."
            }

        experiment["status"] = "paused"
        return { "success": True, "message": f"Experiment '{experiment_id}' paused successfully." }

    def resume_experiment(self, experiment_id: str) -> dict:
        """
        Resume a paused experiment and continue training from the last iteration.

        Args:
            experiment_id (str): The unique identifier of the experiment to resume.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Describes outcome on success
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - The experiment must exist and be in "paused" status.
            - Cannot resume an experiment that is already running, completed, or failed.
        """
        if not experiment_id:
            return { "success": False, "error": "Experiment ID is required" }

        if experiment_id not in self.experiments:
            return { "success": False, "error": "Experiment does not exist" }

        experiment = self.experiments[experiment_id]
        current_status = experiment["status"]

        if current_status != "paused":
            return { "success": False, "error": f"Cannot resume experiment: status is '{current_status}', expected 'paused'" }

        # Update status to running
        experiment["status"] = "running"

        return {
            "success": True,
            "message": f"Experiment '{experiment_id}' resumed successfully and is now running."
        }

    def cancel_experiment(self, experiment_id: str) -> dict:
        """
        Terminate an experiment by setting its status to "cancelled".

        Args:
            experiment_id (str): The unique identifier of the experiment to cancel.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. experiment not found
            }

        Constraints:
            - The experiment must exist in the system.
            - Cancellation is allowed regardless of current status (pending, running, etc.).
            - This operation does not remove the experiment or associated data.
        """
        if experiment_id not in self.experiments:
            return { "success": False, "error": "Experiment does not exist" }

        self.experiments[experiment_id]["status"] = "cancelled"

        return { "success": True, "message": f"Experiment '{experiment_id}' cancelled." }


    def register_dataset(self, name: str, file_path: str, schema: dict, version: str) -> dict:
        """
        Add a new dataset to the system with metadata.

        Args:
            name (str): Name of the dataset.
            file_path (str): Path to the dataset file.
            schema (dict): Structure of the dataset (e.g., column types).
            version (str): Version string of the dataset.

        Returns:
            dict: {
                "success": bool,
                "message": str,
                "dataset_id": str  # Only included if successful
            }
            or
            {
                "success": False,
                "error": str  # Description of the validation or registration failure
            }

        Constraints:
            - All input fields must be valid and non-empty.
            - schema must be a dictionary.
            - file_path should be a non-empty string.
            - A unique dataset_id is generated upon registration.

        Note:
            - File existence is not checked at registration time (checked during training).
        """
        # Validate inputs
        if not name or not isinstance(name, str):
            return {"success": False, "error": "Name must be a non-empty string"}
        if not file_path or not isinstance(file_path, str):
            return {"success": False, "error": "File path must be a non-empty string"}
        if not isinstance(schema, dict) or len(schema) == 0:
            return {"success": False, "error": "Schema must be a non-empty dictionary"}
        if not version or not isinstance(version, str):
            return {"success": False, "error": "Version must be a non-empty string"}

        # Generate dataset_id
        dataset_id = f"dataset_{len(self.datasets) + 1}"

        # Ensure no ID collision (though unlikely with this scheme)
        while dataset_id in self.datasets:
            dataset_id = f"{dataset_id}_1"

        # Create dataset entry
        created_at = datetime.utcnow().isoformat() + "Z"

        self.datasets[dataset_id] = {
            "dataset_id": dataset_id,
            "name": name,
            "file_path": file_path,
            "schema": schema,
            "version": version,
            "created_at": created_at
        }

        return {
            "success": True,
            "message": "Dataset registered successfully",
            "dataset_id": dataset_id
        }

    def update_model_configuration(self, config_id: str, updates: dict) -> dict:
        """
        Modify an existing model configuration with proper validation of hyperparameters and other fields.

        Args:
            config_id (str): The ID of the model configuration to update.
            updates (dict): A dictionary containing fields to update. Supported keys:
                - hyperparameters (dict): Key-value pairs for model hyperparameters.
                - feature_set (List[str]): List of feature names to use.
                - description (str): Description of the configuration.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - The config_id must exist.
            - Hyperparameters must be valid for the model type (e.g., learning_rate only for iterative models).
            - feature_set must be a list of strings if provided.
        """
        if config_id not in self.model_configurations:
            return { "success": False, "error": f"Model configuration with ID '{config_id}' does not exist." }

        config = self.model_configurations[config_id]
        model_type = config["model_type"]

        # Validate hyperparameters if present in updates
        if "hyperparameters" in updates:
            hyperparams = updates["hyperparameters"]
            if not isinstance(hyperparams, dict):
                return { "success": False, "error": "Hyperparameters must be a dictionary." }

            # Example validation rules based on model type
            iterative_models = ["GradientBoosting", "NeuralNetwork", "XGBoost", "AdaBoost"]
            if model_type in iterative_models:
                lr = hyperparams.get("learning_rate")
                if lr is not None:
                    if not isinstance(lr, (float, int)) or lr <= 0:
                        return { "success": False, "error": "learning_rate must be a positive number for iterative models." }
            else:
                # Check for disallowed hyperparameters in non-iterative models
                if "learning_rate" in hyperparams:
                    return { "success": False, "error": "learning_rate is not a valid hyperparameter for this model type." }

            # Additional example: n_estimators should be positive integer
            n_est = hyperparams.get("n_estimators")
            if n_est is not None and (not isinstance(n_est, int) or n_est <= 0):
                return { "success": False, "error": "n_estimators must be a positive integer." }

            # Merge valid hyperparameters
            config["hyperparameters"].update(hyperparams)

        # Validate and update feature_set
        if "feature_set" in updates:
            feature_set = updates["feature_set"]
            if not isinstance(feature_set, list) or not all(isinstance(f, str) for f in feature_set):
                return { "success": False, "error": "feature_set must be a list of strings." }
            config["feature_set"] = feature_set

        # Update description
        if "description" in updates:
            desc = updates["description"]
            if not isinstance(desc, str):
                return { "success": False, "error": "description must be a string." }
            config["description"] = desc

        # Save back to the configurations
        self.model_configurations[config_id] = config

        return { "success": True, "message": "Model configuration updated successfully." }

    def trigger_midway_evaluation(self, experiment_id: str) -> dict:
        """
        Force an evaluation at the midway point of training iterations for the given experiment if not already present.

        Args:
            experiment_id (str): The ID of the experiment.

        Returns:
            dict: {
                "success": True,
                "message": "Midway evaluation triggered for experiment <id> at iteration <midway_iter>."
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - Experiment must exist and not be 'failed' or 'completed'
            - Midway point is integer division of max observed iteration, or possibly from current_iteration if that's the best available
            - If evaluation already present for midway point, do not duplicate
        """
        # Step 1: Check experiment exists
        exp = self.experiments.get(experiment_id)
        if not exp:
            return { "success": False, "error": f"Experiment '{experiment_id}' not found." }

        if exp["status"] in ["failed", "completed"]:
            return { "success": False, "error": f"Cannot trigger evaluation for experiment status: {exp['status']}" }

        # Step 2: Find max iteration from evaluation_results for this experiment
        experiment_evals = [
            eval_info for eval_info in self.evaluation_results.values()
            if eval_info["experiment_id"] == experiment_id
        ]
        # Get highest iteration; fallback to experiment's current_iteration if no evaluations yet
        iterations = [e["iteration"] for e in experiment_evals]
        current_max_iter = max(iterations) if iterations else exp.get("current_iteration", None)

        if current_max_iter is None or current_max_iter <= 1:
            return { "success": False, "error": "Insufficient training iterations to determine midway point." }

        midway_iter = current_max_iter // 2

        # Step 3: Check if evaluation already scheduled at midway iteration
        already_exists = any(
            e["iteration"] == midway_iter for e in experiment_evals
        )
        if already_exists:
            return { "success": True, "message": f"Midway evaluation already triggered for experiment {experiment_id} at iteration {midway_iter}." }

        # Step 4: Generate evaluation_id (e.g., combine experiment_id and midway_iter)
        evaluation_id = f"{experiment_id}_midway_{midway_iter}"

        # Step 5: Create evaluation result with default metrics (empty) and current timestamp
        evaluated_at = datetime.utcnow().isoformat()
        eval_info = {
            "evaluation_id": evaluation_id,
            "experiment_id": experiment_id,
            "iteration": midway_iter,
            "metrics": {},  # Default empty metrics, to be filled in by actual evaluation
            "evaluated_at": evaluated_at
        }
        self.evaluation_results[evaluation_id] = eval_info

        return {
            "success": True,
            "message": f"Midway evaluation triggered for experiment {experiment_id} at iteration {midway_iter}."
        }

    def schedule_periodic_evaluation(self, experiment_id: str, interval_type: str, interval_value: int) -> dict:
        """
        Set up automatic evaluation logging at regular intervals (by days or iterations) for a given experiment.

        Args:
            experiment_id (str): Unique identifier of the experiment to schedule.
            interval_type (str): The basis for scheduling — must be 'days' or 'iterations'.
            interval_value (int): Positive integer indicating the frequency of evaluation.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation of schedule
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - The experiment must exist and not be in a terminal state.
            - interval_type must be 'days' or 'iterations'.
            - interval_value must be a positive integer.
            - Evaluation scheduling respects system constraints (e.g., evaluation rules).
        """
        # Validate interval_type
        if interval_type not in ['days', 'iterations']:
            return {
                "success": False,
                "error": "interval_type must be 'days' or 'iterations'"
            }

        if not isinstance(interval_value, int) or interval_value <= 0:
            return {
                "success": False,
                "error": "interval_value must be a positive integer"
            }

        # Check if experiment exists
        if experiment_id not in self.experiments:
            return {
                "success": False,
                "error": f"Experiment with ID '{experiment_id}' not found"
            }

        experiment = self.experiments[experiment_id]

        # Check if experiment is in a terminal state
        if experiment["status"] in ["completed", "failed", "cancelled"]:
            return {
                "success": False,
                "error": f"Cannot schedule evaluation: experiment is in '{experiment['status']}' state"
            }

        # Initialize scheduled_evaluations if not present (lazy initialization)
        if not hasattr(self, 'scheduled_evaluations'):
            self.scheduled_evaluations = {}

        # Store the schedule (overwrite if already exists)
        self.scheduled_evaluations[experiment_id] = {
            "interval_type": interval_type,
            "interval_value": interval_value
        }

        return {
            "success": True,
            "message": f"Periodic evaluation scheduled every {interval_value} {interval_type} for experiment '{experiment_id}'."
        }

