from typing import Dict, List, Tuple, TypedDict



class BusinessInfo(TypedDict):
    business_id: str
    name: str
    address: str
    city: str
    latitude: float
    longitude: float
    category: str
    phone: str
    website: str

class ReviewInfo(TypedDict):
    review_id: str
    business_id: str
    user_id: str
    rating: float
    text: str
    timestamp: str  # ISO format or Unix timestamp
    helpful_count: int

class UserInfo(TypedDict):
    user_id: str
    username: str
    join_date: str  # e.g., ISO format
    review_count: int
    reputation_score: int

class LocationInfo(TypedDict):
    city: str
    neighborhood: str
    coordinates_bounds: Tuple[Tuple[float, float], Tuple[float, float]]  # ((lat_min, lon_min), (lat_max, lon_max))

class OnlineLocalBusinessReviewPlatform:
    def __init__(self):
        """
        The environment for an online local business review platform.
        """

        # Businesses: {business_id: BusinessInfo}
        self.businesses: Dict[str, BusinessInfo] = {}

        # Reviews: {review_id: ReviewInfo}
        self.reviews: Dict[str, ReviewInfo] = {}

        # Users: {user_id: UserInfo}
        self.users: Dict[str, UserInfo] = {}

        # Locations: {(city, neighborhood): LocationInfo}, allows geographic filtering
        self.locations: Dict[Tuple[str, str], LocationInfo] = {}

        # Constraints reminder:
        # - Each review must be associated with an existing business and user
        # - A user cannot submit more than one review per business
        # - Business names and locations must be validated to prevent duplicates
        # - Reviews are displayed in chronological or relevance-ordered fashion by default
        # - Supports text-based and location-based search queries

    def search_business_by_name(self, name_query: str) -> dict:
        """
        Find businesses by exact or partial match on the business name (case-insensitive).

        Args:
            name_query (str): The search string to match against business names. 
                              If empty, returns all businesses.

        Returns:
            dict: {
                "success": True,
                "data": List[BusinessInfo]  # List of businesses whose name contains the query string
            }
            or
            {
                "success": False,
                "error": str  # Only if input is invalid (e.g., non-string), though type hints prevent this
            }

        Constraints:
            - This operation performs a case-insensitive substring match.
            - An empty query returns all businesses.
        """
        if not isinstance(name_query, str):
            return {"success": False, "error": "name_query must be a string"}

        query_lower = name_query.strip().lower()
        results = []

        for business_info in self.businesses.values():
            if query_lower in business_info["name"].lower():
                results.append(business_info)

        return {"success": True, "data": results}

    def search_business_by_location(self, city: str = None, neighborhood: str = None) -> dict:
        """
        Retrieve businesses located within a specified city or neighborhood.

        Args:
            city (str, optional): Name of the city to filter by.
            neighborhood (str, optional): Name of the neighborhood to filter by.

        Returns:
            dict: {
                "success": True,
                "data": List[BusinessInfo]  # List of businesses matching the location criteria (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., missing parameters or invalid location
            }

        Constraints:
            - At least one of 'city' or 'neighborhood' must be provided.
            - If neighborhood is provided, it must exist in the system (with associated bounds) unless city is also provided.
            - Only businesses in the specified city or within the neighborhood bounds are returned.

        Note:
            - If both city and neighborhood are provided, businesses must match both.
            - If only city is provided, all businesses in that city are returned.
            - If only neighborhood is provided, businesses must be within the coordinate bounds of that neighborhood.
        """
        if not city and not neighborhood:
            return { "success": False, "error": "At least one of 'city' or 'neighborhood' must be provided" }

        result: List[BusinessInfo] = []

        if neighborhood and not city:
            # Search by neighborhood only: find all location entries with this neighborhood
            matching_locations = [loc for loc in self.locations.values() if loc["neighborhood"] == neighborhood]
            if not matching_locations:
                return { "success": True, "data": [] }  # No such neighborhood, return empty list

            # For each matching neighborhood, get businesses within coordinate bounds
            for loc in matching_locations:
                bounds = loc["coordinates_bounds"]
                lat_min, lon_min = bounds[0]
                lat_max, lon_max = bounds[1]
                for business in self.businesses.values():
                    if (lat_min <= business["latitude"] <= lat_max and 
                        lon_min <= business["longitude"] <= lon_max):
                        result.append(business)
        else:
            # Case: city is provided (and possibly neighborhood)
            for business in self.businesses.values():
                if business["city"] != city:
                    continue

                if neighborhood:
                    # Check if there's a location entry for (city, neighborhood)
                    loc_key = (city, neighborhood)
                    if loc_key not in self.locations:
                        continue  # No such neighborhood in the city
                    bounds = self.locations[loc_key]["coordinates_bounds"]
                    lat_min, lon_min = bounds[0]
                    lat_max, lon_max = bounds[1]
                    if not (lat_min <= business["latitude"] <= lat_max and 
                            lon_min <= business["longitude"] <= lon_max):
                        continue

                result.append(business)

        return { "success": True, "data": result }

    def get_business_details(self, business_id: str) -> dict:
        """
        Retrieve full information about a business using its unique business_id.

        Args:
            business_id (str): The unique identifier of the business.

        Returns:
            dict: {
                "success": True,
                "data": BusinessInfo  # Full business details
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Business not found"
            }

        Constraints:
            - The business_id must refer to an existing business in the system.
        """
        if not business_id:
            return {"success": False, "error": "Business ID cannot be empty"}

        business = self.businesses.get(business_id)
        if not business:
            return {"success": False, "error": "Business not found"}

        return {"success": True, "data": business}

    def list_businesses_by_category(self, category: str) -> dict:
        """
        Retrieve all businesses filtered by the given category.

        Args:
            category (str): The category to filter businesses by (e.g., 'restaurant', 'retail').

        Returns:
            dict: {
                "success": True,
                "data": List[BusinessInfo]  # List of businesses matching the category; may be empty
            }
            or
            {
                "success": False,
                "error": str  # Description of error (e.g., invalid input)
            }

        Constraints:
            - None (query operation; no state modification).
            - Matching is exact and case-sensitive.
        """
        if not isinstance(category, str):
            return {"success": False, "error": "Category must be a string."}

        result = [
            business_info for business_info in self.businesses.values()
            if business_info["category"] == category
        ]

        return {"success": True, "data": result}

    def get_reviews_for_business(self, business_id: str) -> dict:
        """
        Retrieve all reviews associated with a given business_id.

        Args:
            business_id (str): The unique identifier of the business.

        Returns:
            dict: {
                "success": bool,
                "data": List[ReviewInfo]  # List of reviews for the business; empty if none exist
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Business not found"
            }

        Constraints:
            - The business_id must correspond to an existing business.
            - Reviews are returned as-is; no default sorting is enforced by this method.
        """
        if business_id not in self.businesses:
            return {"success": False, "error": "Business not found"}

        matching_reviews = [
            review for review in self.reviews.values()
            if review["business_id"] == business_id
        ]

        return {"success": True, "data": matching_reviews}

    def get_reviews_by_user(self, user_id: str) -> dict:
        """
        Retrieve all reviews submitted by a specific user.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": bool,
                "data": List[ReviewInfo]  # List of reviews by the user, empty if none
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., user not found
            }

        Constraints:
            - The user must exist in the system.
            - Each returned review must be associated with the given user_id.
        """
        if user_id not in self.users:
            return {"success": False, "error": "User does not exist"}

        user_reviews = [
