    def search_business_by_coordinates(
        self,
        lat_min: float,
        lat_max: float,
        lon_min: float,
        lon_max: float
    ) -> dict:
        """
        Find businesses within a geographic bounding box defined by latitude and longitude bounds.

        Args:
            lat_min (float): Minimum latitude (inclusive).
            lat_max (float): Maximum latitude (inclusive).
            lon_min (float): Minimum longitude (inclusive).
            lon_max (float): Maximum longitude (inclusive).

        Returns:
            dict: {
                "success": True,
                "data": List[BusinessInfo]  # List of businesses within the bounding box
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., invalid bounds
            }

        Constraints:
            - The coordinate bounds must be valid (min <= max for both lat and lon).
            - Only businesses with valid coordinates are considered.
        """
        # Validate coordinate bounds
        if lat_min > lat_max:
            return {"success": False, "error": "Invalid latitude bounds: lat_min > lat_max"}
        if lon_min > lon_max:
            return {"success": False, "error": "Invalid longitude bounds: lon_min > lon_max"}

        result = []
        for business in self.businesses.values():
            lat = business["latitude"]
            lon = business["longitude"]
            if lat_min <= lat <= lat_max and lon_min <= lon <= lon_max:
                result.append(business)

        return {"success": True, "data": result}

    def get_top_reviews_by_helpful_count(self, business_id: str) -> dict:
        """
        Retrieve the most helpful reviews for a given business, sorted by helpful_count in descending order.

        Args:
