        Returns:
            dict: {
                "success": True,
                "data": List[ReviewInfo]  # Reviews sorted by helpful_count descending (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Business does not exist"
            }

        Constraints:
            - The business_id must correspond to an existing business.
            - Reviews are sorted by helpful_count in descending order.
        """
        if business_id not in self.businesses:
            return {"success": False, "error": "Business does not exist"}

        # Filter reviews for the given business_id
        filtered_reviews = [
            review for review in self.reviews.values()
            if review["business_id"] == business_id
        ]

        # Sort by helpful_count descending
        sorted_reviews = sorted(filtered_reviews, key=lambda r: r["helpful_count"], reverse=True)

        return {"success": True, "data": sorted_reviews}

    def list_location_areas(self) -> dict:
