class FootballLeagueSchedulingSystem:
    def __init__(self):
        """
        Environment for managing football league schedules, teams, and fixtures.
        """
        # Leagues: {league_id: LeagueInfo}
        self.leagues: Dict[str, LeagueInfo] = {}

        # Teams: {team_id: TeamInfo}
        self.teams: Dict[str, TeamInfo] = {}

        # Fixtures: {match_id: FixtureInfo}
        self.fixtures: Dict[str, FixtureInfo] = {}

        # Venues: {venue_id: VenueInfo}
        self.venues: Dict[str, VenueInfo] = {}

        # Constraints reminder:
        # - A fixture must involve two distinct teams from the same league.
        # - Fixture match_date must fall within the league’s season_start_date and season_end_date.
        # - A team can belong to only one league at a time during a season.
        # - No two fixtures can be scheduled at the same venue at the same time.
        # - Leagues with season_start_date in the future are labeled as "upcoming".


    def get_upcoming_leagues(self) -> dict:
        """
        Retrieve all leagues that are marked as "upcoming" and have a season_start_date in the future.

        Returns:
            dict: {
                "success": True,
                "data": List[LeagueInfo]  # List of leagues with status "upcoming" and future start date
            }

        Note:
            - Only leagues with status "upcoming" AND season_start_date > today are returned.
            - Date comparison uses ISO-formatted strings (e.g., "2024-08-01"), which are lexicographically comparable.
            - No input parameters; operates on the entire state.
        """
        try:
            current_date = date.today().isoformat()

            upcoming_leagues = []
            for league in self.leagues.values():
                if (
                    league["status"] == "upcoming"
                    and league["season_start_date"] > current_date
                ):
                    upcoming_leagues.append(league)

            return { "success": True, "data": upcoming_leagues }
        except Exception as e:
            # Although unlikely, catch any unforeseen errors (e.g., date format issues)
            return { "success": False, "error": f"An internal error occurred: {str(e)}" }


    def get_active_leagues(self) -> dict:
        """
        Retrieve all leagues where the current date falls between season_start_date and season_end_date (inclusive).

        Returns:
            dict: {
                "success": True,
                "data": List[LeagueInfo]  # List of leagues currently active
            }
            or in case of no matches (empty list is valid):
            {
                "success": True,
                "data": []
            }

        Note:
            This method determines active status based on the current system date and the league's
            season_start_date and season_end_date. It does not rely solely on the stored 'status'
            field to ensure up-to-date results.

        Constraints:
            - A league is active if: season_start_date <= today <= season_end_date.
        """
        try:
            current_date = datetime.now().date()
            active_leagues = []

            for league in self.leagues.values():
                start_date = datetime.fromisoformat(league["season_start_date"]).date()
                end_date = datetime.fromisoformat(league["season_end_date"]).date()

                if start_date <= current_date <= end_date:
                    active_leagues.append(league)

            return { "success": True, "data": active_leagues }
        except Exception as e:
            # Though unlikely, handle any unexpected parsing or runtime issues gracefully
            return { "success": False, "error": f"Failed to retrieve active leagues: {str(e)}" }


    def get_completed_leagues(self) -> dict:
        """
        Retrieve all leagues where the season_end_date has passed, indicating the league is completed.

        Returns:
            dict: {
                "success": True,
                "data": List[LeagueInfo]  # List of leagues with season_end_date before today
            }

        Constraints:
            - A league is considered completed if its season_end_date is earlier than the current date.
            - Date comparison is based on ISO-formatted date strings (assumed as 'YYYY-MM-DD').
        """
        try:
            current_date_str = datetime.today().strftime("%Y-%m-%d")
            completed_leagues = []

            for league in self.leagues.values():
                if league["season_end_date"] < current_date_str:
                    completed_leagues.append(league)

            return { "success": True, "data": completed_leagues }
        except Exception as e:
            return { "success": False, "error": f"Failed to retrieve completed leagues: {str(e)}" }

    def get_league_by_id(self, league_id: str) -> dict:
        """
        Retrieve full details of a league using its league_id.

        Args:
            league_id (str): The unique identifier of the league.

        Returns:
            dict: {
                "success": True,
                "data": LeagueInfo  # Dictionary containing league details
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "League not found"
            }

        Constraints:
            - The league_id must correspond to an existing league in the system.
        """
        if not league_id:
            return {"success": False, "error": "Invalid input: league_id cannot be empty"}

        league = self.leagues.get(league_id)
        if league is None:
            return {"success": False, "error": "League not found"}

        return {"success": True, "data": league}

    def get_team_by_id(self, team_id: str) -> dict:
        """
        Retrieve team information (name, city, roster, league_id) by team_id.

        Args:
            team_id (str): The unique identifier of the team.

        Returns:
            dict: {
                "success": True,
                "data": TeamInfo  # Full team information
            }
            or
            {
                "success": False,
                "error": str  # "Team not found"
            }

        Constraints:
