        """
        team_info = self.teams.get(team_id)
        if not team_info:
            return {"success": False, "error": "Team not found"}

        return {"success": True, "data": team_info}

    def get_team_by_name(self, team_name: str) -> dict:
        """
        Retrieve team information by exact team name match. May return multiple teams if names are not unique.

        Args:
            team_name (str): The name of the team to search for.

        Returns:
            dict: {
                "success": True,
                "data": List[TeamInfo]  # List of teams with matching name (can be empty)
            }

        Note:
            - Performs exact string match on team name.
            - Returns all teams matching the name (in case names are not globally unique).
            - Does not raise an error if no team is found; returns empty list.

        Constraints:
            - Team membership in leagues is respected in data, but not enforced here.
        """
        if not isinstance(team_name, str):
            return { "success": False, "error": "team_name must be a string" }

        result = [
            team_info for team_info in self.teams.values()
            if team_info["name"] == team_name
        ]

        return { "success": True, "data": result }

    def list_teams_in_league(self, league_id: str) -> dict:
        """
        Retrieve all teams participating in a given league.

        Args:
            league_id (str): The unique identifier of the league.

        Returns:
            dict: {
                "success": True,
                "data": List[TeamInfo]  # List of teams in the league (can be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., "League not found"
            }

        Constraints:
            - The league must exist in the system.
            - Teams are matched by their league_id attribute.
        """
        if league_id not in self.leagues:
            return {"success": False, "error": "League not found"}

        teams_in_league = [
            team_info for team_info in self.teams.values()
            if team_info["league_id"] == league_id
        ]

        return {"success": True, "data": teams_in_league}

    def get_fixture_by_id(self, match_id: str) -> dict:
        """
        Retrieve detailed information about a specific match using its match_id.

        Args:
            match_id (str): The unique identifier of the fixture to retrieve.

        Returns:
            dict: {
                "success": True,
                "data": FixtureInfo  # The complete fixture information
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Fixture not found"
            }

        Constraints:
            - The match_id must correspond to an existing fixture.
        """
        if not match_id:
            return {"success": False, "error": "match_id cannot be empty"}

        fixture = self.fixtures.get(match_id)
        if fixture is None:
            return {"success": False, "error": "Fixture not found"}

        return {"success": True, "data": fixture}

    def get_fixtures_by_date(self, target_date: str) -> dict:
        """
        Retrieve all fixtures scheduled on a specific date.

        Args:
            target_date (str): The date in ISO format (e.g., "2024-12-10") to query fixtures for.

        Returns:
            dict: {
                "success": True,
                "data": List[FixtureInfo]  # List of fixtures where match_date starts with or equals target_date
            }
            or
            {
                "success": False,
                "error": str  # Description if input is invalid (e.g., empty date)
            }

        Constraints:
            - The target_date should be a valid date string in 'YYYY-MM-DD' format.
            - Matches are based on the date portion of match_date (supports full datetime strings).
        """
        if not target_date or not isinstance(target_date, str):
            return { "success": False, "error": "Invalid input: target_date must be a non-empty string" }

        result = []
        for fixture in self.fixtures.values():
            match_date = fixture["match_date"]
            # Match if match_date starts with the target_date (handles both date and datetime)
            if match_date.startswith(target_date):
                result.append(fixture)

        return { "success": True, "data": result }

    def get_fixtures_by_league(self, league_id: str) -> dict:
        """
