    def check_venue_availability(self, venue_id: str, match_date: str) -> dict:
        """
        Check if a venue is free at the specified match date and time to prevent scheduling conflicts.

        Args:
            venue_id (str): The unique identifier of the venue.
            match_date (str): The date and time (in ISO format) for which availability is checked.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "available": bool,           # True if no conflicting fixture exists
                    "conflicting_match_id": str or None  # match_id of conflicting fixture, or None
                }
            }
            or
            {
                "success": False,
                "error": str  # Explanation, e.g., "Venue does not exist"
            }

        Constraints:
            - Only considers fixtures with status "scheduled".
            - A venue is unavailable if another scheduled match exists at the same time.
        """
        if venue_id not in self.venues:
            return {"success": False, "error": "Venue does not exist"}

        # Normalize input match_date (assume already ISO format; no parsing validation)
        for match_id, fixture in self.fixtures.items():
            if (
                fixture["venue"] == venue_id
                and fixture["match_date"] == match_date
                and fixture["status"] == "scheduled"
            ):
                return {
                    "success": True,
                    "data": {
                        "available": False,
                        "conflicting_match_id": match_id
                    }
                }

        # No conflict found
        return {
            "success": True,
            "data": {
                "available": True,
                "conflicting_match_id": None
            }
        }

    def check_teams_in_same_league(self, team_id_1: str, team_id_2: str) -> dict:
        """
        Verify whether two teams belong to the same league, which is a prerequisite for scheduling a fixture.

        Args:
            team_id_1 (str): The ID of the first team.
            team_id_2 (str): The ID of the second team.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "same_league": bool  # True if both teams belong to the same league, False otherwise
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Team not found"
            }

        Constraints:
            - Both teams must exist in the system.
            - Relies on the integrity of team->league_id mapping.
        """
        if team_id_1 not in self.teams:
            return { "success": False, "error": f"Team with ID '{team_id_1}' not found" }

        if team_id_2 not in self.teams:
            return { "success": False, "error": f"Team with ID '{team_id_2}' not found" }

        league_id_1 = self.teams[team_id_1]["league_id"]
        league_id_2 = self.teams[team_id_2]["league_id"]

        same_league = league_id_1 == league_id_2

        return { "success": True, "data": { "same_league": same_league } }


    def add_league(
        self,
        league_id: str,
        name: str,
        country: str,
        season_start_date: str,
        season_end_date: str
    ) -> dict:
        """
        Add a new league to the system with defined start and end dates.
        The status is set automatically:
        - "upcoming" if season_start_date is in the future.
        - "active" if current date is within the season.
        - "completed" if season_end_date is in the past.

        Args:
            league_id (str): Unique identifier for the league.
            name (str): Name of the league.
            country (str): Country where the league is organized.
            season_start_date (str): Start date in ISO format (e.g., "2024-08-01").
            season_end_date (str): End date in ISO format.

        Returns:
            dict: { "success": True, "message": "League added successfully." }
                  or { "success": False, "error": "reason" }

        Constraints:
            - league_id must be unique.
            - season_start_date must be <= season_end_date.
            - status is determined by current date relative to season dates.
        """
        # Check if league_id already exists
        if league_id in self.leagues:
            return { "success": False, "error": f"League with id '{league_id}' already exists." }

        # Validate date format and logical order
        try:
            start = datetime.fromisoformat(season_start_date)
            end = datetime.fromisoformat(season_end_date)
        except ValueError as e:
            return { "success": False, "error": f"Invalid date format: {str(e)}" }

        if start > end:
            return { "success": False, "error": "Season start date must be before or equal to end date." }

        # Determine status based on current date
        now = datetime.now()
        if start > now:
            status = "upcoming"
        elif end < now:
            status = "completed"
        else:
            status = "active"

        # Create new league entry
        self.leagues[league_id] = LeagueInfo(
            league_id=league_id,
            name=name,
            country=country,
            season_start_date=season_start_date,
            season_end_date=season_end_date,
            status=status
        )

        return { "success": True, "message": "League added successfully." }


    def update_league_status(self, league_id: str) -> dict:
        """
        Automatically update the status of a league based on current date relative to its season dates.

        Args:
            league_id (str): The ID of the league to update.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Describes the new status or failure reason
            }

        Constraints:
            - Status is determined by comparing the current date with season_start_date and season_end_date.
            - If season_start_date > today: status = "upcoming"
            - If season_start_date <= today <= season_end_date: status = "active"
            - If today > season_end_date: status = "completed"
        """
        if league_id not in self.leagues:
            return { "success": False, "error": "League not found" }

        league = self.leagues[league_id]
        start_date = league["season_start_date"]
        end_date = league["season_end_date"]

        # Get current date (in simulation, use today's date in ISO format)
        today = datetime.today().strftime('%Y-%m-%d')

        # Determine new status
        if today < start_date:
            new_status = "upcoming"
        elif start_date <= today <= end_date:
            new_status = "active"
        else:  # today > end_date
            new_status = "completed"

        # Update the league status
        league["status"] = new_status

        return {
            "success": True,
            "message": f"League status updated to {new_status}"
        }

    def add_team(
        self,
        team_id: str,
        name: str,
        city: str,
        league_id: str,
        roster: List[str]
    ) -> dict:
        """
        Register a new team and assign it to a league, ensuring it belongs to only one league per season.

        Args:
            team_id (str): Unique identifier for the team.
            name (str): Name of the team.
            city (str): Home city of the team.
            league_id (str): ID of the league to assign the team to.
            roster (List[str]): List of player names or IDs.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or {
                "success": bool,
                "error": str  # On failure
            }

        Constraints:
            - team_id must be unique.
            - league_id must refer to an existing league.
            - A team can belong to only one league at a time (enforced by unique team_id).
            - All input fields must be valid.
        """
        # Validate inputs
        if not team_id:
            return {"success": False, "error": "team_id is required"}
        if not name:
            return {"success": False, "error": "name is required"}
        if not city:
            return {"success": False, "error": "city is required"}
        if not league_id:
            return {"success": False, "error": "league_id is required"}
        if not isinstance(roster, list):
            return {"success": False, "error": "roster must be a list"}

        # Check if team_id already exists
        if team_id in self.teams:
            return {"success": False, "error": "Team with this team_id already exists"}

        # Check if league exists
        if league_id not in self.leagues:
            return {"success": False, "error": "League does not exist"}

        # Create new team
        team: TeamInfo = {
            "team_id": team_id,
            "name": name,
            "city": city,
            "league_id": league_id,
            "roster": roster.copy()  # Store a copy to prevent external mutation
        }

        self.teams[team_id] = team

        return {"success": True, "message": "Team added successfully."}

    def update_team_roster(self, team_id: str, new_roster: List[str]) -> dict:
        """
        Modify the list of players in a team's roster.

        Args:
            team_id (str): The unique identifier of the team.
            new_roster (List[str]): The new list of player names or IDs to set as the team's roster.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": bool,
                "error": str  # On failure
            }

        Constraints:
            - The team must exist in the system.
            - new_roster must be a list of strings.

        Note:
            An empty roster is allowed (e.g., during team setup or off-season).
        """
        if not isinstance(new_roster, list):
            return { "success": False, "error": "new_roster must be a list of strings" }

        if not all(isinstance(player, str) for player in new_roster):
            return { "success": False, "error": "All roster entries must be strings" }

        if team_id not in self.teams:
            return { "success": False, "error": "Team not found" }

        self.teams[team_id]["roster"] = new_roster

        return {
            "success": True,
            "message": f"Roster updated successfully for team {team_id}."
        }

    def assign_team_to_league(self, team_id: str, league_id: str) -> dict:
        """
        Assign a team to a league, ensuring the team belongs to only one league at a time.
        If the team is already in a league, it will be reassigned to the new one.

        Args:
            team_id (str): The unique identifier of the team.
            league_id (str): The unique identifier of the league to assign the team to.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The league must exist.
            - The team must exist.
            - A team can belong to only one league at a time (enforced via single league_id).
        """
        if league_id not in self.leagues:
            return {
                "success": False,
                "error": f"League '{league_id}' does not exist."
            }

        if team_id not in self.teams:
            return {
                "success": False,
                "error": f"Team '{team_id}' does not exist."
            }

        # Update the team's league membership
        self.teams[team_id]["league_id"] = league_id

        return {
            "success": True,
            "message": f"Team '{team_id}' assigned to league '{league_id}'."
        }

    def add_fixture(
        self,
        match_id: str,
        league_id: str,
        home_team_id: str,
        away_team_id: str,
        venue: str,
        match_date: str
    ) -> dict:
        """
        Schedule a new match (fixture) between two teams with full validation.

        Args:
            match_id (str): Unique identifier for the match.
            league_id (str): ID of the league the match belongs to.
            home_team_id (str): ID of the home team.
            away_team_id (str): ID of the away team.
            venue (str): ID of the venue where the match will be played.
            match_date (str): ISO-formatted date/time string for the match (e.g., "2024-09-01T15:00:00").

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            } or {
                "success": False,
                "error": str  # On failure
            }

        Constraints enforced:
            - Teams must be distinct and in the same league.
            - Match date must be within the league's season.
            - Venue must exist and not have a scheduling conflict.
            - Match ID must be unique.
        """
        # Check if fixture ID already exists
        if match_id in self.fixtures:
            return {"success": False, "error": f"Fixture with match_id '{match_id}' already exists"}

        # Check if league exists
        if league_id not in self.leagues:
            return {"success": False, "error": f"League with ID '{league_id}' does not exist"}

        league = self.leagues[league_id]
        season_start = league["season_start_date"]
        season_end = league["season_end_date"]

        # Validate match_date is within season
        if match_date < season_start or match_date > season_end:
            return {
                "success": False,
                "error": f"Match date '{match_date}' is outside the league season ({season_start} to {season_end})"
            }

        # Check if home and away teams exist and are distinct
        if home_team_id == away_team_id:
            return {"success": False, "error": "Home and away teams must be different"}

        if home_team_id not in self.teams:
            return {"success": False, "error": f"Home team with ID '{home_team_id}' does not exist"}
        if away_team_id not in self.teams:
            return {"success": False, "error": f"Away team with ID '{away_team_id}' does not exist"}

        home_team = self.teams[home_team_id]
        away_team = self.teams[away_team_id]

        # Check both teams belong to the same league
        if home_team["league_id"] != league_id:
            return {"success": False, "error": f"Home team '{home_team_id}' does not belong to league '{league_id}'"}
        if away_team["league_id"] != league_id:
            return {"success": False, "error": f"Away team '{away_team_id}' does not belong to league '{league_id}'"}

        # Check if venue exists
        if venue not in self.venues:
            return {"success": False, "error": f"Venue with ID '{venue}' does not exist"}

        # Check for venue conflict: no other fixture at the same venue and same match_date
        for fixture in self.fixtures.values():
            if fixture["venue"] == venue and fixture["match_date"] == match_date:
                return {
                    "success": False,
                    "error": f"Venue '{venue}' is already booked at '{match_date}'"
                }

        # All checks passed: create the fixture
        new_fixture: FixtureInfo = {
            "match_id": match_id,
            "league_id": league_id,
            "home_team_id": home_team_id,
            "away_team_id": away_team_id,
            "venue": venue,
            "match_date": match_date,
            "status": "scheduled"
        }

        self.fixtures[match_id] = new_fixture

        return {"success": True, "message": "Fixture added successfully"}

    def update_fixture_status(self, match_id: str, new_status: str) -> dict:
        """
        Update the status of an existing fixture (e.g., from "scheduled" to "completed").

        Args:
            match_id (str): The unique identifier of the fixture to update.
            new_status (str): The new status to assign to the fixture (e.g., "completed", "postponed").

        Returns:
            dict: {
                "success": True,
                "message": "Fixture status updated successfully."
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Fixture not found" or "Invalid status"
            }

        Constraints:
            - The match_id must exist in the system.
            - The new_status must be a non-empty string.
        """
        if not match_id:
            return { "success": False, "error": "Match ID is required" }

        if match_id not in self.fixtures:
            return { "success": False, "error": "Fixture not found" }

        if not new_status or not isinstance(new_status, str) or new_status.strip() == "":
            return { "success": False, "error": "New status must be a non-empty string" }

        new_status = new_status.strip()

        # Update the fixture status
        self.fixtures[match_id]["status"] = new_status

        return { "success": True, "message": "Fixture status updated successfully." }

    def reschedule_fixture(
        self,
        match_id: str,
        new_match_date: str = None,
        new_venue: str = None
    ) -> dict:
        """
        Change the match_date or venue of an existing fixture, revalidating all constraints.

        Args:
            match_id (str): The ID of the fixture to reschedule.
            new_match_date (str, optional): The new match date/time in ISO format (e.g., "2024-08-10T15:00:00").
            new_venue (str, optional): The new venue_id for the fixture.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            } or {
                "success": False,
                "error": str  # Description of validation failure
            }

        Constraints Enforced:
            - Fixture must have distinct home and away teams from the same league.
            - New match_date must be within the league's season dates.
            - New venue must be available at the new match_date.
            - New venue must exist.
            - At least one of new_match_date or new_venue must be provided.
        """
        # Check if fixture exists
        if match_id not in self.fixtures:
            return {"success": False, "error": "Fixture not found"}

        fixture = self.fixtures[match_id]

        # At least one update must be provided
        if new_match_date is None and new_venue is None:
            return {"success": False, "error": "No changes provided: specify new_match_date or new_venue"}

        league_id = fixture["league_id"]
        home_team_id = fixture["home_team_id"]
        away_team_id = fixture["away_team_id"]
        current_date = fixture["match_date"]
        current_venue = fixture["venue"]

        # Use new values or fallback to current ones
        final_date = new_match_date if new_match_date is not None else current_date
        final_venue = new_venue if new_venue is not None else current_venue

        # Validate league exists
        if league_id not in self.leagues:
            return {"success": False, "error": "League for the fixture not found"}

        league = self.leagues[league_id]

        # Check distinct teams
        if home_team_id == away_team_id:
            return {"success": False, "error": "Fixture must involve two distinct teams"}

        # Check both teams belong to the same league
        if (
            home_team_id not in self.teams or
            self.teams[home_team_id]["league_id"] != league_id
        ):
            return {"success": False, "error": "Home team not found or not in the specified league"}

        if (
            away_team_id not in self.teams or
            self.teams[away_team_id]["league_id"] != league_id
        ):
            return {"success": False, "error": "Away team not found or not in the specified league"}

        # Validate match date is within season
        if final_date < league["season_start_date"] or final_date > league["season_end_date"]:
            return {
                "success": False,
                "error": f"Match date {final_date} is outside the league season: "
                         f"{league['season_start_date']} to {league['season_end_date']}"
            }

        # Validate venue exists
        if final_venue not in self.venues:
            return {"success": False, "error": f"Venue {final_venue} not found"}

        # Check venue availability at the new time (only if rescheduling to a new time or venue)
        for match in self.fixtures.values():
            if (
                match["match_id"] != match_id and  # Not the same fixture
                match["venue"] == final_venue and
                match["match_date"] == final_date
            ):
                return {
                    "success": False,
                    "error": f"Venue {final_venue} is already booked at {final_date}"
                }

        # All checks passed: update the fixture
        self.fixtures[match_id]["match_date"] = final_date
        self.fixtures[match_id]["venue"] = final_venue

        return {"success": True, "message": "Fixture rescheduled successfully."}

    def cancel_fixture(self, match_id: str) -> dict:
        """
        Mark a fixture as cancelled by updating its status to 'cancelled'.

        Args:
            match_id (str): The unique identifier of the fixture to cancel.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Describes outcome on success
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. fixture not found
            }

        Constraints:
            - The fixture must exist in the system.
            - No additional validation (e.g., date, venue) is required for cancellation.
            - This operation is idempotent (cancelling an already-cancelled fixture is allowed).
        """
        if match_id not in self.fixtures:
            return { "success": False, "error": "Fixture not found" }

        self.fixtures[match_id]["status"] = "cancelled"

        return { "success": True, "message": f"Fixture '{match_id}' has been cancelled." }

    def add_venue(
        self,
        venue_id: str,
        name: str,
        city: str,
        capacity: int,
        home_team_id: str = None
    ) -> dict:
        """
        Add a new venue to the system, optionally linking it to a home team.

        Args:
            venue_id (str): Unique identifier for the venue.
            name (str): Name of the venue.
            city (str): City where the venue is located.
            capacity (int): Seating capacity of the venue (must be positive).
            home_team_id (str, optional): ID of the team for which this is a home venue.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - venue_id must be unique.
            - If home_team_id is provided, it must exist in the system.
            - Capacity must be a positive integer.
            - Name and city must be non-empty strings.
        """
        # Validate inputs
        if not venue_id or not isinstance(venue_id, str):
            return {"success": False, "error": "venue_id is required and must be a non-empty string"}
        if not name or not isinstance(name, str):
            return {"success": False, "error": "name is required and must be a non-empty string"}
        if not city or not isinstance(city, str):
            return {"success": False, "error": "city is required and must be a non-empty string"}
        if not isinstance(capacity, int) or capacity <= 0:
            return {"success": False, "error": "capacity must be a positive integer"}

        # Check if venue_id already exists
        if venue_id in self.venues:
            return {"success": False, "error": f"Venue with venue_id '{venue_id}' already exists"}

        # If home_team_id is provided, check that it exists
        if home_team_id is not None:
            if home_team_id not in self.teams:
                return {"success": False, "error": f"Team with team_id '{home_team_id}' does not exist"}

        # Create new venue entry
        venue_info: VenueInfo = {
            "venue_id": venue_id,
            "name": name,
            "city": city,
            "capacity": capacity,
            "home_team_id": home_team_id
        }

        self.venues[venue_id] = venue_info

        return {"success": True, "message": "Venue added successfully"}

    def update_venue_capacity(self, venue_id: str, new_capacity: int) -> dict:
        """
        Modify the seating capacity of a specified venue.

        Args:
            venue_id (str): The unique identifier of the venue.
            new_capacity (int): The new seating capacity; must be non-negative.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - The venue must exist in the system.
            - The new capacity must be a non-negative integer.
        """
        if venue_id not in self.venues:
            return { "success": False, "error": "Venue does not exist" }

        if new_capacity < 0:
            return { "success": False, "error": "Capacity must be non-negative" }

        self.venues[venue_id]["capacity"] = new_capacity

        return { "success": True, "message": "Venue capacity updated successfully." }

