from typing import Dict, List, TypedDict
import time
from typing import Any, List, Dict as TypedDict



class UserInfo(TypedDict):
    _id: str
    username: str
    bio: str
    profile_image: str
    follower_count: int
    following_count: int
    account_type: str  # corrected from 'account_typ'

class ContentInfo(TypedDict):
    content_id: str
    user_id: str
    content_type: str  # one of: "image", "video", "reel"
    media_url: str
    caption: str
    timestamp: float  # Unix timestamp or ISO format as float
    like_count: int
    comment_count: int
    share_count: int
    view_count: int  # corrected from 'view_coun'

class ContentFeedInfo(TypedDict):
    feed_id: str
    user_id: str
    content_list: List[str]  # list of content_id strings
    refresh_timestamp: float
    filter_criteria: dict  # flexible filtering params (e.g., {"type": "reel", "source": "following"})

class SocialMediaContentPlatform:
    def __init__(self):
        """
        A social media content platform (Instagram-like) managing users, content, and dynamic feeds.
        """

        # Users: {_id: UserInfo}
        self.users: Dict[str, UserInfo] = {}

        # Content: {content_id: ContentInfo}
        self.content: Dict[str, ContentInfo] = {}

        # ContentFeeds: {feed_id: ContentFeedInfo}
        self.feeds: Dict[str, ContentFeedInfo] = {}

        # Supported content types
        self.supported_content_types: List[str] = ["image", "video", "reel"]

        # Constraints reminder:
        # - Only publicly posted content or content from followed users can be retrieved
        # - Content must be sorted in descending order by timestamp (latest first)
        # - Each content item must be associated with a valid user_id
        # - content_type must be one of: "image", "video", "reel"
        # - Retrieval operations must support pagination (e.g., limit=5)

    def get_user_by_id(self, user_id: str) -> dict:
        """
        Retrieve user profile information using their unique user ID.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": UserInfo  # Full user profile information
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. "User not found"
            }

        Constraints:
            - The user_id must correspond to an existing user.
            - Only publicly accessible user profile data is returned.
        """
        if not user_id:
            return {"success": False, "error": "Invalid input: user_id cannot be empty"}

        user_info = self.users.get(user_id)
        if not user_info:
            return {"success": False, "error": "User not found"}

        return {"success": True, "data": user_info}

    def get_user_by_username(self, username: str) -> dict:
        """
        Retrieve user information by username.

        Args:
            username (str): The username of the user to retrieve.

        Returns:
            dict: {
                "success": True,
                "data": UserInfo  # The full user information
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., "User not found"
            }

        Constraints:
            - Username must exactly match an existing user (case-sensitive).
            - Only one user is expected per username.
        """
        for user_info in self.users.values():
            if user_info["username"] == username:
                return {"success": True, "data": user_info}
        return {"success": False, "error": "User not found"}

    def list_user_content(self, user_id: str) -> dict:
        """
        Retrieve all content posted by a specific user, sorted from latest to earliest.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": List[ContentInfo]  # List of content items, sorted by timestamp (descending)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "User not found"
            }

        Constraints:
            - Only content associated with a valid user_id is returned.
            - Content is sorted in descending order by timestamp (latest first).
            - All content types (image, video, reel) are included.
        """
        # Check if the user exists
        if user_id not in self.users:
            return {"success": False, "error": "User not found"}

        # Filter content by user_id
        user_content = [
            content_info for content_info in self.content.values()
            if content_info["user_id"] == user_id
        ]

        # Sort content by timestamp in descending order (latest first)
        user_content.sort(key=lambda x: x["timestamp"], reverse=True)

        return {"success": True, "data": user_content}

    def list_user_content_by_type(self, user_id: str, content_type: str) -> dict:
        """
        Retrieve all content from a specific user filtered by content_type (e.g., "reel").

        Args:
            user_id (str): The ID of the user whose content is to be retrieved.
            content_type (str): The type of content to filter by. Must be one of:
                               ["image", "video", "reel"].

        Returns:
            dict: {
                "success": True,
                "data": List[ContentInfo]  # List of content sorted by timestamp (latest first)
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - user_id must exist.
            - content_type must be one of the supported types.
            - Resulting list is sorted in descending order by timestamp.
        """
        # Validate user_id
        if user_id not in self.users:
            return {"success": False, "error": "User does not exist"}

        # Validate content_type
        if content_type not in self.supported_content_types:
            return {
                "success": False,
                "error": f"Unsupported content_type. Supported types: {self.supported_content_types}"
            }

        # Filter content by user_id and content_type
        filtered_content = [
            content_info for content_info in self.content.values()
            if content_info["user_id"] == user_id and content_info["content_type"] == content_type
        ]

        # Sort by timestamp in descending order (latest first)
        sorted_content = sorted(filtered_content, key=lambda x: x["timestamp"], reverse=True)

        return {"success": True, "data": sorted_content}

    def get_latest_content(self, user_id: str) -> dict:
        """
        Retrieve the most recent content items from a user, sorted by timestamp in descending order.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": bool,
                "data": List[ContentInfo]  # Sorted list of content (latest first), may be empty
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., "User not found"
            }

        Constraints:
            - Only content associated with a valid user_id is considered.
            - Result is sorted in descending order by timestamp.
            - All content items must have valid timestamps.
        """
        if user_id not in self.users:
            return {"success": False, "error": "User not found"}

        # Filter content by user_id
        user_content = [
            content for content in self.content.values()
            if content["user_id"] == user_id
        ]

        # Sort in descending order by timestamp (latest first)
        sorted_content = sorted(user_content, key=lambda x: x["timestamp"], reverse=True)

        return {"success": True, "data": sorted_content}

    def get_latest_content_with_limit(self, user_id: str, limit: int) -> dict:
        """
        Retrieve the latest content from a user, sorted by timestamp in descending order, up to a specified limit.

        Args:
            user_id (str): The ID of the user whose content is to be retrieved.
            limit (int): The maximum number of latest content items to return (must be >= 1).

        Returns:
            dict: {
                "success": bool,
                "data": List[ContentInfo]  # Sorted list of content (may be empty)
            }
            or
            {
                "success": False,
                "error": str
            }

        Constraints:
            - The user_id must exist.
            - Content is sorted by timestamp (latest first).
            - Only up to 'limit' items are returned.
            - 'limit' must be a positive integer.
        """
        if not isinstance(limit, int) or limit < 1:
            return { "success": False, "error": "Limit must be a positive integer." }

        if user_id not in self.users:
            return { "success": False, "error": "User not found." }

        # Filter content by user_id
        user_content = [
            content for content in self.content.values()
            if content["user_id"] == user_id
        ]

        # Sort by timestamp descending (latest first)
        sorted_content = sorted(user_content, key=lambda x: x["timestamp"], reverse=True)

        # Apply limit
        result = sorted_content[:limit]

        return { "success": True, "data": result }

    def filter_content_by_type_and_limit(self, content_type: str, limit: int) -> dict:
        """
        Retrieve the latest content items filtered by content type and limited in number.

        Args:
            content_type (str): The type of content to filter by. Must be one of: 
                               ["image", "video", "reel"].
            limit (int): Maximum number of content items to return. Must be a positive integer.

        Returns:
            dict: {
                "success": bool,
                "data": List[ContentInfo]  # List of content sorted by timestamp (newest first),
                                           # up to 'limit' items (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of validation or processing error
            }

        Constraints:
            - content_type must be one of the supported types.
            - limit must be a positive integer.
            - Results are sorted by timestamp in descending order (latest first).
            - The number of results does not exceed 'limit'.
        """
        # Validate content_type
        if content_type not in self.supported_content_types:
            return {
                "success": False,
                "error": f"Unsupported content_type: '{content_type}'. Supported types: {self.supported_content_types}"
            }

        # Validate limit
        if not isinstance(limit, int) or limit <= 0:
            return {
                "success": False,
                "error": "Limit must be a positive integer."
            }

        # Filter content by content_type
        filtered_content = [
            content for content in self.content.values()
            if content["content_type"] == content_type
        ]

        # Sort by timestamp descending (newest first)
        sorted_content = sorted(filtered_content, key=lambda c: c["timestamp"], reverse=True)

        # Apply limit
        result = sorted_content[:limit]

        return {
            "success": True,
            "data": result
        }

    def get_content_by_id(self, content_id: str) -> dict:
        """
        Retrieve full details of a specific content item by its unique content_id.

        Args:
            content_id (str): The unique identifier of the content.

        Returns:
            dict: {
                "success": True,
                "data": ContentInfo  # Full content metadata
            }
            or
            {
                "success": False,
                "error": "Content not found"
            }

        Constraints:
            - The content_id must exist in the system.
            - This operation returns the content if it exists; visibility/privacy logic
              (e.g., public or from followed user) is not enforced here and should be
              checked separately via other operations like `check_content_visibility`.
        """
        content = self.content.get(content_id)
        if not content:
            return {"success": False, "error": "Content not found"}

        return {"success": True, "data": content}

    def get_feed_by_user(self, user_id: str) -> dict:
        """
        Retrieve or generate a personalized feed for a user based on their following and preferences.

        Args:
            user_id (str): The ID of the user for whom to generate the feed.

        Returns:
            dict: {
                "success": True,
                "data": ContentFeedInfo  # Feed containing up to 20 latest content items sorted by timestamp
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., user not found
            }

        Constraints:
            - Only content from valid users is included.
            - Content is sorted in descending order by timestamp (latest first).
            - Only content with supported types ("image", "video", "reel") is included.
            - Feed limits results to latest 20 items (pagination).
        """
        if user_id not in self.users:
            return {"success": False, "error": "User not found"}

        # Filter content: only valid user_id and supported content types
        valid_content = []
        for content_info in self.content.values():
            if (
                content_info["user_id"] in self.users
                and content_info["content_type"] in self.supported_content_types
            ):
                valid_content.append(content_info)

        # Sort by timestamp descending (latest first)
        sorted_content = sorted(valid_content, key=lambda x: x["timestamp"], reverse=True)

        # Apply pagination: get latest 20
        latest_content_ids = [c["content_id"] for c in sorted_content[:20]]

        # Use time module directly to get current timestamp
        current_timestamp = time.time()

        # Create feed representation
        feed = {
            "feed_id": f"feed_{user_id}",
            "user_id": user_id,
            "content_list": latest_content_ids,
            "refresh_timestamp": current_timestamp,
            "filter_criteria": {
                "source": "following_or_public",
                "sort": "latest",
                "limit": 20
            }
        }

        return {"success": True, "data": feed}

    def check_content_visibility(self, content_id: str, requester_user_id: str) -> dict:
        """
        Determine if a piece of content is visible to the requester based on the owner's privacy settings
        and whether the requester follows the owner.

        Args:
            content_id (str): The ID of the content to check visibility for.
            requester_user_id (str): The ID of the user attempting to view the content.

        Returns:
            dict: {
                "success": bool,
                "data": {"visible": bool}  # If successful, whether the content is visible
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., content not found)
            }

        Constraints:
            - If the content owner's account is "public", the content is visible to all.
            - If the account is "private", only followers can see the content.
            - The requester must be a valid user, and the content must exist.
            - A mapping `self.followers` (user_id -> set of follower user_ids) is assumed to exist.

        Note:
            This method assumes `self.followers: Dict[str, set]` is maintained by the system.
            If not, visibility for private accounts cannot be determined.
        """
        # Check if content exists
        if content_id not in self.content:
            return { "success": False, "error": "Content not found" }

        content = self.content[content_id]
        owner_id = content["user_id"]

        # Check if owner exists
        if owner_id not in self.users:
            return { "success": False, "error": "Content owner not found" }

        # Check if requester exists
        if requester_user_id not in self.users:
            return { "success": False, "error": "Requester user not found" }

        owner = self.users[owner_id]
        account_type = owner.get("account_type", "public").lower()

        # Public account: visible to everyone
        if account_type == "public":
            return { "success": True, "data": { "visible": True } }

        # Private account: only visible to followers
        if account_type == "private":
            # Assume self.followers exists and maps user_id -> set of follower user_ids
            if not hasattr(self, "followers"):
                return { "success": False, "error": "Follow relationship tracking is not available" }

            followers = self.followers.get(owner_id, set())
            is_follower = requester_user_id in followers
            return { "success": True, "data": { "visible": is_follower } }

        # Unknown account type
        return { "success": False, "error": f"Unknown account type: {account_type}" }

    def get_content_statistics(self, content_id: str) -> dict:
        """
        Retrieve engagement metrics (likes, comments, shares, views) for a specific content item.

        Args:
            content_id (str): The unique identifier of the content.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "like_count": int,
                    "comment_count": int,
                    "share_count": int,
                    "view_count": int
                }
            }
            or
            {
                "success": False,
                "error": str  # e.g. "Content not found"
            }

        Constraints:
            - The content_id must exist in the system.
            - Engagement counts are always non-negative integers.
        """
        content = self.content.get(content_id)
        if not content:
            return {"success": False, "error": "Content not found"}

        stats = {
            "like_count": content["like_count"],
            "comment_count": content["comment_count"],
            "share_count": content["share_count"],
            "view_count": content["view_count"]
        }

        return {"success": True, "data": stats}

    def upload_content(
        self,
        content_id: str,
        user_id: str,
        content_type: str,
        media_url: str,
        caption: str,
        timestamp: float,
        like_count: int = 0,
        comment_count: int = 0,
        share_count: int = 0,
        view_count: int = 0
    ) -> dict:
        """
        Add new user-generated content to the system.

        Args:
            content_id (str): Unique identifier for the content.
            user_id (str): ID of the user uploading the content. Must exist in the system.
            content_type (str): Type of content. Must be one of: "image", "video", "reel".
            media_url (str): URL to the media file.
            caption (str): Caption or description of the content.
            timestamp (float): Unix timestamp of when the content was created/uploaded.
            like_count (int, optional): Number of initial likes. Defaults to 0.
            comment_count (int, optional): Number of initial comments. Defaults to 0.
            share_count (int, optional): Number of initial shares. Defaults to 0.
            view_count (int, optional): Number of initial views. Defaults to 0.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - user_id must reference an existing user.
            - content_type must be one of the supported types.
            - content_id must be unique.
        """
        if content_id in self.content:
            return { "success": False, "error": "Content ID already exists" }

        if user_id not in self.users:
            return { "success": False, "error": "User ID does not exist" }

        if content_type not in self.supported_content_types:
            return { "success": False, "error": f"Unsupported content type: {content_type}. Supported types: {self.supported_content_types}" }

        # Create new content entry
        new_content: ContentInfo = {
            "content_id": content_id,
            "user_id": user_id,
            "content_type": content_type,
            "media_url": media_url,
            "caption": caption,
            "timestamp": timestamp,
            "like_count": like_count,
            "comment_count": comment_count,
            "share_count": share_count,
            "view_count": view_count
        }

        self.content[content_id] = new_content

        return { "success": True, "message": "Content uploaded successfully" }


    def refresh_user_feed(self, feed_id: str) -> dict:
        """
        Update a user's content feed by reapplying its filter criteria, repopulating content_list,
        and updating the refresh_timestamp.

        Args:
            feed_id (str): The unique identifier of the feed to refresh.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
            }
            or
            {
                "success": False,
                "error": str  # Description of the failure
            }

        Constraints:
            - Only public content or content from followed users is included.
            - Content is sorted by timestamp in descending order (latest first).
            - content_type must be one of: "image", "video", "reel".
            - Supports pagination via 'limit' in filter_criteria (e.g., limit=10).
            - The associated user_id must exist.
        """
        if feed_id not in self.feeds:
            return { "success": False, "error": "Feed not found" }

        feed = self.feeds[feed_id]
        user_id = feed["user_id"]

        if user_id not in self.users:
            return { "success": False, "error": "User associated with feed does not exist" }

        filter_criteria = feed.get("filter_criteria", {})
        source = filter_criteria.get("source", "following")  # default: following
        content_type = filter_criteria.get("type")
        limit = filter_criteria.get("limit", None)

        # Validate content_type if provided
        if content_type and content_type not in self.supported_content_types:
            return { "success": False, "error": f"Unsupported content type: {content_type}" }

        # Determine eligible content
        candidate_content: List[ContentInfo] = []

        if source == "self":
            # Only user's own content
            candidate_content = [
                content for content in self.content.values()
                if content["user_id"] == user_id
            ]
        elif source == "following":
            # Content from followed users and public content
            # Note: Follow relationships are not explicitly modeled, assuming a user follows others
            # For now, we assume public content is visible to all
            # In a full model, we'd have a follows graph; here, we assume privacy is ignored except for 'self'
            # Assuming all content is public for simplicity unless extended
            candidate_content = list(self.content.values())
        else:
            return { "success": False, "error": f"Unsupported source type: {source}" }

        # Filter by content_type if specified
        if content_type:
            candidate_content = [c for c in candidate_content if c["content_type"] == content_type]

        # Sort by timestamp descending
        sorted_content = sorted(candidate_content, key=lambda x: x["timestamp"], reverse=True)

        # Apply limit
        if limit is not None:
            try:
                limit = int(limit)
                if limit < 0:
                    return { "success": False, "error": "Limit must be non-negative" }
                sorted_content = sorted_content[:limit]
            except (TypeError, ValueError):
                return { "success": False, "error": "Invalid limit value" }

        # Extract content_ids
        new_content_list = [c["content_id"] for c in sorted_content]

        # Update feed
        feed["content_list"] = new_content_list
        feed["refresh_timestamp"] = time.time()

        self.feeds[feed_id] = feed  # Ensure update is persisted

        return { "success": True, "message": "Feed refreshed successfully." }

    def update_content_caption(self, content_id: str, new_caption: str) -> dict:
        """
