        """
        if not isinstance(new_caption, str):
            return { "success": False, "error": "New caption must be a string" }

        if content_id not in self.content:
            return { "success": False, "error": "Content not found" }

        self.content[content_id]["caption"] = new_caption

        return {
            "success": True,
            "message": f"Caption updated successfully for content {content_id}"
        }

    def delete_content(self, content_id: str, user_id: str) -> dict:
        """
        Remove a content item from the platform. Only the owner of the content can delete it.

        Args:
            content_id (str): The unique identifier of the content to delete.
            user_id (str): The ID of the user attempting to delete the content (for ownership verification).

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
            }
            or
            {
                "success": False,
                "error": str  # Description of failure (e.g., not found, permission denied)
            }

