        """
        if content_id not in self.content:
            return {"success": False, "error": "Content not found"}

        # Increment the share_count
        self.content[content_id]["share_count"] += 1

        return {"success": True, "message": "Content shared successfully"}

    def update_feed_filter_criteria(self, feed_id: str, new_filter_criteria: dict) -> dict:
        """
