from typing import Dict, TypedDict, Optional
from typing import List



class ProductInfo(TypedDict):
    upc: str
    product_id: str
    name: str
    description: str
    price: float
    category: str
    inventory_level: int
    brand: str
    weight: float
    aisle_location: Optional[str]

class RetailProductDatabase:
    def __init__(self):
        """
        The environment for a retail product database.
        """
        # Products: {upc: ProductInfo}, where upc is unique
        self.products: Dict[str, ProductInfo] = {}

        # Predefined valid categories
        self.valid_categories: set = {
            "Electronics", "Clothing", "Groceries", "Home & Kitchen",
            "Toys", "Health & Beauty", "Sports", "Books", "Automotive", "Other"
        }

        # Constraints reminder:
        # - Each UPC must be unique across the product database (enforced by dict key)
        # - Product price must be non-negative
        # - Inventory level must be a non-negative integer
        # - aisle_location may be None for online-only items
        # - Product category must be one of the valid_categories

    def get_product_by_upc(self, upc: str) -> dict:
        """
        Retrieve full product information using its unique UPC.

        Args:
            upc (str): The Universal Product Code of the product to retrieve.

        Returns:
            dict: {
                "success": True,
                "data": ProductInfo
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Product with given UPC not found"
            }

        Constraints:
            - The UPC must exist in the database.
        """
        product = self.products.get(upc)
        if not product:
            return {"success": False, "error": "Product with given UPC not found"}

        return {"success": True, "data": product}

    def get_product_by_id(self, product_id: str) -> dict:
        """
        Retrieve product details by product_id. Since product_id is not necessarily unique,
        this operation may return multiple products.

        Args:
            product_id (str): The product_id to search for.

        Returns:
            dict: {
                "success": True,
                "data": List[ProductInfo]  # List of product entries with matching product_id (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of error (e.g. invalid input)
            }

        Constraints:
            - product_id must be a non-empty string.
        """
        if not isinstance(product_id, str) or not product_id.strip():
            return { "success": False, "error": "Invalid input: product_id must be a non-empty string" }

        product_id = product_id.strip()
        result = [
            product_info for product_info in self.products.values()
            if product_info["product_id"] == product_id
        ]

        return { "success": True, "data": result }

    def search_products_by_name(self, keyword: str) -> dict:
        """
        Find all products whose name contains the given keyword using case-insensitive partial matching.

        Args:
            keyword (str): The substring to search for in product names.

        Returns:
            dict: {
                "success": True,
                "data": List[ProductInfo]  # List of products whose name contains the keyword (case-insensitive)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. invalid input type
            }

        Constraints:
            - Matching is case-insensitive.
            - Partial match (substring search) is performed.
            - If keyword is empty string, all products are returned.
        """
        if not isinstance(keyword, str):
            return { "success": False, "error": "Keyword must be a string" }

        keyword_lower = keyword.lower()
        result = [
            product for product in self.products.values()
            if keyword_lower in product["name"].lower()
        ]

        return { "success": True, "data": result }

    def list_products_by_category(self, category: str) -> dict:
        """
        Retrieve all products belonging to a specified valid category.

        Args:
            category (str): The product category to filter by. Must be one of the valid categories.

        Returns:
            dict: {
                "success": True,
                "data": List[ProductInfo]  # List of products in the given category (may be empty)
            }
            or
            {
                "success": False,
                "error": "Invalid category"
            }

        Constraints:
            - The category must be one of the predefined valid categories.
            - Product entries are expected to have valid categories (enforced at creation/update).
        """
        if not category or category not in self.valid_categories:
            return {"success": False, "error": "Invalid category"}

        result = [
            product for product in self.products.values()
            if product["category"] == category
        ]

        return {"success": True, "data": result}

    def list_products_by_brand(self, brand: str) -> dict:
        """
        Retrieve all products that belong to a specific brand.

        Args:
            brand (str): The brand name to search for. Must be a non-empty string.

        Returns:
            dict: {
                "success": True,
                "data": List[ProductInfo]  # List of products matching the brand; may be empty
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. invalid input
            }

        Constraints:
            - The brand must be a string.
            - Brand values are not restricted to a predefined list.
        """
        if not isinstance(brand, str):
            return { "success": False, "error": "Brand must be a string" }

        if not brand:
            return { "success": False, "error": "Brand cannot be empty" }

        result = [
            product_info for product_info in self.products.values()
            if product_info["brand"] == brand
        ]

        return { "success": True, "data": result }

    def check_inventory_level(self, upc: str) -> dict:
        """
        Return the current inventory count for a product identified by UPC.

        Args:
            upc (str): The unique product code (UPC) of the product.

        Returns:
            dict: {
                "success": bool,
                "data": { "inventory_level": int }  # Present only on success
            }
            or {
                "success": False,
                "error": str  # Reason for failure, e.g., product not found
            }

