        product = self.products.get(upc)
        if not product:
            return { "success": False, "error": "Product with given UPC not found" }

        return { "success": True, "data": product["price"] }

    def get_aisle_location(self, upc: str) -> dict:
        """
        Get the physical store aisle location of a product by its UPC.
        Returns None if the product is online-only or aisle location is unspecified.

        Args:
            upc (str): The unique product code (UPC) of the product.

        Returns:
            dict: {
                "success": True,
                "data": Optional[str]  # The aisle location (e.g. "A3"), or None if online-only
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. product not found
            }

        Constraints:
