        """
        if upc not in self.products:
            return { "success": False, "error": "Product with given UPC not found" }

        aisle_location = self.products[upc]["aisle_location"]
        return { "success": True, "data": aisle_location }

    def list_all_categories(self) -> dict:
        """
        Return the list of all valid product categories supported by the system.

        Args:
            None

        Returns:
            dict: {
                "success": True,
                "data": List[str]  # List of valid category names (e.g., "Electronics", "Clothing", etc.)
            }

        Note:
            This operation always succeeds as the valid_categories set is initialized at construction.
        """
        return {
            "success": True,
            "data": list(self.valid_categories)
        }

    def get_all_products(self) -> dict:
        """
        Retrieve a complete list of all products in the database.

        Returns:
            dict: {
                "success": True,
                "data": List[ProductInfo]  # List of all products; empty list if no products exist
            }

        Note:
