from typing import Dict, List, TypedDict, Optional
import time
from typing import Dict



class OCRRequestInfo(TypedDict):
    request_id: str
    document_reference: str
    submission_time: float  # Unix timestamp
    status: str  # One of: "submitted", "processing", "completed", "failed"
    result_text: Optional[str]
    completion_time: Optional[float]

class ResultRepositoryInfo(TypedDict):
    request_id: str
    extracted_text: str
    confidence_scores: List[float]  # or Dict[str, float] depending on structure
    processing_timestamp: float

class OCRProcessingService:
    def __init__(self):
        """
        Stateful OCR processing service supporting document submission,
        job queuing, and result retrieval.
        """

        # OCR Requests: {request_id: OCRRequestInfo}
        # Maintains full lifecycle of each OCR job
        self.requests: Dict[str, OCRRequestInfo] = {}

        # Job Queue: tracks pending request IDs and next request to process
        self.job_queue: Dict[str, List[str]] = {
            "queued_request_ids": []  # FIFO queue
        }
        self.next_request_id: Optional[str] = None  # Head of the queue

        # Result Repository: {request_id: ResultRepositoryInfo}
        # Stores final OCR outputs with quality metrics
        self.result_repository: Dict[str, ResultRepositoryInfo] = {}

        # Constraints reminder:
        # - A request must be in the system before its result can be retrieved
        # - Status transitions: "submitted" → "processing" → "completed"/"failed"
        # - result_text is only available if status == "completed"
        # - Each request_id must be unique (enforced via dict keys)
        # - Completed results are retained for 24 hours (e.g., 86400 seconds) before purge

    def get_ocr_request_status(self, request_id: str) -> dict:
        """
        Retrieve the current status of an OCR request by its request_id.

        Args:
            request_id (str): The unique identifier of the OCR request.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "status": str  # One of: "submitted", "processing", "completed", "failed"
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Request not found"
            }

        Constraints:
            - The request must exist in the system to retrieve its status.
        """
        if request_id not in self.requests:
            return { "success": False, "error": "Request not found" }

        status = self.requests[request_id]["status"]
        return { "success": True, "data": { "status": status } }

    def is_result_available(self, request_id: str) -> dict:
        """
        Check whether the OCR result is available (i.e., status is "completed") for a given request_id.

        Args:
            request_id (str): The unique identifier of the OCR request.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "available": bool  # True if status is "completed", False otherwise
                }
            }
            or
            {
                "success": False,
                "error": str  # E.g., "Request not found"
            }

        Constraints:
            - The request must exist in the system.
            - Result is considered available only when status is "completed".
        """
        if request_id not in self.requests:
            return { "success": False, "error": "Request not found" }

        status = self.requests[request_id]["status"]
        available = status == "completed"

        return { "success": True, "data": { "available": available } }

    def fetch_ocr_result_text(self, request_id: str) -> dict:
        """
        Retrieve the extracted text from a completed OCR request.

        Args:
            request_id (str): The unique identifier of the OCR request.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "extracted_text": str  # The OCR-extracted text
                }
            }
            or
            {
                "success": False,
                "error": str  # Explanation such as "Request not found", "OCR processing not completed", "Result unavailable"
            }

        Constraints:
            - The request must exist in the system.
            - The request status must be "completed" to retrieve the result.
            - The extracted text must be available in the result repository or request data.
        """
        # Check if request exists
        if request_id not in self.requests:
            return { "success": False, "error": "Request not found" }

        request = self.requests[request_id]

        # Check if request has completed
        if request["status"] != "completed":
            return { "success": False, "error": "OCR processing not completed" }

        # Check if result_text is available
        if not request.get("result_text"):
            return { "success": False, "error": "Result text unavailable" }

        # Optionally verify presence in result_repository
        if request_id not in self.result_repository:
            return { "success": False, "error": "OCR result not found in repository" }

        extracted_text = self.result_repository[request_id]["extracted_text"]

        return {
            "success": True,
            "data": {
                "extracted_text": extracted_text
            }
        }

    def get_ocr_result_with_confidence(self, request_id: str) -> dict:
        """
        Retrieve the extracted text and confidence scores for characters or words from the result repository.

        Args:
            request_id (str): The unique identifier of the OCR request.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "extracted_text": str,
                    "confidence_scores": List[float],
                    "processing_timestamp": float
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g., not found, not completed)
            }

        Constraints:
            - The request must exist in the system.
            - The request status must be "completed".
            - The result must be present in the result repository.
            - Results are only available for completed requests.
        """
        # Check if request exists
        if request_id not in self.requests:
            return { "success": False, "error": "Request not found" }

        request = self.requests[request_id]

        # Check if request is completed
        if request["status"] != "completed":
            return { "success": False, "error": "OCR processing not completed" }

        # Check if result exists in repository
        if request_id not in self.result_repository:
            return { "success": False, "error": "Result not available in repository" }

        result = self.result_repository[request_id]
        return {
            "success": True,
            "data": {
                "extracted_text": result["extracted_text"],
                "confidence_scores": result["confidence_scores"],
                "processing_timestamp": result["processing_timestamp"]
            }
        }

    def list_queued_requests(self) -> dict:
        """
        View all request IDs currently in the job queue waiting for processing.

        Returns:
            dict: {
                "success": True,
                "data": List[str]  # List of request_id strings in FIFO order (may be empty)
            }
            This operation always succeeds as the job queue is a core initialized component.

        Constraints:
            - The job queue is maintained in FIFO order.
            - Only requests that have been submitted and not yet started processing are included.
        """
        return {
            "success": True,
            "data": self.job_queue["queued_request_ids"].copy()  # Return a copy to prevent external mutation
        }

    def check_request_existence(self, request_id: str) -> dict:
        """
        Verify whether a request with the given request_id has been submitted into the system.

        Args:
            request_id (str): The unique identifier of the OCR request to check.

        Returns:
            dict: {
                "success": True,
                "data": bool  # True if request exists, False otherwise
            }
            This operation always succeeds; it only checks presence in the system.

        Constraints:
            - A request must be submitted before it exists in the system.
            - Each request_id must be unique (enforced at submission).
        """
        exists = request_id in self.requests
        return { "success": True, "data": exists }

    def get_request_metadata(self, request_id: str) -> dict:
        """
        Retrieve metadata for a given OCR request, including document reference, submission time,
        completion time (if available), and current status.

        Args:
            request_id (str): The unique identifier of the OCR request.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "document_reference": str,
                    "submission_time": float,  # Unix timestamp
                    "completion_time": Optional[float],
                    "status": str
                }
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., "Request not found"
            }

        Constraints:
            - The request must exist in the system to retrieve its metadata.
            - completion_time may be None if the request has not completed.
        """
        request = self.requests.get(request_id)
        if not request:
            return {"success": False, "error": "Request not found"}

        return {
            "success": True,
            "data": {
                "document_reference": request["document_reference"],
                "submission_time": request["submission_time"],
                "completion_time": request["completion_time"],
                "status": request["status"]
            }
        }


    def submit_ocr_request(self, document_reference: str) -> Dict[str, object]:
        """
        Submit a new document for OCR processing, generate a unique request_id, store request metadata, and enqueue it.

        Args:
            document_reference (str): Identifier or path to the document to be processed.

        Returns:
            dict: {
                "success": bool,
                "message": str,
                "request_id": str  # Included only on success
            }
            If unsuccessful, returns:
            {
                "success": False,
                "error": str
            }

        Constraints:
            - Each request_id must be unique.
            - New requests start with status "submitted".
            - The request is added to the job queue.
        """
        if not isinstance(document_reference, str) or not document_reference.strip():
            return {
                "success": False,
                "error": "Document reference must be a non-empty string"
            }

        document_reference = document_reference.strip()

        # Generate unique request_id (simple scheme: req_<n>)
        request_id = f"req_{len(self.requests)}"

        # Ensure uniqueness (in rare case of collision due to external load, retry logic not needed here)
        while request_id in self.requests:
            request_id = f"req_{len(self.requests) + 1}"

        submission_time = time.time()

        # Create new OCR request
        new_request: OCRRequestInfo = {
            "request_id": request_id,
            "document_reference": document_reference,
            "submission_time": submission_time,
            "status": "submitted",
            "result_text": None,
            "completion_time": None
        }

        # Store request
        self.requests[request_id] = new_request

        # Enqueue request
        self.job_queue["queued_request_ids"].append(request_id)

        # Set next_request_id if it's the only one in queue
        if self.next_request_id is None:
            self.next_request_id = request_id

        return {
            "success": True,
            "message": "OCR request submitted successfully",
            "request_id": request_id
        }

    def start_processing_request(self, request_id: str) -> dict:
        """
        Move an OCR request from "submitted" to "processing" state and set it as the next in line for execution.

        Args:
            request_id (str): The unique identifier of the OCR request to start processing.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The request must exist in the system.
            - The request's current status must be "submitted".
            - Status transition must follow: "submitted" → "processing".
        """
        if request_id not in self.requests:
            return { "success": False, "error": "Request not found" }

        request = self.requests[request_id]

        if request["status"] != "submitted":
            return { "success": False, "error": "Request is not in submitted state" }

        # Update status to processing
        request["status"] = "processing"
        self.next_request_id = request_id

        return {
            "success": True,
            "message": f"Request '{request_id}' started processing."
        }

    def complete_ocr_request(
        self,
        request_id: str,
        extracted_text: str,
        confidence_scores: List[float],
        processing_timestamp: float
    ) -> dict:
        """
        Mark a processing OCR request as completed, store the extracted text and confidence scores
        in the result repository, and update the request's completion time.

        Args:
            request_id (str): Unique identifier of the OCR request.
            extracted_text (str): The text extracted from the document by the OCR engine.
            confidence_scores (List[float]): Confidence scores associated with the OCR result.
            processing_timestamp (float): Unix timestamp when processing was completed.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Description of the issue
            }

        Constraints:
            - Request must exist.
            - Request status must be "processing" to transition to "completed".
            - Result text is only stored upon completion.
            - Each request_id must be unique (enforced by system).
        """
        if request_id not in self.requests:
            return { "success": False, "error": "Request ID does not exist" }

        request = self.requests[request_id]

        if request["status"] != "processing":
            return { "success": False, "error": f"Request status is '{request['status']}', expected 'processing'" }

        # Update request status and metadata
        request["status"] = "completed"
        request["result_text"] = extracted_text
        request["completion_time"] = processing_timestamp

        # Store result in repository
        self.result_repository[request_id] = {
            "request_id": request_id,
            "extracted_text": extracted_text,
            "confidence_scores": confidence_scores,
            "processing_timestamp": processing_timestamp
        }

        return { "success": True, "message": "OCR request completed successfully" }


    def fail_ocr_request(self, request_id: str) -> dict:
        """
        Mark an OCR request as "failed" due to processing errors.

        Args:
            request_id (str): The unique identifier of the OCR request.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The request must exist.
            - Only requests in status "submitted" or "processing" can be failed.
            - Status transitions must follow: "submitted" → "processing" → "failed".
            - Once failed, the result_text remains None.
        """
        if request_id not in self.requests:
            return { "success": False, "error": f"Request {request_id} does not exist." }

        request = self.requests[request_id]
        current_status = request["status"]

        if current_status == "completed":
            return { "success": False, "error": f"Request {request_id} is already completed and cannot be failed." }
        if current_status == "failed":
            return { "success": False, "error": f"Request {request_id} has already failed." }

        # Valid to fail if status is "submitted" or "processing"
        if current_status not in ["submitted", "processing"]:
            return {
                "success": False,
                "error": f"Request {request_id} has invalid status '{current_status}' for failing."
            }

        # Update the request state
        request["status"] = "failed"
        request["completion_time"] = time.time()
        request["result_text"] = None  # Ensure no result is present

        # Remove from job queue if present
        if request_id in self.job_queue["queued_request_ids"]:
            self.job_queue["queued_request_ids"].remove(request_id)
        if self.next_request_id == request_id:
            self.next_request_id = None  # Will be reassigned on next processing

        return { "success": True, "message": f"Request {request_id} marked as failed." }


    def purge_expired_results(self) -> dict:
        """
        Remove entries from the result repository that have exceeded the retention period (24 hours).

        Returns:
            dict: {
                "success": True,
                "message": str  # Describes how many results were purged or none found
            }

        Constraints:
            - Only results with processing_timestamp older than 24 hours (86400 seconds) are removed.
            - The operation does not remove OCR requests but only their associated results.
        """
        current_time = time.time()
        retention_period = 86400  # 24 hours in seconds
        cutoff_time = current_time - retention_period
        purged_count = 0

        # Collect expired request IDs first to avoid modifying dict during iteration
        expired_request_ids = [
            req_id for req_id, result_info in self.result_repository.items()
            if result_info["processing_timestamp"] < cutoff_time
        ]

        # Remove expired results
        for req_id in expired_request_ids:
            del self.result_repository[req_id]
            purged_count += 1

        if purged_count > 0:
            return {
                "success": True,
                "message": f"Purged {purged_count} expired results."
            }
        else:
            return {
                "success": True,
                "message": "No expired results to purge."
            }

    def clear_completed_request(self, request_id: str) -> dict:
        """
        Remove a completed OCR request from the system, including its entry in the request log
        and the result repository.

        Args:
            request_id (str): The unique identifier of the OCR request to clear.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation of removal
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g. not found, not completed)
            }

        Constraints:
            - Only requests with status "completed" can be cleared.
            - Request must exist in the system.
            - After clearing, the request and its result (if any) are no longer accessible.
        """
        request = self.requests.get(request_id)
        if not request:
            return { "success": False, "error": "Request not found." }

        status = request["status"]
        if status != "completed":
            return {
                "success": False,
                "error": f"Only completed requests can be cleared. Current status: {status}."
            }

        # Remove from requests
        if request_id in self.requests:
            del self.requests[request_id]

        # Remove from result repository if present
        if request_id in self.result_repository:
            del self.result_repository[request_id]

        return {
            "success": True,
            "message": f"Request {request_id} cleared from system."
        }


    def retry_ocr_request(self, original_request_id: str) -> Dict[str, str]:
        """
        Re-submit a failed OCR request with the same document reference and a new request_id.

        Args:
            original_request_id (str): The ID of the failed OCR request to retry.

        Returns:
            dict: {
                "success": True,
                "message": str  # Description of the retry outcome
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g. request not found, not failed)
            }

        Constraints:
            - Only requests with status "failed" can be retried.
            - Each request_id must be unique.
            - The new request is added to the job queue with status "submitted".
        """
        # Check if original request exists
        if original_request_id not in self.requests:
            return { "success": False, "error": "Original OCR request not found" }

        original_request = self.requests[original_request_id]

        # Only allow retry if status is "failed"
        if original_request["status"] != "failed":
            return { "success": False, "error": "Only failed OCR requests can be retried" }

        # Generate new request_id
        new_request_id = f"{original_request_id}_retry"
        suffix = 1
        while new_request_id in self.requests:
            new_request_id = f"{original_request_id}_retry_{suffix}"
            suffix += 1

        submission_time = time.time()

        # Create new OCR request
        new_request: OCRRequestInfo = {
            "request_id": new_request_id,
            "document_reference": original_request["document_reference"],
            "submission_time": submission_time,
            "status": "submitted",
            "result_text": None,
            "completion_time": None
        }

        # Add to requests and job queue
        self.requests[new_request_id] = new_request
        self.job_queue["queued_request_ids"].append(new_request_id)

        # Update next_request_id if queue was empty
        if self.next_request_id is None:
            self.next_request_id = new_request_id

        return {
            "success": True,
            "message": f"OCR request retry submitted with new request_id: {new_request_id}"
        }

