        """
        Submit a new document for OCR processing, generate a unique request_id, store request metadata, and enqueue it.

        Args:
            document_reference (str): Identifier or path to the document to be processed.

        Returns:
            dict: {
                "success": bool,
                "message": str,
                "request_id": str  # Included only on success
            }
            If unsuccessful, returns:
            {
                "success": False,
                "error": str
            }

        Constraints:
            - Each request_id must be unique.
            - New requests start with status "submitted".
            - The request is added to the job queue.
        """
        if not isinstance(document_reference, str) or not document_reference.strip():
            return {
                "success": False,
                "error": "Document reference must be a non-empty string"
            }

        document_reference = document_reference.strip()

        # Generate unique request_id (simple scheme: req_<n>)
        request_id = f"req_{len(self.requests)}"

        # Ensure uniqueness (in rare case of collision due to external load, retry logic not needed here)
        while request_id in self.requests:
            request_id = f"req_{len(self.requests) + 1}"

        submission_time = time.time()

        # Create new OCR request
        new_request: OCRRequestInfo = {
            "request_id": request_id,
            "document_reference": document_reference,
            "submission_time": submission_time,
            "status": "submitted",
            "result_text": None,
            "completion_time": None
        }

        # Store request
        self.requests[request_id] = new_request

        # Enqueue request
        self.job_queue["queued_request_ids"].append(request_id)

        # Set next_request_id if it's the only one in queue
        if self.next_request_id is None:
            self.next_request_id = request_id

        return {
            "success": True,
            "message": "OCR request submitted successfully",
            "request_id": request_id
        }"}, "start_processing_request": {"signature": {"parameters": [{"name": "request_id", "type": "str", "default": null, "kind": "positional-or-keyword"}], "return": "dict"}, "doc": "Move an OCR request from "submitted" to "processing" state and set it as the next in line for execution.

