        """
        Move an OCR request from "submitted" to "processing" state and set it as the next in line for execution.

        Args:
            request_id (str): The unique identifier of the OCR request to start processing.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The request must exist in the system.
            - The request's current status must be "submitted".
            - Status transition must follow: "submitted" → "processing".
        """
        if request_id not in self.requests:
            return { "success": False, "error": "Request not found" }

        request = self.requests[request_id]

        if request["status"] != "submitted":
            return { "success": False, "error": "Request is not in submitted state" }

        # Update status to processing
        request["status"] = "processing"
        self.next_request_id = request_id

        return {
            "success": True,
            "message": f"Request '{request_id}' started processing."
        }"}, "complete_ocr_request": {"signature": {"parameters": [{"name": "request_id", "type": "str", "default": null, "kind": "positional-or-keyword"}, {"name": "extracted_text", "type": "str", "default": null, "kind": "positional-or-keyword"}, {"name": "confidence_scores", "type": "List[float]", "default": null, "kind": "positional-or-keyword"}, {"name": "processing_timestamp", "type": "float", "default": null, "kind": "positional-or-keyword"}], "return": "dict"}, "doc": "Mark a processing OCR request as completed, store the extracted text and confidence scores
