        self,
        request_id: str,
        extracted_text: str,
        confidence_scores: List[float],
        processing_timestamp: float
    ) -> dict:
        """
        Mark a processing OCR request as completed, store the extracted text and confidence scores
        in the result repository, and update the request's completion time.

        Args:
            request_id (str): Unique identifier of the OCR request.
            extracted_text (str): The text extracted from the document by the OCR engine.
            confidence_scores (List[float]): Confidence scores associated with the OCR result.
            processing_timestamp (float): Unix timestamp when processing was completed.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Description of the issue
            }

        Constraints:
            - Request must exist.
            - Request status must be "processing" to transition to "completed".
            - Result text is only stored upon completion.
            - Each request_id must be unique (enforced by system).
        """
        if request_id not in self.requests:
            return { "success": False, "error": "Request ID does not exist" }

        request = self.requests[request_id]

        if request["status"] != "processing":
            return { "success": False, "error": f"Request status is '{request['status']}', expected 'processing'" }

        # Update request status and metadata
        request["status"] = "completed"
        request["result_text"] = extracted_text
        request["completion_time"] = processing_timestamp

        # Store result in repository
        self.result_repository[request_id] = {
            "request_id": request_id,
            "extracted_text": extracted_text,
            "confidence_scores": confidence_scores,
            "processing_timestamp": processing_timestamp
        }

        return { "success": True, "message": "OCR request completed successfully" }"}, "fail_ocr_request": {"signature": {"parameters": [{"name": "request_id", "type": "str", "default": null, "kind": "positional-or-keyword"}], "return": "dict"}, "doc": "Mark an OCR request as "failed" due to processing errors.

