    - Only requests in status "submitted" or "processing" can be failed.
    - Status transitions must follow: "submitted" → "processing" → "failed".
    - Once failed, the result_text remains None.", "source_code": "    def fail_ocr_request(self, request_id: str) -> dict:
        """
        Mark an OCR request as "failed" due to processing errors.

        Args:
            request_id (str): The unique identifier of the OCR request.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The request must exist.
            - Only requests in status "submitted" or "processing" can be failed.
            - Status transitions must follow: "submitted" → "processing" → "failed".
            - Once failed, the result_text remains None.
        """
        if request_id not in self.requests:
            return { "success": False, "error": f"Request {request_id} does not exist." }

        request = self.requests[request_id]
        current_status = request["status"]

        if current_status == "completed":
            return { "success": False, "error": f"Request {request_id} is already completed and cannot be failed." }
        if current_status == "failed":
            return { "success": False, "error": f"Request {request_id} has already failed." }

        # Valid to fail if status is "submitted" or "processing"
        if current_status not in ["submitted", "processing"]:
            return {
                "success": False,
                "error": f"Request {request_id} has invalid status '{current_status}' for failing."
            }

        # Update the request state
        request["status"] = "failed"
        request["completion_time"] = time.time()
        request["result_text"] = None  # Ensure no result is present

        # Remove from job queue if present
        if request_id in self.job_queue["queued_request_ids"]:
            self.job_queue["queued_request_ids"].remove(request_id)
        if self.next_request_id == request_id:
            self.next_request_id = None  # Will be reassigned on next processing

        return { "success": True, "message": f"Request {request_id} marked as failed." }"}, "purge_expired_results": {"signature": {"parameters": [], "return": "dict"}, "doc": "Remove entries from the result repository that have exceeded the retention period (24 hours).

