    dict: {
        "success": True,
        "message": str  # Describes how many results were purged or none found
    }

Constraints:
    - Only results with processing_timestamp older than 24 hours (86400 seconds) are removed.
    - The operation does not remove OCR requests but only their associated results.", "source_code": "    def purge_expired_results(self) -> dict:
        """
        Remove entries from the result repository that have exceeded the retention period (24 hours).

        Returns:
            dict: {
                "success": True,
                "message": str  # Describes how many results were purged or none found
            }

        Constraints:
            - Only results with processing_timestamp older than 24 hours (86400 seconds) are removed.
            - The operation does not remove OCR requests but only their associated results.
        """
        current_time = time.time()
        retention_period = 86400  # 24 hours in seconds
        cutoff_time = current_time - retention_period
        purged_count = 0

        # Collect expired request IDs first to avoid modifying dict during iteration
        expired_request_ids = [
            req_id for req_id, result_info in self.result_repository.items()
            if result_info["processing_timestamp"] < cutoff_time
        ]

        # Remove expired results
        for req_id in expired_request_ids:
            del self.result_repository[req_id]
            purged_count += 1

        if purged_count > 0:
            return {
                "success": True,
                "message": f"Purged {purged_count} expired results."
            }
        else:
            return {
                "success": True,
                "message": "No expired results to purge."
            }"}, "clear_completed_request": {"signature": {"parameters": [{"name": "request_id", "type": "str", "default": null, "kind": "positional-or-keyword"}], "return": "dict"}, "doc": "Remove a completed OCR request from the system, including its entry in the request log
