from typing import Dict, List, TypedDict
import time
from typing import List, Dict



class ThreadInfo(TypedDict):
    thread_id: str
    title: str
    creation_timestamp: float
    last_activity_timestamp: float
    author_id: str
    forum_category: str  # References category_id in ForumCategory
    tags: List[str]      # List of tag names
    status: str          # 'open' or 'closed'

class PostInfo(TypedDict):
    post_id: str
    thread_id: str
    author_id: str
    content: str
    creation_timestamp: float
    edit_timestamp: float
    is_first_post: bool

class UserInfo(TypedDict):
    user_id: str
    username: str
    join_date: float
    reputation_score: int
    role: str  # e.g., 'member', 'moderator'

class TagInfo(TypedDict):
    tag_name: str
    usage_count: int
    is_moderated: bool

class ForumCategoryInfo(TypedDict):
    category_id: str
    name: str
    description: str
    parent_category: str  # Optional; references another category_id or None

class OnlineDiscussionForum:
    def __init__(self):
        """
        The environment for an online discussion forum.
        """
        # Threads: {thread_id: ThreadInfo}
        self.threads: Dict[str, ThreadInfo] = {}

        # Posts: {post_id: PostInfo}
        self.posts: Dict[str, PostInfo] = {}

        # Users: {user_id: UserInfo}
        self.users: Dict[str, UserInfo] = {}

        # Tags: {tag_name: TagInfo}
        self.tags: Dict[str, TagInfo] = {}

        # Forum Categories: {category_id: ForumCategoryInfo}
        self.forum_categories: Dict[str, ForumCategoryInfo] = {}

        # Constraints reminder:
        # - Each thread must belong to exactly one forum category.
        # - A thread must have exactly one initial post, which creates the thread.
        # - Tags must be from a predefined or moderated set; new tags may require approval.
        # - Only registered users can create threads or posts.
        # - The first post in a thread is linked to the thread title and subject.
        # - Thread timestamps (creation and last activity) are automatically updated with new posts.

    def get_user_by_id(self, user_id: str) -> dict:
        """
        Retrieve user information including username, role, reputation score, join date, and role by user_id.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": UserInfo  # Full user information
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., "User not found"
            }

        Constraints:
            - Only registered users exist in the system.
        """
        user_info = self.users.get(user_id)
        if user_info is None:
            return {"success": False, "error": "User not found"}

        return {"success": True, "data": user_info}

    def get_user_role(self, user_id: str) -> dict:
        """
        Retrieve the role of a user by their user ID.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": {"role": str}  # e.g., "member", "moderator"
            }
            or
            {
                "success": False,
                "error": str  # e.g., "User does not exist"
            }

        Constraints:
            - Only registered users have a role recorded in the system.
        """
        user = self.users.get(user_id)
        if not user:
            return {"success": False, "error": "User does not exist"}

        return {"success": True, "data": {"role": user["role"]}}

    def get_user_reputation(self, user_id: str) -> dict:
        """
        Query a user's reputation score, which may influence visibility or privileges.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": int  # The user's reputation score
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "User not found"
            }

        Constraints:
            - Only registered users have a reputation score.
            - Unregistered users (non-existent) will result in an error.
        """
        if user_id not in self.users:
            return {"success": False, "error": "User not found"}

        return {"success": True, "data": self.users[user_id]["reputation_score"]}

    def list_all_categories(self) -> dict:
        """
        Retrieve all available forum categories, including their hierarchical structure.

        Returns:
            dict: {
                "success": True,
                "data": List[ForumCategoryInfo]  # All categories; caller may infer hierarchy via parent_category
            }
            or
            {
                "success": False,
                "error": str  # Only if unexpected (e.g., internal state issue), though not expected here
            }

        Note:
            - The hierarchical structure is represented through the 'parent_category' field in each category.
            - If no categories exist, returns an empty list (success).
        """
        try:
            all_categories = list(self.forum_categories.values())
            return { "success": True, "data": all_categories }
        except Exception as e:
            # Though unlikely, catch any unforeseen error (e.g., corrupted state)
            return { "success": False, "error": f"Failed to retrieve categories: {str(e)}" }

    def get_category_by_id(self, category_id: str) -> dict:
        """
        Retrieve the details of a forum category by its category_id.

        Args:
            category_id (str): The unique identifier of the forum category.

        Returns:
            dict: {
                "success": True,
                "data": ForumCategoryInfo  # Dictionary containing category details
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Category not found"
            }

        Constraints:
            - The category_id must correspond to an existing forum category.
        """
        category = self.forum_categories.get(category_id)
        if not category:
            return {"success": False, "error": "Category not found"}

        return {"success": True, "data": category}

    def get_category_by_name(self, name: str) -> dict:
        """
        Find and return a forum category by its name.

        Args:
            name (str): The name of the forum category to retrieve (e.g., "Policy Discussion").

        Returns:
            dict: {
                "success": True,
                "data": ForumCategoryInfo  # Full category information
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. "Category with the given name not found"
            }

        Constraints:
            - The name must match an existing category's name exactly (case-sensitive).
            - If multiple categories have the same name, the first match encountered is returned.
        """
        for category_info in self.forum_categories.values():
            if category_info["name"] == name:
                return {"success": True, "data": category_info}
        return {"success": False, "error": "Category with the given name not found"}

    def list_threads_in_category(self, category_id: str) -> dict:
        """
        Retrieve all threads within the specified forum category.

        Args:
            category_id (str): The unique identifier of the forum category.

        Returns:
            dict: {
                "success": True,
                "data": List[ThreadInfo]  # List of threads in the category; may be empty
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. "Category does not exist"
            }

        Constraints:
            - The category_id must correspond to an existing forum category.
            - Each thread is associated with exactly one category.
        """
        if category_id not in self.forum_categories:
            return { "success": False, "error": "Category does not exist" }

        result = [
            thread_info for thread_info in self.threads.values()
            if thread_info["forum_category"] == category_id
        ]

        return { "success": True, "data": result }

    def get_thread_by_id(self, thread_id: str) -> dict:
        """
        Retrieve full metadata and status of a thread by its unique thread_id.

        Args:
            thread_id (str): The unique identifier of the thread.

        Returns:
            dict: {
                "success": True,
                "data": ThreadInfo  # Complete thread metadata
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Thread not found"
            }

        Constraints:
            - The thread_id must correspond to an existing thread.
        """
        thread = self.threads.get(thread_id)
        if thread is None:
            return {"success": False, "error": "Thread not found"}

        return {"success": True, "data": thread}

    def get_thread_status(self, thread_id: str) -> dict:
        """
        Retrieve the current status (open or closed) of a thread.

        Args:
            thread_id (str): The unique identifier of the thread.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "status": str  # Either "open" or "closed"
                }
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. thread not found
            }

        Constraints:
            - The thread must exist in the forum.
        """
        thread = self.threads.get(thread_id)
        if not thread:
            return {"success": False, "error": "Thread not found"}

        return {"success": True, "data": {"status": thread["status"]}}

    def get_thread_title(self, thread_id: str) -> dict:
        """
        Retrieve the title of a thread by its thread_id.

        Args:
            thread_id (str): The unique identifier of the thread.

        Returns:
            dict: {
                "success": True,
                "data": str  # The title of the thread
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Thread not found"
            }

        Constraints:
            - The thread must exist in the forum.
            - The title is defined at thread creation and is linked to the first post.
        """
        thread = self.threads.get(thread_id)
        if not thread:
            return {"success": False, "error": "Thread not found"}

        return {"success": True, "data": thread["title"]}

    def get_thread_author(self, thread_id: str) -> dict:
        """
        Retrieve the author ID of the specified thread.

        Args:
            thread_id (str): The unique identifier of the thread.

        Returns:
            dict: {
                "success": True,
                "data": {"author_id": str}
            }
            or
            {
                "success": False,
                "error": "Thread not found"
            }

        Constraints:
            - The thread must exist in the system.
        """
        thread = self.threads.get(thread_id)
        if not thread:
            return {"success": False, "error": "Thread not found"}

        return {"success": True, "data": {"author_id": thread["author_id"]}}

    def list_posts_in_thread(self, thread_id: str) -> dict:
        """
        Retrieve all posts in a thread, ordered chronologically by creation timestamp (oldest first).

        Args:
            thread_id (str): The ID of the thread to retrieve posts from.

        Returns:
            dict: {
                "success": bool,
                "data": List[PostInfo]  # Sorted by creation_timestamp ascending
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., thread not found
            }

        Constraints:
            - The thread must exist in the forum.
            - Posts are returned in chronological order of creation.
        """
        if thread_id not in self.threads:
            return {"success": False, "error": "Thread not found"}

        # Filter posts belonging to the thread
        thread_posts = [
            post for post in self.posts.values()
            if post["thread_id"] == thread_id
        ]

        # Sort by creation_timestamp ascending (oldest first)
        sorted_posts = sorted(thread_posts, key=lambda p: p["creation_timestamp"])

        return {
            "success": True,
            "data": sorted_posts
        }

    def get_first_post_in_thread(self, thread_id: str) -> dict:
        """
        Retrieve the initial post that started the thread, containing the core topic.

        Args:
            thread_id (str): The unique identifier of the thread.

        Returns:
            dict: {
                "success": True,
                "data": PostInfo  # The first post in the thread
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g., thread not found, first post missing)
            }

        Constraints:
            - The thread must exist.
            - The thread must have exactly one initial post (enforced by system rules).
        """
        if thread_id not in self.threads:
            return { "success": False, "error": "Thread not found" }

        # Find the post in this thread where is_first_post is True
        first_post = None
        for post in self.posts.values():
            if post["thread_id"] == thread_id and post["is_first_post"]:
                first_post = post
                break

        if not first_post:
            return { "success": False, "error": "First post not found in thread" }

        return { "success": True, "data": first_post }

    def get_post_content(self, post_id: str) -> dict:
        """
        Retrieve the text content of a specific post by its post ID.

        Args:
            post_id (str): The unique identifier of the post.

        Returns:
            dict: {
                "success": True,
                "data": str  # The content of the post
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Post not found"
            }

        Constraints:
            - The post must exist in the forum.
        """
        if not post_id:
            return {"success": False, "error": "Post ID cannot be empty"}

        post = self.posts.get(post_id)
        if not post:
            return {"success": False, "error": "Post not found"}

        return {"success": True, "data": post["content"]}

    def search_threads_by_tag(self, tag_name: str) -> dict:
        """
        Find all threads associated with a given tag.

        Args:
            tag_name (str): The name of the tag to search for (e.g., 'renewable').

        Returns:
            dict: {
                "success": True,
                "data": List[ThreadInfo]  # List of threads that include the tag; may be empty
            }
            or
            {
                "success": False,
                "error": str  # Only if input is invalid, though type hints protect us
            }

        Constraints:
            - The search is based on exact string match in the thread's `tags` list.
            - Threads are returned even if the tag is not formally registered or approved.
            - The operation does not require the tag to exist in the tag registry.
        """
        if not isinstance(tag_name, str):
            return { "success": False, "error": "Tag name must be a string." }

        if not tag_name.strip():
            return { "success": False, "error": "Tag name cannot be empty or whitespace." }

        tag_name = tag_name.strip()

        result = [
            thread_info for thread_info in self.threads.values()
            if tag_name in thread_info["tags"]
        ]

        return { "success": True, "data": result }

    def list_all_tags(self) -> dict:
        """
        Retrieve all available tags in the forum, including their moderation status and usage count.

        Returns:
            dict: {
                "success": True,
                "data": List[TagInfo]  # List of all tag metadata (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Only if an unexpected internal issue occurs (should not happen)
            }

        Constraints:
            - Tag data is retrieved as-is from the internal state.
            - No permissions are required to list tags.
        """
        try:
            tags_list = list(self.tags.values())
            return {"success": True, "data": tags_list}
        except Exception as e:
            return {"success": False, "error": f"Failed to retrieve tags: {str(e)}"}

    def check_tag_exists(self, tag_name: str) -> dict:
        """
        Verify whether a tag exists in the forum and is approved (i.e., moderated).

        Args:
            tag_name (str): The name of the tag to check.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "exists": bool,        # Whether the tag exists in the system
                    "is_approved": bool    # Whether the tag is approved (is_moderated == True)
                }
            }

        Note:
            - A tag may exist but not be approved (is_moderated == False).
            - If the tag does not exist, both 'exists' and 'is_approved' are False.
        """
        tag_info = self.tags.get(tag_name)
        if tag_info is not None:
            return {
                "success": True,
                "data": {
                    "exists": True,
                    "is_approved": tag_info["is_moderated"]
                }
            }
        return {
            "success": True,
            "data": {
                "exists": False,
                "is_approved": False
            }
        }

    def check_user_registration_status(self, user_id: str) -> dict:
        """
        Confirm whether a user is registered and eligible to create content.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "is_registered": bool  # True if user exists in the system, False otherwise
                }
            }

        Note:
            This operation always succeeds; if the user does not exist, it returns is_registered=False.
            It does not raise an error for unknown users, as checking existence is the purpose.
        """
        is_registered = user_id in self.users
        return {
            "success": True,
            "data": {
                "is_registered": is_registered
            }
        }


    def create_new_thread(self, title: str, author_id: str, category_id: str, content: str, tags: List[str] = None) -> Dict[str, any]:
        """
        Create a new discussion thread with an initial post in the specified category.

        Args:
            title (str): The title of the thread.
            author_id (str): The ID of the user creating the thread.
            category_id (str): The ID of the forum category to post in.
            content (str): The content of the initial post.
            tags (List[str], optional): List of tag names to associate with the thread. 
                                        Each tag must exist and be moderated.

        Returns:
            dict: {
                "success": True,
                "message": "Thread created successfully with ID: <thread_id>"
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - The author must be a registered user.
            - The category must exist.
            - All tags must exist and be moderated.
            - The thread and its initial post are created with current timestamps.
            - Only one initial post is created.
        """
        # Validate author exists
        if author_id not in self.users:
            return {"success": False, "error": "Author not registered"}

        # Validate category exists
        if category_id not in self.forum_categories:
            return {"success": False, "error": "Forum category does not exist"}

        # Initialize and validate tags
        if tags is None:
            tags = []
        for tag_name in tags:
            if tag_name not in self.tags:
                return {"success": False, "error": f"Tag '{tag_name}' does not exist"}
            if not self.tags[tag_name]["is_moderated"]:
                return {"success": False, "error": f"Tag '{tag_name}' is not approved"}

        # Generate unique thread_id and post_id
        thread_id = f"thread_{len(self.threads) + 1}"
        post_id = f"post_{len(self.posts) + 1}"
        current_time = time.time()

        # Create the thread
        new_thread: ThreadInfo = {
            "thread_id": thread_id,
            "title": title,
            "creation_timestamp": current_time,
            "last_activity_timestamp": current_time,
            "author_id": author_id,
            "forum_category": category_id,
            "tags": tags,
            "status": "open"
        }
        self.threads[thread_id] = new_thread

        # Create the initial post
        initial_post: PostInfo = {
            "post_id": post_id,
            "thread_id": thread_id,
            "author_id": author_id,
            "content": content,
            "creation_timestamp": current_time,
            "edit_timestamp": 0.0,
            "is_first_post": True
        }
        self.posts[post_id] = initial_post

        return {
            "success": True,
            "message": f"Thread created successfully with ID: {thread_id}"
        }

    def create_new_post(
        self,
        post_id: str,
        thread_id: str,
        author_id: str,
        content: str,
        creation_timestamp: float
    ) -> dict:
        """
        Add a reply post to an existing thread. Updates the thread's last_activity_timestamp.

        Args:
            post_id (str): Unique identifier for the new post.
            thread_id (str): ID of the thread to reply to.
            author_id (str): ID of the user creating the post.
            content (str): Text content of the post.
            creation_timestamp (float): Unix timestamp when the post is created.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success, confirmation message
                # or "error": str on failure
            }

        Constraints:
            - Only registered users can create posts.
            - The thread must exist and be open.
            - post_id must be unique.
            - The new post is not marked as the first post.
            - Thread's last_activity_timestamp is updated to creation_timestamp.
        """
        # Check if user exists (registered)
        if author_id not in self.users:
            return { "success": False, "error": "User not registered" }

        # Check if thread exists
        if thread_id not in self.threads:
            return { "success": False, "error": "Thread not found" }

        thread = self.threads[thread_id]

        # Check if thread is open
        if thread["status"] == "closed":
            return { "success": False, "error": "Cannot post in a closed thread" }

        # Check if post_id is already in use
        if post_id in self.posts:
            return { "success": False, "error": "Post ID already exists" }

        # Create new post
        new_post: PostInfo = {
            "post_id": post_id,
            "thread_id": thread_id,
            "author_id": author_id,
            "content": content,
            "creation_timestamp": creation_timestamp,
            "edit_timestamp": creation_timestamp,  # Initially same as creation
            "is_first_post": False
        }

        # Add post to posts dictionary
        self.posts[post_id] = new_post

        # Update thread's last activity timestamp
        thread["last_activity_timestamp"] = creation_timestamp

        return { "success": True, "message": "Post created and thread activity updated." }

    def edit_post(self, post_id: str, user_id: str, new_content: str, current_timestamp: float) -> dict:
        """
        Allow a user to edit their own post. Updates the post content and edit_timestamp.

        Args:
            post_id (str): The ID of the post to edit.
            user_id (str): The ID of the user attempting the edit.
            new_content (str): The new content for the post.
            current_timestamp (float): The current time as a Unix timestamp to set as edit_timestamp.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            } or {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Only the author of the post can edit it.
            - The post must exist.
            - The user must be registered.
            - Content must not be empty.
        """
        # Check if user is registered
        if user_id not in self.users:
            return { "success": False, "error": "User is not registered" }

        # Check if post exists
        if post_id not in self.posts:
            return { "success": False, "error": "Post does not exist" }

        post = self.posts[post_id]

        # Check if user is the author
        if post["author_id"] != user_id:
            # No indication in constraints that moderators can override, so deny
            return { "success": False, "error": "User does not have permission to edit this post" }

        # Validate new content
        if not new_content or not new_content.strip():
            return { "success": False, "error": "Post content cannot be empty" }

        # Update post content and edit timestamp
        post["content"] = new_content.strip()
        post["edit_timestamp"] = current_timestamp

        # Note: Thread last_activity_timestamp is not updated on edit (only on new posts)
        return { "success": True, "message": "Post edited successfully" }

    def close_thread(self, thread_id: str, user_id: str) -> dict:
        """
        Prevent further posts in a thread by setting its status to 'closed'.
        Only the thread author or a moderator can perform this action.

        Args:
            thread_id (str): The ID of the thread to close.
            user_id (str): The ID of the user attempting to close the thread.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - Only the thread's author or a user with role 'moderator' can close a thread.
            - The thread and user must exist.
            - The operation is idempotent (closing an already-closed thread is allowed).
        """
        if thread_id not in self.threads:
            return {"success": False, "error": "Thread not found"}

        if user_id not in self.users:
            return {"success": False, "error": "User not registered"}

        thread = self.threads[thread_id]
        user = self.users[user_id]

        # Check authorization: must be author or moderator
        if user["role"] != "moderator" and user["user_id"] != thread["author_id"]:
            return {"success": False, "error": "User not authorized to close this thread"}

        # Update thread status
        thread["status"] = "closed"

        return {"success": True, "message": "Thread closed successfully."}

    def reopen_thread(self, thread_id: str) -> dict:
        """
        Reopen a closed thread for new contributions.

        Args:
            thread_id (str): The unique identifier of the thread to reopen.

        Returns:
            dict: {
                "success": True,
                "message": "Thread reopened successfully."
            }
            or
            {
                "success": False,
                "error": str  # e.g. "Thread not found."
            }

        Constraints:
            - The thread must exist in the forum.
            - Only closed threads are affected; open threads remain unchanged.
            - No permission checking is performed in this method (assumed to be handled externally).
        """
        if thread_id not in self.threads:
            return { "success": False, "error": "Thread not found." }

        thread = self.threads[thread_id]
        thread["status"] = "open"

        return { "success": True, "message": "Thread reopened successfully." }

    def delete_post(self, post_id: str, requester_id: str) -> dict:
        """
        Remove a post from the forum. If the post is the first post in its thread,
        the entire thread (and all its posts) is deleted.

        Args:
            post_id (str): The ID of the post to delete.
            requester_id (str): The ID of the user attempting to delete the post.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: description of deletion
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Only the post author or a moderator can delete a post.
            - If the post is the first post in the thread, the entire thread is deleted.
            - A thread must have exactly one initial post; deleting it invalidates the thread.
        """
        # Check if post exists
        if post_id not in self.posts:
            return { "success": False, "error": "Post does not exist" }

        post = self.posts[post_id]
        thread_id = post["thread_id"]
        thread = self.threads.get(thread_id)

        # Check requester exists
        if requester_id not in self.users:
            return { "success": False, "error": "Requester is not a registered user" }

        requester = self.users[requester_id]

        # Check permission: must be author or moderator
        if requester["user_id"] != post["author_id"] and requester["role"] != "moderator":
            return { "success": False, "error": "Permission denied: only author or moderator can delete this post" }

        # If this is the first post, delete the entire thread
        if post["is_first_post"]:
            # Delete all posts in the thread
            posts_to_delete = [pid for pid, p in self.posts.items() if p["thread_id"] == thread_id]
            for pid in posts_to_delete:
                del self.posts[pid]

            # Delete the thread
            if thread_id in self.threads:
                del self.threads[thread_id]

            return { "success": True, "message": f"Post {post_id} and its entire thread have been deleted" }

        # Otherwise, just delete the post
        del self.posts[post_id]
        return { "success": True, "message": f"Post {post_id} deleted successfully" }

    def delete_thread(self, thread_id: str, user_id: str) -> dict:
        """
        Delete a thread and all its associated posts. Only moderators can perform this action.
        Also decrements the usage_count of each tag associated with the thread.

        Args:
            thread_id (str): The ID of the thread to delete.
            user_id (str): The ID of the user attempting the deletion.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - Only users with role 'moderator' can delete threads.
            - The thread must exist.
            - All associated posts are deleted.
            - Tag usage counts are decremented accordingly.
        """
        # Check if user exists
        if user_id not in self.users:
            return { "success": False, "error": "User not registered" }

        # Check if user is a moderator
        if self.users[user_id]["role"] != "moderator":
            return { "success": False, "error": "Permission denied: Only moderators can delete threads" }

        # Check if thread exists
        if thread_id not in self.threads:
            return { "success": False, "error": "Thread not found" }

        thread = self.threads[thread_id]

        # Delete all posts associated with the thread
        posts_to_delete = [pid for pid, post in self.posts.items() if post["thread_id"] == thread_id]
        for post_id in posts_to_delete:
            del self.posts[post_id]

        # Decrement usage count for each tag in the thread
        for tag_name in thread["tags"]:
            if tag_name in self.tags:
                self.tags[tag_name]["usage_count"] = max(0, self.tags[tag_name]["usage_count"] - 1)

        # Delete the thread itself
        del self.threads[thread_id]

        return { "success": True, "message": "Thread deleted successfully." }

    def add_new_tag(self, tag_name: str) -> dict:
        """
        Propose a new tag to the forum. The tag is added with is_moderated=False, indicating it is pending approval.

        Args:
            tag_name (str): The name of the tag to add. Must be a non-empty string.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Tag names must be unique.
            - New tags are added with usage_count=0 and is_moderated=False.
            - Only non-empty tag names are allowed.
        """
        if not tag_name or not tag_name.strip():
            return { "success": False, "error": "Tag name cannot be empty or whitespace" }

        tag_name = tag_name.strip()

        if tag_name in self.tags:
            return { "success": False, "error": f"Tag '{tag_name}' already exists" }

        new_tag: TagInfo = {
            "tag_name": tag_name,
            "usage_count": 0,
            "is_moderated": False
        }

        self.tags[tag_name] = new_tag

        return { 
            "success": True, 
            "message": f"Tag '{tag_name}' added successfully and is pending moderation." 
        }

    def approve_tag(self, tag_name: str) -> dict:
        """
        Approve a pending tag, making it available for use in threads.

        Args:
            tag_name (str): The name of the tag to approve.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation of approval
            }
            or
            {
                "success": False,
                "error": str  # Description of failure (e.g. tag not found, already approved)
            }

        Constraints:
            - The tag must exist in the system.
            - Only unapproved (pending) tags can be approved.
            - This action is typically restricted to moderators (caller assumed authorized).
        """
        if tag_name not in self.tags:
            return { "success": False, "error": f"Tag '{tag_name}' does not exist." }

        tag_info = self.tags[tag_name]

        if tag_info["is_moderated"]:
            return { "success": False, "error": f"Tag '{tag_name}' is already approved." }

        # Approve the tag
        self.tags[tag_name]["is_moderated"] = True

        return { "success": True, "message": f"Tag '{tag_name}' approved successfully." }

    def update_thread_tags(
        self,
        thread_id: str,
        user_id: str,
        add_tags: List[str] = None,
        remove_tags: List[str] = None
    ) -> dict:
        """
        Add or remove tags from an existing thread. Only the thread author or a moderator can perform this action.

        Args:
            thread_id (str): The ID of the thread to update.
            user_id (str): The ID of the user attempting the update.
            add_tags (List[str], optional): List of tag names to add. Defaults to empty list.
            remove_tags (List[str], optional): List of tag names to remove. Defaults to empty list.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Description of success or failure
            }

        Constraints:
            - Only the thread author or a user with role 'moderator' can update tags.
            - Tags must exist in the system (i.e., be registered in self.tags) to be added.
            - Cannot add unapproved or non-existent tags.
        """
        add_tags = add_tags or []
        remove_tags = remove_tags or []

        # Check if thread exists
        if thread_id not in self.threads:
            return {
                "success": False,
                "error": "Thread does not exist"
            }

        # Check if user exists
        if user_id not in self.users:
            return {
                "success": False,
                "error": "User does not exist"
            }

        thread = self.threads[thread_id]
        user = self.users[user_id]

        # Check authorization: must be thread author or moderator
        if user["user_id"] != thread["author_id"] and user["role"] != "moderator":
            return {
                "success": False,
                "error": "Permission denied: Only the thread author or a moderator can update tags"
            }

        # Validate all tags to be added
        for tag_name in add_tags:
            if tag_name not in self.tags:
                return {
                    "success": False,
                    "error": f"Tag '{tag_name}' does not exist or is not approved and cannot be added"
                }

        # Update tags: add valid ones, remove requested ones
        current_tags = set(thread["tags"])  # Use set to avoid duplicates
        current_tags.difference_update(remove_tags)  # Remove requested
        current_tags.update(add_tags)  # Add new ones

        # Convert back to list and update thread
        thread["tags"] = list(current_tags)

        return {
            "success": True,
            "message": "Thread tags updated successfully"
        }

    def update_thread_category(self, thread_id: str, new_category_id: str, user_id: str) -> dict:
        """
        Move a thread to a different forum category. Only moderators can perform this action.

        Args:
            thread_id (str): The ID of the thread to move.
            new_category_id (str): The ID of the target forum category.
            user_id (str): The ID of the user attempting the operation (must be a moderator).

        Returns:
            dict: {
                "success": True,
                "message": "Thread moved to new category successfully."
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - The user must have the role 'moderator'.
            - The thread must exist.
            - The new category must exist.
            - Each thread must belong to exactly one forum category (enforced by valid assignment).
        """
        # Check if user exists and is a moderator
        if user_id not in self.users:
            return {"success": False, "error": "User not found"}
        if self.users[user_id]["role"] != "moderator":
            return {"success": False, "error": "Permission denied: Only moderators can update thread category"}

        # Check if thread exists
        if thread_id not in self.threads:
            return {"success": False, "error": "Thread not found"}

        # Check if new category exists
        if new_category_id not in self.forum_categories:
            return {"success": False, "error": "Target category not found"}

        # Update the thread's category
        self.threads[thread_id]["forum_category"] = new_category_id

        return {
            "success": True,
            "message": "Thread moved to new category successfully."
        }

    def bump_thread(self, thread_id: str, current_timestamp: float) -> dict:
        """
        Manually update the last_activity_timestamp of a thread to bring it to the top of listings.

        Args:
            thread_id (str): The unique identifier of the thread to bump.
            current_timestamp (float): The current Unix timestamp to set as the last activity time.

        Returns:
            dict: {
                "success": True,
                "message": "Thread bumped successfully"
            }
            or
            {
                "success": False,
                "error": "Thread does not exist"
            }

        Constraints:
            - The thread must exist in the forum.
            - The last_activity_timestamp is updated unconditionally if the thread exists.
        """
        if thread_id not in self.threads:
            return {"success": False, "error": "Thread does not exist"}

        self.threads[thread_id]["last_activity_timestamp"] = current_timestamp

        return {"success": True, "message": "Thread bumped successfully"}

