from typing import Dict, List, TypedDict
from datetime import datetime



class CategoryInfo(TypedDict):
    category_id: str
    name: str
    description: str

class CommodityInfo(TypedDict):
    commodity_id: str
    name: str
    quote_date: str
    rating: str
    unit_price: float

class ServiceInfo(TypedDict):
    service_id: str
    name: str
    status: str
    last_updated: str
    provider: str

class EmployeeInfo(TypedDict):
    employee_id: str
    name: str
    department: str
    role: str
    status: str
    contact_info: str

class OrderInfo(TypedDict):
    order_id: str
    order_date: str
    category_id: str
    item_list: List[str]
    status: str
    total_val: float

class ERPSystem:
    def __init__(self):
        """
        Enterprise Resource Planning (ERP) system integrating finance, HR, supply chain, and operations.
        """

        # Categories: {category_id: CategoryInfo}
        self.categories: Dict[str, CategoryInfo] = {}

        # Commodities: {commodity_id: CommodityInfo}
        self.commodities: Dict[str, CommodityInfo] = {}

        # Services: {service_id: ServiceInfo}
        self.services: Dict[str, ServiceInfo] = {}

        # Employees: {employee_id: EmployeeInfo}
        self.employees: Dict[str, EmployeeInfo] = {}

        # Orders: {order_id: OrderInfo}
        self.orders: Dict[str, OrderInfo] = {}

        # Constraints reminder:
        # - Each order must be associated with one or more valid categories (referential integrity)
        # - Commodity ratings are updated daily and are only valid for their specified quote_date
        # - Service status must be one of: 'active', 'inactive', 'maintenance', 'disrupted'
        # - Employee IDs are unique and must be valid for access
        # - The system ensures referential integrity (e.g., category_id in orders must exist in self.categories)

    def get_orders_by_date(self, order_date: str) -> dict:
        """
        Retrieve all orders placed on a specific date.

        Args:
            order_date (str): The date of the orders to retrieve, in 'YYYY-MM-DD' format.

        Returns:
            dict: {
                "success": True,
                "data": List[OrderInfo]  # List of orders with matching order_date (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Only if input validation fails (e.g. empty date string)
            }

        Constraints:
            - The operation performs exact string match on order_date.
            - Referential integrity (e.g. valid category_id) is assumed to be enforced at order creation.
        """
        if not order_date or not isinstance(order_date, str):
            return { "success": False, "error": "Invalid input: order_date must be a non-empty string" }

        result = [
            order for order in self.orders.values()
            if order["order_date"] == order_date
        ]

        return { "success": True, "data": result }

    def get_order_by_id(self, order_id: str) -> dict:
        """
        Fetch detailed information about a specific order using its order_id.

        Args:
            order_id (str): The unique identifier of the order to retrieve.

        Returns:
            dict: {
                "success": True,
                "data": OrderInfo  # Complete order information
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Order not found"
            }

        Constraints:
            - The order_id must correspond to an existing order in the system.
            - Referential integrity is assumed to have been enforced at creation time.
        """
        order = self.orders.get(order_id)
        if order is None:
            return {"success": False, "error": "Order not found"}
        return {"success": True, "data": order}

    def get_category_by_id(self, category_id: str) -> dict:
        """
        Retrieve category information (name, description) by category_id.

        Args:
            category_id (str): The unique identifier of the category.

        Returns:
            dict: {
                "success": bool,
                "data": CategoryInfo   # Only present if success is True
            }
            or
            {
                "success": False,
                "error": str           # Description of the error
            }

        Constraints:
            - The category_id must correspond to an existing category.
        """
        if not category_id:
            return { "success": False, "error": "Category ID cannot be empty" }

        category = self.categories.get(category_id)
        if not category:
            return { "success": False, "error": "Category not found" }

        return { "success": True, "data": category }

    def list_all_categories(self) -> dict:
        """
        Retrieve the full list of product or service categories in the system.

        Returns:
            dict: {
                "success": True,
                "data": List[CategoryInfo]  # List of all categories; empty list if none exist
            }

        Constraints:
            - None; this is a read-only operation that always succeeds.
        """
        return {
            "success": True,
            "data": list(self.categories.values())
        }

    def get_commodity_by_name(self, name: str) -> dict:
        """
        Retrieve commodity details by its name (e.g., 'Silver').

        Args:
            name (str): The name of the commodity to search for.

        Returns:
            dict: {
                "success": True,
                "data": CommodityInfo  # Contains commodity_id, name, quote_date, rating, unit_price
            }
            or
            {
                "success": False,
                "error": "Commodity not found"
            }

        Constraints:
            - The commodity name must exist in the system.
            - Multiple commodities with the same name may exist; this returns the first match.
        """
        for commodity in self.commodities.values():
            if commodity["name"] == name:
                return {"success": True, "data": commodity}
        return {"success": False, "error": "Commodity not found"}

    def get_commodity_by_id(self, commodity_id: str) -> dict:
        """
        Retrieve commodity information using its unique commodity_id.

        Args:
            commodity_id (str): The unique identifier of the commodity.

        Returns:
            dict: {
                "success": True,
                "data": CommodityInfo  # The commodity's information
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Commodity not found"
            }

        Constraints:
            - The commodity_id must exist in the system.
        """
        if not commodity_id:
            return {"success": False, "error": "Commodity ID cannot be empty"}

        commodity = self.commodities.get(commodity_id)
        if commodity is None:
            return {"success": False, "error": "Commodity not found"}

        return {"success": True, "data": commodity}

    def get_commodity_rating_by_date(self, commodity_id: str, quote_date: str) -> dict:
        """
        Retrieve the rating of a commodity on a specific quote_date to ensure temporal validity.

        Args:
            commodity_id (str): The unique identifier of the commodity.
            quote_date (str): The date (YYYY-MM-DD format) for which the rating is requested.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "commodity_id": str,
                    "rating": str,
                    "quote_date": str
                }
            }
            or
            {
                "success": False,
                "error": str  # e.g. "Commodity not found" or "Rating not valid for the given date"
            }

        Constraints:
            - The commodity must exist.
            - The rating is only valid if the given quote_date matches the commodity's quote_date.
        """
        if commodity_id not in self.commodities:
            return { "success": False, "error": "Commodity not found" }

        commodity = self.commodities[commodity_id]

        if commodity["quote_date"] != quote_date:
            return { "success": False, "error": "Rating not valid for the given date" }

        return {
            "success": True,
            "data": {
                "commodity_id": commodity_id,
                "rating": commodity["rating"],
                "quote_date": quote_date
            }
        }

    def get_service_status(self, service_id: str) -> dict:
        """
        Retrieve the current status of a service by its service_id.

        Args:
            service_id (str): The unique identifier of the service.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "status": str  # One of: 'active', 'inactive', 'maintenance', 'disrupted'
                }
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., service not found
            }

        Constraints:
            - service_id must exist in the system.
        """
        if not service_id:
            return {"success": False, "error": "Service ID is required"}

        service = self.services.get(service_id)
        if not service:
            return {"success": False, "error": "Service not found"}

        return {"success": True, "data": {"status": service["status"]}}

    def get_service_by_id(self, service_id: str) -> dict:
        """
        Fetch full details of a service including provider and last_updated timestamp.

        Args:
            service_id (str): The unique identifier of the service.

        Returns:
            dict: {
                "success": True,
                "data": ServiceInfo,  # Full service details
            }
            or
            {
                "success": False,
                "error": str  # Error message, e.g., "Service not found"
            }

        Constraints:
            - The service_id must correspond to an existing service in the system.
        """
        if not service_id:
            return { "success": False, "error": "Service ID cannot be empty" }

        service_info = self.services.get(service_id)
        if service_info is None:
            return { "success": False, "error": "Service not found" }

        return { "success": True, "data": service_info }

    def list_all_services(self) -> dict:
        """
        Retrieve a list of all operational services in the system.

        Returns:
            dict: {
                "success": True,
                "data": List[ServiceInfo]  # List of all service records; empty list if none exist
            }
            or
            {
                "success": False,
                "error": str  # Description of any error encountered
            }

        Constraints:
            - None (no parameters).
            - Service status values are expected to be one of: 'active', 'inactive', 'maintenance', 'disrupted'.
        """
        try:
            # Extract all service info from the services dictionary
            all_services = list(self.services.values())
            return {"success": True, "data": all_services}
        except Exception as e:
            return {"success": False, "error": f"Failed to retrieve services: {str(e)}"}

    def get_employee_by_id(self, employee_id: str) -> dict:
        """
        Retrieve employee details using their unique employee_id.

        Args:
            employee_id (str): The unique identifier of the employee.

        Returns:
            dict: {
                "success": True,
                "data": EmployeeInfo  # Full employee details
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. "Employee not found"
            }

        Constraints:
            - Employee IDs must exist in the system (referential integrity).
        """
        if not isinstance(employee_id, str):
            return { "success": False, "error": "Invalid employee_id type: must be a string" }

        employee = self.employees.get(employee_id)
        if employee is None:
            return { "success": False, "error": "Employee not found" }

        return { "success": True, "data": employee }

    def get_employee_by_name(self, name: str) -> dict:
        """
        Look up employee information by name. May return multiple employees if they share the same name.

        Args:
            name (str): The name of the employee to search for.

        Returns:
            dict: {
                "success": True,
