        """
        Mark a category as inactive by removing it from the active category set, provided
        it is not referenced by any existing order. Historical data is preserved in logs
        (simulated), but the category is no longer available for new associations.

        Args:
            category_id (str): The unique identifier of the category to deactivate.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The category must exist.
            - The category cannot be referenced by any order (referential integrity).
            - Deactivation does not delete historical records but removes it from active use.
        """
        if category_id not in self.categories:
            return { "success": False, "error": "Category not found" }

        # Check if any order references this category_id
        for order in self.orders.values():
            if order["category_id"] == category_id:
                return {
                    "success": False,
                    "error": f"Cannot deactivate category '{category_id}': referenced by order {order['order_id']}"
                }

        # Safe to deactivate (remove from active categories)
        del self.categories[category_id]

        return {
            "success": True,
            "message": f"Category '{category_id}' has been deactivated successfully"
        }

    def bulk_update_commodity_prices(self, updates: List[Dict[str, str]]) -> dict:
        """
        Update prices, ratings, and quote dates for multiple commodities in bulk.

        Args:
            updates (List[Dict]): Each dict contains:
                - 'commodity_id' (str): ID of the commodity to update.
                - 'unit_price' (float): New unit price (must be float or float-convertible).
                - 'rating' (str): New rating.
                - 'quote_date' (str): New quote date in YYYY-MM-DD format.

        Returns:
            dict: {
                "success": True,
                "message": "Updated prices and ratings for N commodities."
            }
            or
            {
                "success": False,
                "error": str  # e.g., "Commodity with ID 'X' not found."
            }

        Constraints:
            - All commodity_ids must exist in the system.
            - Commodity ratings are valid only for their quote_date, so both are updated together.
        """
        if not isinstance(updates, list):
            return { "success": False, "error": "Updates must be a list." }

        for i, update in enumerate(updates):
            if not isinstance(update, dict):
                return { "success": False, "error": f"Update at index {i} is not a dictionary." }
            required_keys = {'commodity_id', 'unit_price', 'rating', 'quote_date'}
            if not required_keys.issubset(update.keys()):
                return { "success": False, "error": f"Update at index {i} missing required keys: {required_keys - update.keys()}" }
            try:
                # Validate types
                commodity_id = update['commodity_id']
                unit_price = float(update['unit_price'])
                rating = update['rating']
                quote_date = update['quote_date']
            except (ValueError, TypeError) as e:
                return { "success": False, "error": f"Invalid data type in update at index {i}: {str(e)}" }

            if commodity_id not in self.commodities:
                return { "success": False, "error": f"Commodity with ID '{commodity_id}' not found." }

        # All validations passed: apply updates
        for update in updates:
            commodity_id = update['commodity_id']
            self.commodities[commodity_id]['unit_price'] = float(update['unit_price'])
            self.commodities[commodity_id]['rating'] = update['rating']
            self.commodities[commodity_id]['quote_date'] = update['quote_date']

        n_updated = len(updates)
        return {
            "success": True,
            "message": f"Updated prices and ratings for {n_updated} commodities."
        }

