from datetime import datetime



class CategoryInfo(TypedDict):
    category_id: str
    name: str
    description: str

class CommodityInfo(TypedDict):
    commodity_id: str
    name: str
    quote_date: str
    rating: str
    unit_price: float

class ServiceInfo(TypedDict):
    service_id: str
    name: str
    status: str
    last_updated: str
    provider: str

class EmployeeInfo(TypedDict):
    employee_id: str
    name: str
    department: str
    role: str
    status: str
    contact_info: str

class OrderInfo(TypedDict):
    order_id: str
    order_date: str
    category_id: str
    item_list: List[str]
    status: str
    total_val: float

