            }

        Constraints:
            - Service must exist in the system.
            - Status value must be valid.
        """

        valid_statuses = {'active', 'inactive', 'maintenance', 'disrupted'}

        if service_id not in self.services:
            return { "success": False, "error": "Service not found" }

        if new_status not in valid_statuses:
            return { "success": False, "error": f"Status '{new_status}' is invalid. Allowed: {sorted(valid_statuses)}" }

