from typing import Dict, List, TypedDict



class ProjectInfo(TypedDict):
    project_id: str
    name: str
    description: str
    base_system: str
    status: str

class RepositoryItemInfo(TypedDict):
    m_id: str
    name: str
    path: str
    type: str  # Must be one of: "design", "code", "documentation"
    version: str
    last_modified: str
    author: str

class VersionHistoryInfo(TypedDict):
    m_id: str
    version: str
    change_log: str
    timestamp: str
    commit_message: str

class ReviewInfo(TypedDict):
    view_id: str
    item_id: str
    reviewer: str
    status: str  # e.g., "pending", "completed"
    comment: str

class SoftwareProjectRepository:
    def __init__(self):
        """
        A software project repository environment supporting version control,
        collaborative reviews, and project-based organization of assets.
        """

        # Projects: {project_id: ProjectInfo}
        self.projects: Dict[str, ProjectInfo] = {}

        # Repository items: {m_id: RepositoryItemInfo}
        self.repository_items: Dict[str, RepositoryItemInfo] = {}

        # Version history: {m_id: [VersionHistoryInfo, ...]}
        self.version_history: Dict[str, List[VersionHistoryInfo]] = {}

        # Reviews: {view_id: ReviewInfo}
        self.reviews: Dict[str, ReviewInfo] = {}

        # Constraints:
        # - Repository items must be associated with a project (enforced via project_id reference)
        # - RepositoryItem.type must be 'design', 'code', or 'documentation'
        # - Only items with type='design' in projects where base_system='Apollo' are eligible for UI design review
        # - Access to items may depend on user permissions (not modeled in state)

    def get_project_by_id(self, project_id: str) -> dict:
        """
        Retrieve full metadata of a project using its project_id.

        Args:
            project_id (str): The unique identifier of the project.

        Returns:
            dict: {
                "success": True,
                "data": ProjectInfo  # The complete project metadata
            }
            or
            {
                "success": False,
                "error": str  # "Project not found"
            }

        Constraints:
            - The project_id must exist in the repository.
        """
        project = self.projects.get(project_id)
        if not project:
            return {"success": False, "error": "Project not found"}

        return {"success": True, "data": project}

    def list_projects_by_base_system(self, base_system: str) -> dict:
        """
        List all projects that are based on a specific system.

        Args:
            base_system (str): The name of the base system (e.g., "Apollo") to filter projects by.

        Returns:
            dict: {
                "success": True,
                "data": List[ProjectInfo]  # List of projects where base_system matches input
            }
            or
            {
                "success": False,
                "error": str  # Description of error (e.g., invalid input type)
            }

        Constraints:
            - The operation filters projects whose 'base_system' field exactly matches the input.
            - No permission checks are enforced in this simulation.
        """
        if not isinstance(base_system, str):
            return { "success": False, "error": "base_system must be a string" }

        result = [
            project_info for project_info in self.projects.values()
            if project_info["base_system"] == base_system
        ]

        return { "success": True, "data": result }

    def find_design_items_by_project(self, project_id: str) -> dict:
        """
        Retrieve all repository items of type "design" associated with the given project.

        Args:
            project_id (str): The ID of the project to find design items for.

        Returns:
            dict: {
                "success": True,
                "data": List[RepositoryItemInfo]  # List of design-type items under the project
            }
            or
            {
                "success": False,
                "error": str  # e.g., "Project not found"
            }

        Constraints:
            - Only items with type == "design" are included.
            - An item is considered associated with the project if its path starts with the project_id
              (with optional leading slash).
        """
        if project_id not in self.projects:
            return {"success": False, "error": "Project not found"}

        # Normalize project_id for path matching (ensure it can match paths like "/{project_id}/...")
        prefix1 = f"{project_id}/"
        prefix2 = f"/{project_id}/"

        design_items = []
        for item in self.repository_items.values():
            # Check if item is of type "design"
            if item["type"] != "design":
                continue
            # Check if path starts with project_id or /project_id/
            if item["path"].startswith(prefix1) or item["path"].startswith(prefix2):
                design_items.append(item)

        return {"success": True, "data": design_items}

    def get_repository_item_by_id(self, m_id: str) -> dict:
        """
        Retrieve full metadata of a repository item by its unique identifier (m_id).

        Args:
            m_id (str): The unique identifier of the repository item.

        Returns:
            dict: {
                "success": True,
                "data": RepositoryItemInfo  # Full metadata of the item
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Repository item not found"
            }

        Constraints:
            - The m_id must correspond to an existing repository item.
        """
        item = self.repository_items.get(m_id)
        if not item:
            return {"success": False, "error": "Repository item not found"}

        return {"success": True, "data": item}

    def get_repository_item_by_path(self, path: str) -> dict:
        """
        Retrieve a repository item using its file path within the project.

        Args:
            path (str): The absolute path of the repository item (e.g., '/src/main.py').

        Returns:
            dict: {
                "success": True,
                "data": RepositoryItemInfo
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Repository item not found"
            }

        Constraints:
            - The path must uniquely identify a repository item.
            - Repository items must be associated with a project (assumed, not validated here).
        """
        for item in self.repository_items.values():
            if item["path"] == path:
                return { "success": True, "data": item }
        return { "success": False, "error": "Repository item not found" }

    def list_items_by_type(self, item_type: str) -> dict:
        """
        List all repository items filtered by their type.

        Args:
            item_type (str): The type of items to retrieve. Must be one of: 
                             "design", "code", "documentation".

        Returns:
            dict: {
                "success": True,
                "data": List[RepositoryItemInfo]  # List of items matching the type (may be empty)
            }
            or
            {
                "success": False,
                "error": "Invalid item type"
            }

        Constraints:
            - The item_type must be one of: "design", "code", "documentation".
            - Repository items must be associated with a project (but not checked here).
        """
        allowed_types = {"design", "code", "documentation"}
        if item_type not in allowed_types:
            return {"success": False, "error": "Invalid item type"}

        result = [
            item for item in self.repository_items.values()
            if item["type"] == item_type
        ]

        return {"success": True, "data": result}

    def get_latest_version_info(self, item_id: str) -> dict:
        """
        Retrieve the latest version entry (version, timestamp, commit_message) for a repository item.

        Args:
            item_id (str): The m_id of the repository item.

        Returns:
            dict: {
                "success": bool,
                "data": {
                    "version": str,
                    "timestamp": str,
                    "commit_message": str
                } | None  # None if item exists but has no version history
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. item not found
            }

        Constraints:
            - The item_id must correspond to an existing repository item.
            - Version history is assumed to be in chronological order; latest version is last.
        """
        if item_id not in self.repository_items:
            return {"success": False, "error": "Repository item not found"}

        version_list = self.version_history.get(item_id, [])

        if not version_list:
            return {"success": True, "data": None}

        latest_version = version_list[-1]  # Assume list is chronological; last is newest
        return {
            "success": True,
            "data": {
                "version": latest_version["version"],
                "timestamp": latest_version["timestamp"],
                "commit_message": latest_version["commit_message"]
            }
        }

    def get_version_history(self, item_id: str) -> dict:
        """
        Retrieve the full version history for a given repository item.

        Args:
            item_id (str): The unique identifier (m_id) of the repository item.

        Returns:
            dict: {
                "success": True,
                "data": List[VersionHistoryInfo]  # List of version records, may be empty
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. item not found
            }

        Constraints:
            - The item_id must correspond to an existing repository item.
            - Version history is maintained per item and may be empty.
        """
        if item_id not in self.repository_items:
            return {"success": False, "error": "Repository item not found"}

        history = self.version_history.get(item_id, [])

        return {"success": True, "data": history}

    def check_review_status(self, item_id: str) -> dict:
        """
        Check whether a repository item has an active or completed review by querying via item_id.

        Args:
            item_id (str): The unique identifier of the repository item.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "reviews": List[ReviewInfo]  # List of all reviews associated with the item_id (may be empty)
                }
            }
            or
            {
                "success": False,
                "error": str  # Only in case of invalid input
            }

        Note:
            - Returns an empty list if no reviews are found for the item.
            - Does not validate whether the item_id corresponds to an existing repository item.
        """
        if not isinstance(item_id, str) or not item_id.strip():
            return { "success": False, "error": "Invalid item_id: must be a non-empty string" }

        item_id = item_id.strip()
        matching_reviews = [
            review for review in self.reviews.values()
            if review["item_id"] == item_id
        ]

        return {
            "success": True,
            "data": { "reviews": matching_reviews }
        }

    def get_review_details(self, view_id: str) -> dict:
        """
        Retrieve full review information including reviewer, comment, and status by view_id.

        Args:
            view_id (str): The unique identifier of the review.

        Returns:
            dict: {
                "success": True,
                "data": ReviewInfo  # Full review details
            }
            or
            {
                "success": False,
                "error": str  # e.g., "Review not found"
            }

        Constraints:
            - The view_id must exist in the system.
        """
        review = self.reviews.get(view_id)
        if review is None:
            return { "success": False, "error": "Review not found" }

        return { "success": True, "data": review }

    def list_pending_reviews(self) -> dict:
        """
        Retrieve all reviews with status "pending" to identify open review tasks.

        Returns:
            dict: {
                "success": True,
                "data": List[ReviewInfo]  # List of reviews where status is "pending" (may be empty)
            }

        Constraints:
            - Only reviews with status "pending" are included.
            - All reviews are stored in the system and accessible.
        """
        pending_reviews = [
            review_info for review_info in self.reviews.values()
            if review_info["status"] == "pending"
        ]
        return { "success": True, "data": pending_reviews }

    def create_review_request(
        self,
        view_id: str,
        item_id: str,
        reviewer: str,
        comment: str = ""
    ) -> dict:
        """
        Initiate a new review for a design item by creating a review entry with status "pending".

        Args:
            view_id (str): Unique identifier for the review request.
            item_id (str): The m_id of the repository item to be reviewed.
            reviewer (str): Name or ID of the reviewer.
            comment (str, optional): Optional initial comment for the review. Defaults to empty string.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
            }
            or
            {
                "success": False,
                "error": str  # Description of failure
            }

        Constraints:
            - The item must exist in the repository.
            - The item must be of type "design".
            - The view_id must be unique (no existing review with that ID).
        """
        # Check if item_id exists
        if item_id not in self.repository_items:
            return { "success": False, "error": "Repository item does not exist" }

        item = self.repository_items[item_id]

        # Check if item is of type "design"
        if item["type"] != "design":
            return { "success": False, "error": "Only design items can be reviewed" }

        # Check if view_id already exists
        if view_id in self.reviews:
            return { "success": False, "error": "Review request with this view_id already exists" }

        # Create new review entry
        review_entry: ReviewInfo = {
            "view_id": view_id,
            "item_id": item_id,
            "reviewer": reviewer,
            "status": "pending",
            "comment": comment
        }

        self.reviews[view_id] = review_entry

        return { "success": True, "message": "Review request created successfully" }

    def update_review_status(self, view_id: str, new_status: str) -> dict:
        """
        Update the status of an existing review.

        Args:
            view_id (str): The unique identifier of the review to update.
            new_status (str): The new status to assign (e.g., "pending", "completed").

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present if success is True
            }
            or
            {
                "success": False,
                "error": str  # Description of the failure
            }

        Constraints:
            - The review must exist (view_id must be in self.reviews).
            - The new_status should be a non-empty string; allowed values are not strictly enforced
              but expected to be among: "pending", "completed".
        """
        if not view_id:
            return {"success": False, "error": "Review ID (view_id) is required."}

        if not new_status or not isinstance(new_status, str):
            return {"success": False, "error": "New status must be a non-empty string."}

        if view_id not in self.reviews:
            return {"success": False, "error": "Review not found."}

        # Update the status
        self.reviews[view_id]["status"] = new_status

        return {"success": True, "message": "Review status updated successfully."}

    def add_review_comment(self, view_id: str, comment: str) -> dict:
        """
        Add or update a comment in an existing review.

        Args:
            view_id (str): The unique identifier of the review.
            comment (str): The comment to add or update.

        Returns:
            dict: {
                "success": True,
                "message": "Comment added to review with view_id: <view_id>"
            }
            or
            {
                "success": False,
                "error": "Review not found"
            }

        Constraints:
            - The review identified by `view_id` must exist in the repository.
            - The comment can be any string (including empty), as no restrictions are enforced.
        """
        if view_id not in self.reviews:
            return {"success": False, "error": "Review not found"}

        self.reviews[view_id]["comment"] = comment
        return {
            "success": True,
            "message": f"Comment added to review with view_id: {view_id}"
        }

    def update_repository_item(
        self,
        item_id: str,
        new_version: str,
        change_log: str,
        commit_message: str = "",
        timestamp: str = ""
    ) -> dict:
        """
        Update a repository item's metadata (e.g., version, last_modified) and record the change in version history.

        Args:
            item_id (str): The unique ID (m_id) of the repository item to update.
            new_version (str): The new version string (e.g., "v2.1.0").
            change_log (str): Description of the changes made to the item.
            commit_message (str, optional): A message describing the update. Defaults to empty string.
            timestamp (str, optional): The timestamp of the update (e.g., ISO format). If empty, current time can be used.
                                      However, expected to be provided.

        Returns:
            dict: {
                "success": True,
                "message": "Repository item updated and version recorded."
            }
            or
            {
                "success": False,
                "error": str  # e.g., "Repository item not found."
            }

        Constraints:
            - The item_id must exist in the repository.
            - A new version entry will be appended to the version history.
        """
        if item_id not in self.repository_items:
            return { "success": False, "error": "Repository item not found." }

        # Update the repository item
        item = self.repository_items[item_id]
        item["version"] = new_version
        if timestamp:
            item["last_modified"] = timestamp

        # Initialize version history for this item if not present
        if item_id not in self.version_history:
            self.version_history[item_id] = []

        # Create and append version history entry
        version_entry: VersionHistoryInfo = {
            "m_id": item_id,
            "version": new_version,
            "change_log": change_log,
            "timestamp": timestamp or item["last_modified"],
            "commit_message": commit_message
        }
        self.version_history[item_id].append(version_entry)

        return {
            "success": True,
            "message": "Repository item updated and version recorded."
        }

    def record_new_version(
        self,
        m_id: str,
        version: str,
        change_log: str,
        timestamp: str,
        commit_message: str
    ) -> dict:
        """
        Add a new version entry to the version history of a repository item.

        Args:
            m_id (str): The unique identifier of the repository item.
            version (str): The version string (e.g., 'v1.2').
            change_log (str): A description of changes made in this version.
            timestamp (str): The time when the version was created (ISO format or similar).
            commit_message (str): The message associated with the version commit.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. item not found
            }

        Constraints:
            - The repository item with the given m_id must exist.
            - Version history is maintained as a chronological list (oldest first).
        """
        if m_id not in self.repository_items:
            return { "success": False, "error": "Repository item not found" }

        # Initialize version history for this item if not present
        if m_id not in self.version_history:
            self.version_history[m_id] = []

        # Create new version entry
        new_version: VersionHistoryInfo = {
            "m_id": m_id,
            "version": version,
            "change_log": change_log,
            "timestamp": timestamp,
            "commit_message": commit_message
        }

        self.version_history[m_id].append(new_version)

        return {
            "success": True,
            "message": f"New version recorded for item {m_id}"
        }

    def associate_item_with_project(self, item_id: str, project_id: str) -> dict:
        """
        Link a repository item to a project, ensuring both entities exist and constraints are satisfied.

        Args:
            item_id (str): The m_id of the repository item to associate.
            project_id (str): The ID of the project to associate the item with.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": bool,
                "error": str  # On failure
            }

        Constraints:
            - Both the project and repository item must exist in the system.
            - Repository items must be associated with a project (enforced by this check).
            - No physical link is stored; association is logical and validated at call time.
        """
        if project_id not in self.projects:
            return { "success": False, "error": "Project not found" }

        if item_id not in self.repository_items:
            return { "success": False, "error": "Repository item not found" }

        return {
            "success": True,
            "message": "Repository item associated with project successfully."
        }

    def delete_review(self, view_id: str) -> dict:
        """
        Remove a review entry from the repository by its view_id.

        Args:
            view_id (str): The unique identifier of the review to delete.

        Returns:
            dict: {
                "success": True,
                "message": "Review deleted successfully"
            }
            or
            {
                "success": False,
                "error": "Review with given view_id not found"
            }

        Constraints:
            - The review must exist in the system to be deleted.
        """
        if not isinstance(view_id, str) or view_id == "":
            return { "success": False, "error": "Invalid view_id: must be a non-empty string" }

        if view_id not in self.reviews:
            return { "success": False, "error": "Review with given view_id not found" }

        del self.reviews[view_id]
        return { "success": True, "message": "Review deleted successfully" }

    def cancel_review_request(self, view_id: str) -> dict:
        """
        Cancel a pending review request by setting its status to "cancelled".

        Args:
            view_id (str): The unique identifier of the review request to cancel.

        Returns:
            dict: {
                "success": True,
                "message": "Review request cancelled successfully"
            }
            or
            {
                "success": False,
                "error": "Review not found"
            }

        Constraints:
            - The review must exist in the system.
            - No restrictions on current status (can cancel from any state).
        """
        if view_id not in self.reviews:
            return {"success": False, "error": "Review not found"}

        self.reviews[view_id]["status"] = "cancelled"
        return {"success": True, "message": "Review request cancelled successfully"}

