from typing import Dict, Any, TypedDict
import time
from typing import Any



class SearchRequestInfo(TypedDict):
    request_id: str
    query_params: Any
    status: str
    result: Any
    created_at: float
    updated_at: float

class SearchProcessingSystem:
    def __init__(self):
        """
        A stateful search processing system that tracks user search requests.
        """
        # Requests: {request_id: SearchRequestInfo}
        self.requests: Dict[str, SearchRequestInfo] = {}

        # Constraints reminder:
        # - Each request_id must be unique
        # - Status transitions are sequential (e.g., submitted → processing → completed/failed)
        # - The result field is only populated when status is "completed" or "failed"
        # - Only existing request IDs can be queried

    def get_request_status(self, request_id: str) -> dict:
        """
        Retrieve the current status of a search request by its request ID.

        Args:
            request_id (str): The unique identifier of the search request.

        Returns:
            dict: {
                "success": True,
                "data": str  # The current status (e.g., "submitted", "processing", "completed", "failed")
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Request not found"
            }

        Constraints:
            - The request_id must correspond to an existing request.
        """
        if request_id not in self.requests:
            return {"success": False, "error": "Request not found"}

        status = self.requests[request_id]["status"]
        return {"success": True, "data": status}

    def get_request_result(self, request_id: str) -> dict:
        """
        Retrieve the result of a completed or failed search request, if available.

        Args:
            request_id (str): The unique identifier of the search request.

        Returns:
            dict: {
                "success": True,
                "data": Any  # The result of the search request
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g. request not found, result not ready)
            }

        Constraints:
            - Only existing request IDs can be queried.
            - Result is only available when status is "completed" or "failed".
        """
        if request_id not in self.requests:
            return { "success": False, "error": "Request ID does not exist" }

        request = self.requests[request_id]
        status = request["status"]

        if status not in ["completed", "failed"]:
            return { "success": False, "error": "Result not available yet; request is still processing or not started" }

        return { "success": True, "data": request["result"] }

    def get_request_details(self, request_id: str) -> dict:
        """
        Retrieve full details of a search request by its request ID.

        Args:
            request_id (str): The unique identifier of the search request.

        Returns:
            dict: {
                "success": True,
                "data": SearchRequestInfo  # Full details of the request
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Request not found"
            }

        Constraints:
            - Only existing request IDs can be queried.
            - The request_id must be a non-empty string.
        """
        if not request_id:
            return { "success": False, "error": "Request ID cannot be empty" }

        request = self.requests.get(request_id)
        if request is None:
            return { "success": False, "error": "Request not found" }

        return { "success": True, "data": request }

    def list_all_request_ids(self) -> dict:
        """
        Return a list of all existing request IDs currently tracked by the system.

        Returns:
            dict: {
                "success": True,
                "data": List[str]  # List of all request_id strings (may be empty)
            }

        Constraints:
            - The list includes only request IDs that are currently in the system.
            - Each request_id is unique (enforced upon submission).

        Note:
            This operation always succeeds since no parameters are involved and the internal state is always consistent.
        """
        request_ids = list(self.requests.keys())
        return { "success": True, "data": request_ids }

    def check_request_exists(self, request_id: str) -> dict:
        """
        Verify whether a request with the given request_id exists in the system.

        Args:
            request_id (str): The unique identifier of the search request to check.

        Returns:
            dict: {
                "success": True,
                "data": bool  # True if request exists, False otherwise
            }
            This operation always succeeds; it does not raise errors for invalid or non-existent IDs.

        Constraints:
            - Each request_id must be unique (enforced at submission, not here).
            - Only existing request IDs can be queried — this function helps enforce that rule externally.
        """
        exists = request_id in self.requests
        return { "success": True, "data": exists }


    def submit_new_search_request(self, request_id: str, query_params: Any) -> dict:
        """
        Create and register a new search request with a unique request_id, query parameters,
        and initial status 'submitted'.

        Args:
            request_id (str): Unique identifier for the search request.
            query_params (Any): The parameters or content of the search query.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., duplicate request_id)
            }

        Constraints:
            - request_id must be unique.
            - Initial status is set to "submitted".
            - result field is initialized to None.
            - created_at and updated_at timestamps are set at submission time.
        """
        if not request_id:
            return { "success": False, "error": "Request ID cannot be empty" }

        if request_id in self.requests:
            return { "success": False, "error": "Request ID already exists" }

        current_time = time.time()

        new_request: SearchRequestInfo = {
            "request_id": request_id,
            "query_params": query_params,
            "status": "submitted",
            "result": None,
            "created_at": current_time,
            "updated_at": current_time
        }

        self.requests[request_id] = new_request

        return { "success": True, "message": "Search request submitted successfully" }

    def update_request_status(self, request_id: str, new_status: str) -> dict:
        """
        Transition the status of an existing request to a new valid state, respecting sequential constraints.

        Args:
            request_id (str): The unique identifier of the search request.
            new_status (str): The target status to transition to. Must be a valid next state:
                             - From "submitted" → "processing"
                             - From "processing" → "completed" or "failed"
                             - No transitions allowed from "completed" or "failed"

        Returns:
            dict: {
                "success": True,
                "message": str  # Description of the status update
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., invalid transition, request not found)
            }

        Constraints:
            - Only existing request IDs can be updated.
            - Status transitions must follow the defined sequence.
            - The result field is not modified by this method (use set_request_result separately).
        """
        valid_transitions = {
            "submitted": ["processing"],
            "processing": ["completed", "failed"],
            "completed": [],
            "failed": []
        }

        if request_id not in self.requests:
            return {"success": False, "error": "Request ID does not exist"}

        request = self.requests[request_id]
        current_status = request["status"]

        allowed_next = valid_transitions.get(current_status, [])
        if new_status not in allowed_next:
            return {
                "success": False,
                "error": f"Invalid status transition from '{current_status}' to '{new_status}'. "
                         f"Allowed transitions: {allowed_next}"
            }

        request["status"] = new_status
        request["updated_at"] = time.time()

        return {
            "success": True,
            "message": f"Status updated from '{current_status}' to '{new_status}' for request '{request_id}'"
        }

    def set_request_result(self, request_id: str, result: Any) -> dict:
        """
        Populate the result field of a request when its status is "completed" or "failed".

        Args:
            request_id (str): The unique identifier of the request.
            result (Any): The result data to set. Can be any type, such as a list, dict, or error message.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., request not found or invalid status)
            }

        Constraints:
            - Only existing requests can be updated.
            - Result can only be set if status is "completed" or "failed".
            - The updated_at timestamp is updated upon successful modification.
        """

        if request_id not in self.requests:
            return { "success": False, "error": "Request ID does not exist" }

        request = self.requests[request_id]
        current_status = request["status"]

        if current_status not in ["completed", "failed"]:
            return { "success": False, "error": f"Result can only be set when status is 'completed' or 'failed', got '{current_status}'" }

        # Update result and timestamp
        request["result"] = result
        request["updated_at"] = time.time()

        return { "success": True, "message": f"Result set for request {request_id}" }

    def retry_failed_request(self, request_id: str) -> dict:
        """
        Reset a failed search request to 'submitted' status for reprocessing.
        - If possible, the existing request_id is reused (recommended unless there's a conflict).
        - The status is changed to 'submitted', and the result field is cleared.
        - The 'updated_at' timestamp is set to the current time.

        Args:
            request_id (str): The ID of the failed search request to retry.

        Returns:
            dict: {
                "success": True,
                "message": "Request {request_id} reset for reprocessing."
            }
            or
            {
                "success": False,
                "error": "reason"
            }

        Constraints:
        - Only an existing request with status 'failed' can be retried.
        - Status transitions are sequential.
        - The result field is cleared for retried requests.
        - updated_at timestamp is updated.
        """
        if request_id not in self.requests:
            return { "success": False, "error": "Request ID does not exist." }

        req = self.requests[request_id]
        if req["status"] != "failed":
            return { "success": False, "error": "Only requests with status 'failed' can be retried." }

        req["status"] = "submitted"
        req["result"] = None
        req["updated_at"] = time.time()
        self.requests[request_id] = req  # Not strictly necessary, but for completeness

        return {
            "success": True,
            "message": f"Request {request_id} reset for reprocessing."
        }


    def cancel_request(self, request_id: str) -> dict:
        """
        Mark a request as "failed" with a cancellation reason, if it is not already completed or failed.

        Args:
            request_id (str): The unique identifier of the search request to cancel.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation of cancellation
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., not found, already completed/failed)
            }

        Constraints:
            - The request must exist.
            - Only requests with status "submitted" or "processing" can be cancelled.
            - Once a request is "completed" or "failed", it cannot be cancelled.
            - The result field is updated only when marking as "failed".
        """
        request = self.requests.get(request_id)
        if not request:
            return { "success": False, "error": f"Request '{request_id}' does not exist" }

        if request["status"] in ["completed", "failed"]:
            return {
                "success": False,
                "error": f"Request '{request_id}' cannot be cancelled because it is already {request['status']}"
            }

        # Update the request state
        request["status"] = "failed"
        request["result"] = "Cancelled by user"
        request["updated_at"] = time.time()

        return {
            "success": True,
            "message": f"Request '{request_id}' cancelled successfully."
        }

