        # Get the note
        note = self.notes[note_id]

        # If tag does not exist, create it
        if tag_name not in self.tags:
            self.tags[tag_name] = TagInfo(tag_name=tag_name)

        # If tag is already in the note, no need to add again
        if tag_name in note["tags"]:
            return { "success": True, "message": f"Tag '{tag_name}' is already attached to note '{note_id}'" }

        # Add tag to note
        note["tags"].append(tag_name)
        note["updated_at"] = time.time()  # Update timestamp

        return { "success": True, "message": f"Tag '{tag_name}' added to note '{note_id}'." }

