            product_name (str): The full or partial name of the product to search for.

        Returns:
            dict: {
                "success": True,
                "data": List[ProductInfo]  # List of products whose name contains the query (case-insensitive)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g., invalid input type)
            }

        Constraints:
            - Matching is case-insensitive.
            - Supports partial substring matches (e.g., "treadmill" matches "ProForm Treadmill").
            - If product_name is empty, returns all products.
        """
        if not isinstance(product_name, str):
            return { "success": False, "error": "Product name must be a string" }

        query = product_name.strip().lower()
        result = []

        for product in self.products.values():
            if query in product["name"].lower():
                result.append(product)

        return { "success": True, "data": result }

    def get_product_by_id(self, product_id: str) -> dict:
        """
        Retrieve product details using its unique product_id.

        Args:
            product_id (str): The unique identifier of the product.

        Returns:
            dict: {
                "success": True,
                "data": ProductInfo  # The product's information
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Product not found"
            }

        Constraints:
            - The product must exist in the catalog.
        """
        if not product_id:
            return { "success": False, "error": "Product ID is required" }

        product = self.products.get(product_id)
        if not product:
            return { "success": False, "error": "Product not found" }

        return { "success": True, "data": product }

    def search_products_by_category(self, category: str) -> dict:
        """
        List all products belonging to a specific category.

        Args:
            category (str): The category to search for (e.g., "fitness equipment").

        Returns:
            dict: {
                "success": True,
                "data": List[ProductInfo]  # List of products matching the given category (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., invalid input type
            }

        Constraints:
            - None directly enforced during query; relies on existing product data.
            - Matching is case-sensitive and based on exact category string.
        """
        if not isinstance(category, str):
            return { "success": False, "error": "Category must be a string." }

        result = [
            product_info for product_info in self.products.values()
            if product_info["category"] == category
        ]

        return { "success": True, "data": result }

    def list_all_products(self) -> dict:
        """
        Retrieve a list of all products in the catalog.

        Returns:
            dict: {
                "success": True,
                "data": List[ProductInfo]  # List of all products; may be empty
            }

        Constraints:
            - None. This operation always succeeds, even if no products exist.
        """
        return {
            "success": True,
            "data": list(self.products.values())
        }

    def get_reviews_by_product_id(self, product_id: str) -> dict:
        """
        Fetch all reviews associated with a given product_id.

        Args:
            product_id (str): The unique identifier of the product.

        Returns:
            dict: {
                "success": True,
                "data": List[ReviewInfo]  # List of reviews for the product (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Product not found"
            }

        Constraints:
            - The product_id must correspond to an existing product in the catalog.
            - Only reviews for valid products can be retrieved.
        """
        if product_id not in self.products:
            return { "success": False, "error": "Product not found" }

        result = [
            review for review in self.reviews.values()
            if review["product_id"] == product_id
        ]

        return { "success": True, "data": result }

    def get_reviews_by_product_name(self, product_name: str) -> dict:
        """
        Retrieve all reviews for products matching the given product name.

        The operation first resolves product(s) by name, then retrieves all reviews
        associated with the corresponding product_id(s).

        Args:
            product_name (str): The name of the product to retrieve reviews for.

        Returns:
            dict: {
                "success": True,
                "data": List[ReviewInfo]  # List of reviews for the product(s) with the given name
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., "Product not found"
            }

        Constraints:
            - The product name must match at least one product in the catalog.
            - Reviews are returned only for products that exist.
        """
        # Find all products matching the given name
        matching_product_ids = [
            product["product_id"] for product in self.products.values()
            if product["name"] == product_name
        ]

        if not matching_product_ids:
            return {"success": False, "error": "Product not found"}

        # Retrieve all reviews for the matching product(s)
        reviews_list = [
            review for review in self.reviews.values()
            if review["product_id"] in matching_product_ids
        ]

        return {"success": True, "data": reviews_list}

    def get_review_by_id(self, review_id: str) -> dict:
        """
        Retrieve a specific review by its unique review_id.

        Args:
            review_id (str): The unique identifier of the review to retrieve.

        Returns:
            dict: {
                "success": True,
                "data": ReviewInfo  # The review data if found
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Review not found"
            }

        Constraints:
            - The review_id must correspond to an existing review.
            - No permissions are required to read a review (only to modify/delete).
        """
        if not review_id:
            return {"success": False, "error": "Review ID cannot be empty"}

        review = self.reviews.get(review_id)
        if review is None:
            return {"success": False, "error": "Review not found"}

        return {"success": True, "data": review}

    def get_user_by_id(self, user_id: str) -> dict:
        """
        Retrieve user information including username, account status, and purchase history by user_id.

        Args:
            user_id (str): The unique identifier of the user.

        Returns:
            dict: {
                "success": True,
                "data": UserInfo  # Full user information
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. "User not found"
            }

        Constraints:
            - None beyond existence check; no permissions enforced here.
        """
        user = self.users.get(user_id)
        if not user:
            return {"success": False, "error": "User not found"}

        return {"success": True, "data": user}

    def check_user_purchase_history(self, user_id: str, product_id: str) -> dict:
        """
        Verify whether a user has purchased a specific product by checking their purchase history.

        Args:
            user_id (str): The unique identifier of the user.
            product_id (str): The unique identifier of the product.

        Returns:
            dict: {
                "success": True,
                "data": bool  # True if user has purchased the product, False otherwise
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g. "User not found", "Product not found"
            }

        Constraints:
            - Both user and product must exist in the system.
            - Only users with a purchase record for the product can pass review eligibility checks.
        """
        if user_id not in self.users:
            return {"success": False, "error": "User not found"}

        if product_id not in self.products:
            return {"success": False, "error": "Product not found"}

        user = self.users[user_id]
        has_purchased = product_id in user["purchase_history"]

        return {"success": True, "data": has_purchased}

    def get_average_rating_for_product(self, product_id: str = None, product_name: str = None) -> dict:
        """
        Calculate and return the average star rating for a product based on all its reviews.

        Args:
            product_id (str, optional): The unique ID of the product.
            product_name (str, optional): The name of the product (exact match).

        Returns:
            dict: {
                "success": True,
                "data": {
                    "average_rating": float  # Rounded to 2 decimal places
                }
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., product not found, ambiguous name)
            }

        Constraints:
            - One of product_id or product_name must be provided.
            - If product_name is used and multiple products have the same name, it is ambiguous → error.
            - Average is computed over all reviews linked to the product.
            - If product has no reviews, average rating is 0.0.
        """
        if not product_id and not product_name:
            return { "success": False, "error": "Either product_id or product_name must be provided." }

        target_product_id = None

        if product_id:
            if product_id not in self.products:
                return { "success": False, "error": "Product not found." }
            target_product_id = product_id
        else:
            # Look up by product_name
            matching_products = [p for p in self.products.values() if p["name"] == product_name]
            if len(matching_products) == 0:
                return { "success": False, "error": f"No product found with name '{product_name}'." }
            if len(matching_products) > 1:
                return { "success": False, "error": f"Multiple products found with name '{product_name}'. Please use product_id to disambiguate." }
            target_product_id = matching_products[0]["product_id"]

        # Get all reviews for the target product
        product_reviews = [
            review for review in self.reviews.values()
            if review["product_id"] == target_product_id
        ]

        if len(product_reviews) == 0:
            average_rating = 0.0
        else:
            total_rating = sum(review["rating"] for review in product_reviews)
            average_rating = round(total_rating / len(product_reviews), 2)

        return {
            "success": True,
            "data": { "average_rating": average_rating }
        }

    def get_most_helpful_reviews(self) -> dict:
        """
        Retrieve all reviews sorted by helpful_votes in descending order to highlight the most community-valued feedback.

        Returns:
            dict: {
                "success": True,
                "data": List[ReviewInfo]  # Reviews sorted by helpful_votes (highest first)
            }
            or
            {
                "success": False,
                "error": str  # Only in unexpected cases (e.g., invalid data)
            }

        Constraints:
            - Reviews are sorted solely by helpful_votes in descending order.
            - All reviews in the system are included, regardless of product or user.
            - No permissions or purchase checks are needed for viewing reviews.
        """
        try:
            reviews_list = list(self.reviews.values())
            # Sort by helpful_votes descending
            sorted_reviews = sorted(reviews_list, key=lambda r: r["helpful_votes"], reverse=True)
            return { "success": True, "data": sorted_reviews }
        except Exception as e:
            # Though unlikely, catch any unexpected error (e.g. corrupted data)
            return { "success": False, "error": f"Failed to retrieve reviews: {str(e)}" }

    def submit_review(self, user_id: str, product_id: str, rating: int, comment: str) -> dict:
        """
        Allow a user to post a new review for a product they've purchased.

        Args:
            user_id (str): The ID of the user submitting the review.
            product_id (str): The ID of the product to review.
            rating (int): Star rating from 1 to 5.
            comment (str): The textual feedback provided by the user.

        Returns:
            dict: {
                "success": True,
                "message": "Review submitted successfully"
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Product must exist in the catalog.
            - User must have purchased the product (product_id in user's purchase_history).
            - Rating must be an integer between 1 and 5, inclusive.
        """
        # Check if product exists
        if product_id not in self.products:
            return { "success": False, "error": "Product does not exist" }

        # Check if user exists
        if user_id not in self.users:
            return { "success": False, "error": "User does not exist" }

        user = self.users[user_id]
        # Check if user has purchased the product
        if product_id not in user["purchase_history"]:
            return { "success": False, "error": "User has not purchased this product" }

        # Validate rating
        if not isinstance(rating, int) or rating < 1 or rating > 5:
            return { "success": False, "error": "Rating must be an integer between 1 and 5" }

        # Generate a unique review_id
        review_id = f"rev_{len(self.reviews) + 1}"

        # Create new review
        new_review: ReviewInfo = {
            "review_id": review_id,
            "product_id": product_id,
            "user_id": user_id,
            "rating": rating,
            "comment": comment,
            "timestamp": time(),
            "helpful_votes": 0
        }

        # Add to reviews
        self.reviews[review_id] = new_review

        return { "success": True, "message": "Review submitted successfully" }

    def edit_review(
        self,
        review_id: str,
        user_id: str,
        new_comment: str = None,
        new_rating: int = None
    ) -> dict:
        """
        Allow the owner of a review to edit its comment or rating.

        Args:
            review_id (str): The ID of the review to edit.
            user_id (str): The ID of the user attempting the edit (ownership check).
            new_comment (str, optional): New comment text. If not provided, comment remains unchanged.
            new_rating (int, optional): New rating (1-5 stars). If not provided, rating remains unchanged.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Only the review owner can edit the review.
            - Rating must be between 1 and 5 if provided.
            - Review must exist.
            - At least one of new_comment or new_rating must be provided.
        """
        if review_id not in self.reviews:
            return { "success": False, "error": "Review not found" }

        review = self.reviews[review_id]

        if review["user_id"] != user_id:
            return { "success": False, "error": "User not authorized to edit this review" }

        if new_rating is not None:
            if not (1 <= new_rating <= 5):
                return { "success": False, "error": "Rating must be between 1 and 5" }
            review["rating"] = new_rating

        if new_comment is not None:
            review["comment"] = new_comment

        if new_comment is None and new_rating is None:
            return { "success": False, "error": "No changes provided" }

        # Note: In real systems, update timestamp; not required here

        return { "success": True, "message": "Review updated successfully" }

    def delete_review(self, review_id: str, requester_user_id: str) -> dict:
        """
        Delete a review from the system if the requester is the owner of the review.

        Args:
            review_id (str): The ID of the review to delete.
            requester_user_id (str): The user ID of the person attempting to delete the review.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
            }
            or
            {
                "success": bool,
                "error": str  # Present on failure
            }

        Constraints:
            - Only the owner of the review can delete it.
            - The review must exist.
        """
        if review_id not in self.reviews:
            return { "success": False, "error": "Review not found" }

        review = self.reviews[review_id]

        if review["user_id"] != requester_user_id:
            return { "success": False, "error": "Permission denied: Only the review owner can delete this review" }

        # Delete the review
        del self.reviews[review_id]

        return { "success": True, "message": "Review deleted successfully" }

    def increment_helpful_vote(self, review_id: str) -> dict:
        """
        Increment the helpful vote count for a given review by 1.

        Args:
            review_id (str): The unique identifier of the review to upvote.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation of vote increment
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., review not found
            }

        Constraints:
            - The review must exist in the system.
            - No user authentication required; any user can upvote.
            - The helpful_votes count is incremented unconditionally if review exists.
        """
        if review_id not in self.reviews:
            return {"success": False, "error": "Review not found"}

        # Increment helpful_votes
        self.reviews[review_id]["helpful_votes"] += 1

        return {
            "success": True,
            "message": f"Helpful vote incremented for review '{review_id}'"
        }

    def bulk_delete_reviews_by_product(self, product_id: str, admin_user_id: str) -> dict:
        """
        Admin-only operation to remove all reviews associated with a specific product.

        Args:
            product_id (str): The ID of the product whose reviews should be deleted.
            admin_user_id (str): The ID of the admin user performing the operation.

        Returns:
            dict: {
                "success": True,
                "message": str  # Describes how many reviews were deleted
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure: invalid product, unauthorized, etc.
            }

        Constraints:
            - The product must exist in the catalog.
            - The admin_user_id must refer to an existing active user.
            - Only admin users are allowed to perform this action (best effort with available schema).
        """
        # Check if the product exists
        if product_id not in self.products:
            return { "success": False, "error": "Product does not exist" }

        # Check if admin user exists and is active
        admin_user = self.users.get(admin_user_id)
        if not admin_user:
            return { "success": False, "error": "Admin user does not exist" }
        if admin_user["account_status"] != "active":
            return { "success": False, "error": "Admin user is not active" }

        # Find all reviews associated with the product
        reviews_to_delete = [
            rid for rid, review in self.reviews.items()
            if review["product_id"] == product_id
        ]

        # Delete the reviews
        for review_id in reviews_to_delete:
            del self.reviews[review_id]

        count = len(reviews_to_delete)
        return {
            "success": True,
            "message": f"Deleted {count} reviews associated with product ID '{product_id}'."
        }

    def update_product_info(self, product_id: str, updates: dict) -> dict:
        """
        Admin operation to update details of an existing product.

        Args:
            product_id (str): The unique ID of the product to update.
            updates (dict): A dictionary containing any of the following keys:
                - name (str)
                - brand (str)
                - category (str)
                - description (str)
                Any subset of these fields can be updated.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The product must exist in the system.
            - Only existing fields are updated; unknown fields are ignored.
        """
        if product_id not in self.products:
            return { "success": False, "error": "Product not found" }

        product = self.products[product_id]

        # Valid fields that can be updated
        allowed_fields = ['name', 'brand', 'category', 'description']

        for field, value in updates.items():
            if field in allowed_fields:
                product[field] = value
        # Note: Timestamps or audit fields are not modeled, so no update to those.

        return { "success": True, "message": "Product updated successfully" }

    def add_product(self, product_id: str, name: str, brand: str, category: str, description: str) -> dict:
        """
        Add a new product to the catalog. The product must have a unique ID and complete information.

        Args:
            product_id (str): Unique identifier for the product.
            name (str): Name of the product.
            brand (str): Brand of the product.
            category (str): Category the product belongs to.
            description (str): Description of the product.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - product_id must be unique.
            - All fields must be provided and non-empty.
        """
        if not product_id or not name or not brand or not category:
            return { "success": False, "error": "Missing required fields: product_id, name, brand, or category" }

        if product_id in self.products:
            return { "success": False, "error": "Product with this product_id already exists" }

        self.products[product_id] = {
            "product_id": product_id,
            "name": name,
            "brand": brand,
            "category": category,
            "description": description
        }

        return { "success": True, "message": "Product added successfully" }

