        """
        Calculate and return the average star rating for a product based on all its reviews.

        Args:
            product_id (str, optional): The unique ID of the product.
            product_name (str, optional): The name of the product (exact match).

        Returns:
            dict: {
                "success": True,
                "data": {
                    "average_rating": float  # Rounded to 2 decimal places
                }
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., product not found, ambiguous name)
            }

        Constraints:
            - One of product_id or product_name must be provided.
            - If product_name is used and multiple products have the same name, it is ambiguous → error.
            - Average is computed over all reviews linked to the product.
            - If product has no reviews, average rating is 0.0.
        """
        if not product_id and not product_name:
            return { "success": False, "error": "Either product_id or product_name must be provided." }

        target_product_id = None

        if product_id:
            if product_id not in self.products:
                return { "success": False, "error": "Product not found." }
            target_product_id = product_id
        else:
            # Look up by product_name
            matching_products = [p for p in self.products.values() if p["name"] == product_name]
            if len(matching_products) == 0:
                return { "success": False, "error": f"No product found with name '{product_name}'." }
            if len(matching_products) > 1:
                return { "success": False, "error": f"Multiple products found with name '{product_name}'. Please use product_id to disambiguate." }
            target_product_id = matching_products[0]["product_id"]

        # Get all reviews for the target product
        product_reviews = [
            review for review in self.reviews.values()
            if review["product_id"] == target_product_id
        ]

        if len(product_reviews) == 0:
            average_rating = 0.0
        else:
            total_rating = sum(review["rating"] for review in product_reviews)
            average_rating = round(total_rating / len(product_reviews), 2)

        return {
            "success": True,
            "data": { "average_rating": average_rating }
        }"}, "get_most_helpful_reviews": {"signature": {"parameters": [], "return": "dict"}, "doc": "Retrieve all reviews sorted by helpful_votes in descending order to highlight the most community-valued feedback.

