        """
        Allow a user to post a new review for a product they've purchased.

        Args:
            user_id (str): The ID of the user submitting the review.
            product_id (str): The ID of the product to review.
            rating (int): Star rating from 1 to 5.
            comment (str): The textual feedback provided by the user.

        Returns:
            dict: {
                "success": True,
                "message": "Review submitted successfully"
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Product must exist in the catalog.
            - User must have purchased the product (product_id in user's purchase_history).
            - Rating must be an integer between 1 and 5, inclusive.
        """
        # Check if product exists
        if product_id not in self.products:
            return { "success": False, "error": "Product does not exist" }

        # Check if user exists
        if user_id not in self.users:
            return { "success": False, "error": "User does not exist" }

        user = self.users[user_id]
        # Check if user has purchased the product
        if product_id not in user["purchase_history"]:
            return { "success": False, "error": "User has not purchased this product" }

        # Validate rating
        if not isinstance(rating, int) or rating < 1 or rating > 5:
            return { "success": False, "error": "Rating must be an integer between 1 and 5" }

        # Generate a unique review_id
        review_id = f"rev_{len(self.reviews) + 1}"

        # Create new review
        new_review: ReviewInfo = {
            "review_id": review_id,
            "product_id": product_id,
            "user_id": user_id,
            "rating": rating,
            "comment": comment,
            "timestamp": time(),
            "helpful_votes": 0
        }

        # Add to reviews
        self.reviews[review_id] = new_review

        return { "success": True, "message": "Review submitted successfully" }"}, "edit_review": {"signature": {"parameters": [{"name": "review_id", "type": "str", "default": null, "kind": "positional-or-keyword"}, {"name": "user_id", "type": "str", "default": null, "kind": "positional-or-keyword"}, {"name": "new_comment", "type": "str", "default": "None", "kind": "positional-or-keyword"}, {"name": "new_rating", "type": "int", "default": "None", "kind": "positional-or-keyword"}], "return": "dict"}, "doc": "Allow the owner of a review to edit its comment or rating.

