from typing import Dict, List, TypedDict
import time
from typing import List



class SensorReadingInfo(TypedDict):
    device_id: str
    timestamp: float  # Unix timestamp
    sensor_type: str
    val: float

class DeviceInfo(TypedDict):
    device_id: str
    location: str
    device_type: str
    registration_sta: str  # Note: likely typo for 'registration_status'

class SensorTypeInfo(TypedDict):
    sensor_type: str  # Note: typo in original, corrected key
    unit_of_measurement: str
    description: str

class IoTSensorDataPlatform:
    def __init__(self):
        """
        IoT sensor data platform for managing sensor readings, devices, and sensor metadata.
        """

        # Registered devices: {device_id: DeviceInfo}
        self.devices: Dict[str, DeviceInfo] = {}

        # Supported sensor types: {sensor_type: SensorTypeInfo}
        self.sensor_types: Dict[str, SensorTypeInfo] = {}

        # Time-series sensor readings (append-only list)
        self.readings: List[SensorReadingInfo] = []

        # Constraints reminder:
        # - Each SensorReading must have a valid device_id (must exist in self.devices)
        # - SensorReading timestamp must be within valid range (e.g., not in distant future)
        # - SensorReading sensor_type must be registered in self.sensor_types
        # - Querying supported by device_id, time range, and sensor_type combinations

    def get_sensor_readings_by_device(self, device_id: str) -> dict:
        """
        Retrieve all sensor readings associated with a specific device_id.

        Args:
            device_id (str): The unique identifier of the device.

        Returns:
            dict: {
                "success": True,
                "data": List[SensorReadingInfo]  # List of readings for the device (can be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., "Device not registered"
            }

        Constraints:
            - The device_id must correspond to a registered device in the system.
        """
        if device_id not in self.devices:
            return { "success": False, "error": "Device not registered" }

        filtered_readings = [
            reading for reading in self.readings
            if reading["device_id"] == device_id
        ]

        return { "success": True, "data": filtered_readings }

    def get_sensor_readings_by_time_range(self, start_time: float, end_time: float) -> dict:
        """
        Retrieve all sensor readings within the specified time range (inclusive).

        Args:
            start_time (float): Unix timestamp for the start of the time range (inclusive).
            end_time (float): Unix timestamp for the end of the time range (inclusive).

        Returns:
            dict: {
                "success": True,
                "data": List[SensorReadingInfo]  # List of readings within the time range (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., "Invalid time range: start_time > end_time"
            }

        Constraints:
            - Both start_time and end_time must be valid floats.
            - start_time must be less than or equal to end_time.
            - Readings are filtered by timestamp inclusively.
        """
        # Validate time range
        if not isinstance(start_time, (int, float)) or not isinstance(end_time, (int, float)):
            return { "success": False, "error": "start_time and end_time must be numeric" }

        if start_time > end_time:
            return { "success": False, "error": "start_time must be less than or equal to end_time" }

        # Filter readings by timestamp
        result = [
            reading for reading in self.readings
            if start_time <= reading["timestamp"] <= end_time
        ]

        return { "success": True, "data": result }

    def get_sensor_readings_by_sensor_type(self, sensor_type: str) -> dict:
        """
        Retrieve all sensor readings for a specific sensor_type.

        Args:
            sensor_type (str): The type of sensor (e.g., 'temperature', 'humidity') to filter by.

        Returns:
            dict: {
                "success": True,
                "data": List[SensorReadingInfo]  # List of readings matching the sensor_type (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g., sensor type not registered)
            }

        Constraints:
            - The sensor_type must be registered in the system.
            - Only readings with valid, registered sensor types are stored; query respects this.
        """
        if not sensor_type:
            return { "success": False, "error": "Sensor type must be a non-empty string" }

        if sensor_type not in self.sensor_types:
            return { "success": False, "error": f"Sensor type '{sensor_type}' is not registered" }

        matched_readings = [
            reading for reading in self.readings
            if reading["sensor_type"] == sensor_type
        ]

        return { "success": True, "data": matched_readings }

    def get_sensor_readings_filtered(
        self,
        device_id: str = None,
        sensor_types: List[str] = None,
        start_time: float = None,
        end_time: float = None
    ) -> dict:
        """
        Retrieve sensor readings filtered by device_id, sensor type(s), and time range.
        All parameters are optional; if none are provided, all readings are returned.

        Args:
            device_id (str, optional): Filter by device ID.
            sensor_types (List[str], optional): Filter by one or more sensor types.
            start_time (float, optional): Lower bound Unix timestamp (inclusive).
            end_time (float, optional): Upper bound Unix timestamp (inclusive).

        Returns:
            dict: {
                "success": True,
                "data": List[SensorReadingInfo]  # May be empty if no matches
            }
            or
            {
                "success": False,
                "error": str  # Description of error (e.g. invalid types)
            }

        Constraints:
            - Only readings matching all provided filters are returned.
            - All sensor readings are assumed to have valid device_id and sensor_type
              (enforced at ingestion time).
        """
        # Validate parameter types
        if device_id is not None and not isinstance(device_id, str):
            return { "success": False, "error": "device_id must be a string if provided" }

        if sensor_types is not None:
            if not isinstance(sensor_types, list):
                return { "success": False, "error": "sensor_types must be a list of strings if provided" }
            if not all(isinstance(st, str) for st in sensor_types):
                return { "success": False, "error": "all elements in sensor_types must be strings" }

        if start_time is not None and not isinstance(start_time, (int, float)):
            return { "success": False, "error": "start_time must be a number (Unix timestamp)" }

        if end_time is not None and not isinstance(end_time, (int, float)):
            return { "success": False, "error": "end_time must be a number (Unix timestamp)" }

        # Start with all readings
        filtered_readings = self.readings

        # Apply device_id filter
        if device_id is not None:
            filtered_readings = [r for r in filtered_readings if r["device_id"] == device_id]

        # Apply sensor_types filter
        if sensor_types is not None:
            filtered_readings = [r for r in filtered_readings if r["sensor_type"] in sensor_types]

        # Apply time range filters
        if start_time is not None:
            filtered_readings = [r for r in filtered_readings if r["timestamp"] >= start_time]

        if end_time is not None:
            filtered_readings = [r for r in filtered_readings if r["timestamp"] <= end_time]

        return { "success": True, "data": filtered_readings }

    def get_device_info(self, device_id: str) -> dict:
        """
        Retrieve metadata for a given device_id.

        Args:
            device_id (str): The unique identifier of the device.

        Returns:
            dict: {
                "success": True,
                "data": DeviceInfo  # Contains location, device_type, registration_sta
            }
            or
            {
                "success": False,
                "error": str  # e.g. "Device not registered"
            }

        Constraints:
            - The device_id must correspond to a registered device in the system.
        """
        device = self.devices.get(device_id)
        if not device:
            return {"success": False, "error": "Device not registered"}
        return {"success": True, "data": device}

    def list_registered_devices(self) -> dict:
        """
        Return a list of all registered devices in the system.

        Returns:
            dict: {
                "success": True,
                "data": List[DeviceInfo]  # List of all registered devices; empty if none
            }

        Constraints:
            - None; this is a read-only operation with no parameters.
        """
        return {
            "success": True,
            "data": list(self.devices.values())
        }

    def list_supported_sensor_types(self) -> dict:
        """
        Return a list of all sensor types registered in the system.

        Returns:
            dict: {
                "success": True,
                "data": List[SensorTypeInfo]  # List of all registered sensor types with their unit and description
            }

        Note:
            - Returns an empty list if no sensor types are registered.
            - No error cases expected as this is a read operation on an internal dictionary.
        """
        return {
            "success": True,
            "data": list(self.sensor_types.values())
        }

    def get_sensor_type_info(self, sensor_type: str) -> dict:
        """
        Retrieve metadata for a given sensor type, including its unit of measurement and description.

        Args:
            sensor_type (str): The name of the sensor type (e.g., 'temperature', 'humidity').

        Returns:
            dict: {
                "success": True,
                "data": SensorTypeInfo  # Contains 'sensor_type', 'unit_of_measurement', 'description'
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., sensor type not registered
            }

        Constraints:
            - The sensor_type must be registered in the system.
            - Exact string match is used to lookup the sensor type.
        """
        if sensor_type not in self.sensor_types:
            return { "success": False, "error": "Sensor type not registered" }

        return { "success": True, "data": self.sensor_types[sensor_type] }

    def check_device_registration_status(self, device_id: str) -> dict:
        """
        Check whether a device with the given device_id is registered in the system.

        Args:
            device_id (str): The unique identifier of the device to check.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "is_registered": bool  # True if device is registered, False otherwise
                }
            }
            This method always succeeds; if the device is not found, it returns False.

        Constraints:
            - None (query operation, no state change).
            - Device registration is determined by presence in the system's device registry.
        """
        is_registered = device_id in self.devices
        return {
            "success": True,
            "data": {
                "is_registered": is_registered
            }
        }

    def check_sensor_type_registered(self, sensor_type: str) -> dict:
        """
        Verify whether a given sensor_type is defined (registered) in the system.

        Args:
            sensor_type (str): The sensor type to check (e.g., 'temperature', 'humidity').

        Returns:
            dict: {
                "success": True,
                "data": {
                    "registered": bool  # True if sensor_type is registered, False otherwise
                }
            }

        Constraints:
            - The sensor_type must match exactly (case-sensitive) with a registered sensor type.
        """
        registered = sensor_type in self.sensor_types
        return {
            "success": True,
            "data": {
                "registered": registered
            }
        }


    def ingest_sensor_reading(self, device_id: str, timestamp: float, sensor_type: str, val: float) -> dict:
        """
        Add a new sensor reading to the system after validating device_id, sensor_type, and timestamp.

        Args:
            device_id (str): Unique identifier of the sensor device.
            timestamp (float): Unix timestamp of when the reading was taken.
            sensor_type (str): Type of sensor (e.g., 'temperature', 'humidity').
            val (float): The measured value.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Only if success is True
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - device_id must correspond to a registered device.
            - sensor_type must be a predefined/registered type.
            - timestamp must be within a valid range (e.g., not in the far future).
        """
        # Validate device_id
        if device_id not in self.devices:
            return { "success": False, "error": f"Device ID '{device_id}' is not registered" }

        # Validate sensor_type
        if sensor_type not in self.sensor_types:
            return { "success": False, "error": f"Sensor type '{sensor_type}' is not registered" }

        # Validate timestamp (not more than 1 hour in the future)
        current_time = time.time()
        if timestamp > current_time + 3600:  # 1 hour tolerance
            return { "success": False, "error": "Timestamp is too far in the future" }

        # Create and append the reading
        reading: SensorReadingInfo = {
            "device_id": device_id,
            "timestamp": timestamp,
            "sensor_type": sensor_type,
            "val": val
        }
        self.readings.append(reading)

        return { "success": True, "message": "Sensor reading ingested successfully" }

    def register_device(self, device_id: str, location: str, device_type: str, registration_sta: str) -> dict:
        """
        Register a new physical device in the system.

        Args:
            device_id (str): Unique identifier for the device.
            location (str): Physical location of the device (e.g., "Room 205", "Outdoor West").
            device_type (str): Type or category of the device (e.g., "temperature_sensor").
            registration_sta (str): Registration status (e.g., "active", "pending").

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Description of failure
            }

        Constraints:
            - device_id must be unique (not already registered).
            - All input fields must be strings and non-empty.
        """
        if not all(isinstance(arg, str) and arg.strip() for arg in [device_id, location, device_type, registration_sta]):
            return { "success": False, "error": "All arguments must be non-empty strings" }

        if device_id in self.devices:
            return { "success": False, "error": f"Device with ID '{device_id}' is already registered" }

        self.devices[device_id] = {
            "device_id": device_id,
            "location": location,
            "device_type": device_type,
            "registration_sta": registration_sta
        }

        return { "success": True, "message": "Device registered successfully" }

    def register_sensor_type(self, sensor_type: str, unit_of_measurement: str, description: str) -> dict:
        """
        Add a new sensor type to the system with its unit and description.

        Args:
            sensor_type (str): Unique identifier for the sensor type (e.g., 'temperature').
            unit_of_measurement (str): Unit in which the sensor values are measured (e.g., '°C').
            description (str): Human-readable description of the sensor type.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - The sensor_type must not already be registered.
            - All input fields must be non-empty strings.
        """
        if not sensor_type or not isinstance(sensor_type, str):
            return {"success": False, "error": "Sensor type must be a non-empty string."}
        if not unit_of_measurement or not isinstance(unit_of_measurement, str):
            return {"success": False, "error": "Unit of measurement must be a non-empty string."}
        if not description or not isinstance(description, str):
            return {"success": False, "error": "Description must be a non-empty string."}

        if sensor_type in self.sensor_types:
            return {"success": False, "error": f"Sensor type '{sensor_type}' is already registered."}

        self.sensor_types[sensor_type] = {
            "sensor_type": sensor_type,
            "unit_of_measurement": unit_of_measurement,
            "description": description
        }

        return {
            "success": True,
            "message": f"Sensor type '{sensor_type}' registered successfully."
        }

    def update_device_location(self, device_id: str, new_location: str) -> dict:
        """
        Update the physical location of a registered device.

        Args:
            device_id (str): The unique identifier of the device.
            new_location (str): The new physical location to assign to the device.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., device not found
            }

        Constraints:
            - The device_id must correspond to a registered device in the system.
        """
        if device_id not in self.devices:
            return { "success": False, "error": f"Device {device_id} is not registered" }

        self.devices[device_id]["location"] = new_location
        return { "success": True, "message": f"Location updated for device {device_id}" }

    def deregister_device(self, device_id: str) -> dict:
        """
        Mark a device as unregistered or decommissioned by updating its registration status.

        Args:
            device_id (str): The unique identifier of the device to deregister.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. device not found
            }

        Constraints:
            - The device must exist in the system (registered) to be deregistered.
            - Only the registration status is updated; the device entry remains in the system.
        """
        if device_id not in self.devices:
            return { "success": False, "error": f"Device '{device_id}' not found. Cannot deregister." }

        self.devices[device_id]["registration_sta"] = "unregistered"

        return { "success": True, "message": f"Device '{device_id}' has been deregistered." }

    def remove_sensor_type(self, sensor_type: str) -> dict:
        """
        Remove a sensor type from the system if no sensor readings depend on it.

        Args:
            sensor_type (str): The name of the sensor type to remove.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation of removal
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., not found, still in use)
            }

        Constraints:
            - The sensor type must exist in the system.
            - The sensor type can only be removed if no SensorReading uses it.
        """
        if sensor_type not in self.sensor_types:
            return { "success": False, "error": f"Sensor type '{sensor_type}' is not registered." }

        # Check if any reading uses this sensor_type
        for reading in self.readings:
            if reading["sensor_type"] == sensor_type:
                return { "success": False, "error": f"Cannot remove sensor type '{sensor_type}': still used by existing sensor readings." }

        # Safe to remove
        del self.sensor_types[sensor_type]
        return { "success": True, "message": f"Sensor type '{sensor_type}' removed successfully." }


    def batch_ingest_readings(self, readings_list: List[SensorReadingInfo]) -> dict:
        """
        Ingest multiple sensor readings at once, validating each against system constraints.

        Args:
            readings_list (List[SensorReadingInfo]): A list of sensor readings to ingest.
                Each reading must include device_id, timestamp, sensor_type, and val.

        Returns:
            dict: {
                "success": True,
                "message": str  # Describes how many readings were ingested successfully
            }
            Errors in individual readings do not cause overall failure; only valid readings are ingested.

        Validation Constraints:
            - device_id must correspond to a registered device in self.devices.
            - sensor_type must be registered in self.sensor_types.
            - timestamp must not be more than 3600 seconds ahead of the current system time.
        """
        if not isinstance(readings_list, list):
            return {
                "success": False,
                "error": "Input must be a list of sensor readings"
            }

        current_time = time.time()
        future_limit = current_time + 3600  # Allow up to 1 hour in the future
        ingested_count = 0

        for reading in readings_list:
            # Validate required fields
            device_id = reading.get("device_id")
            timestamp = reading.get("timestamp")
            sensor_type = reading.get("sensor_type")
            val = reading.get("val")

            # Field presence checks
            if not all(isinstance(x, (str, float, int)) for x in [device_id, sensor_type, val]):
                continue  # Skip invalid reading
            if not isinstance(timestamp, (int, float)):
                continue

            # Constraint 1: device_id must be registered
            if device_id not in self.devices:
                continue

            # Constraint 2: sensor_type must be registered
            if sensor_type not in self.sensor_types:
                continue

            # Constraint 3: timestamp must be within valid range (not too far in future)
            if timestamp > future_limit:
                continue

            # If all checks pass, append the reading
            self.readings.append({
                "device_id": device_id,
                "timestamp": timestamp,
                "sensor_type": sensor_type,
                "val": float(val)
            })
            ingested_count += 1

        return {
            "success": True,
            "message": f"{ingested_count} out of {len(readings_list)} readings ingested successfully."
        }

    def clear_expired_readings(self, current_time: float, retention_period: float) -> dict:
        """
        Remove sensor readings older than the specified retention period from the current time.

        Args:
            current_time (float): The current Unix timestamp (in seconds) used as reference.
            retention_period (float): The duration (in seconds) for which readings are retained.
                                      Must be non-negative.

        Returns:
            dict: {
                "success": True,
                "message": str  # Describes how many readings were cleared
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g. invalid parameters
            }

        Constraints:
            - Only readings with timestamp < (current_time - retention_period) are removed.
            - Sensor readings must have valid timestamps (assumed valid upon ingestion).
            - Does not affect device or sensor type registration.
        """
        # Validate inputs
        if not isinstance(current_time, (int, float)):
            return { "success": False, "error": "current_time must be a number (Unix timestamp)" }
        if not isinstance(retention_period, (int, float)):
            return { "success": False, "error": "retention_period must be a number (in seconds)" }
        if retention_period < 0:
            return { "success": False, "error": "retention_period must be non-negative" }
        if current_time < 0:
            return { "success": False, "error": "current_time must be a non-negative Unix timestamp" }

        cutoff = current_time - retention_period

        # Count readings before filtering
        initial_count = len(self.readings)

        # Keep only readings that are not expired (i.e., timestamp >= cutoff)
        self.readings = [reading for reading in self.readings if reading["timestamp"] >= cutoff]

        # Calculate how many were removed
        removed_count = initial_count - len(self.readings)

        return {
            "success": True,
            "message": f"Cleared {removed_count} expired sensor readings."
        }

