from typing import Dict, TypedDict
from datetime import datetime



class EmployeeInfo(TypedDict):
    employee_id: str
    first_name: str
    last_name: str
    date_of_birth: str  # format: YYYY-MM-DD
    gender: str
    hire_date: str  # format: YYYY-MM-DD
    job_title: str
    department: str
    manager_id: str
    employment_status: str
    salary: float
    work_email: str
    phone_number: str
    address: str

class DepartmentInfo(TypedDict):
    department_id: str
    department_name: str
    manager_id: str
    location: str

class JobPositionInfo(TypedDict):
    job_title: str
    department_id: str
    salary_range_min: float
    salary_range_max: float
    required_qualification: str

class EmploymentStatusInfo(TypedDict):
    status_type: str
    description: str
    is_active: bool

class HRIS:
    def __init__(self):
        """
        Human Resources Information System (HRIS) to manage employee data and employment lifecycle.
        """

        # Employees: {employee_id: EmployeeInfo}
        self.employees: Dict[str, EmployeeInfo] = {}

        # Departments: {department_id: DepartmentInfo}
        self.departments: Dict[str, DepartmentInfo] = {}

        # Job Positions: {job_title: JobPositionInfo}
        self.job_positions: Dict[str, JobPositionInfo] = {}

        # Employment Status Types: {status_type: EmploymentStatusInfo}
        self.employment_statuses: Dict[str, EmploymentStatusInfo] = {}

        # Constraints:
        # - employee_id must be unique (enforced by dict key in self.employees)
        # - employment_status must be one of the predefined valid status types
        # - hire_date cannot be in the future
        # - salary must fall within the defined salary range for the assigned job_title
        # - Every employee must belong to a valid department
        # - Only active employees (is_active=True in employment status) are eligible for promotions, bonuses, etc.

    def get_employee_by_id(self, employee_id: str) -> dict:
        """
        Retrieve full details of an employee using their unique employee_id.

        Args:
            employee_id (str): The unique identifier of the employee.

        Returns:
            dict: {
                "success": True,
                "data": EmployeeInfo  # Complete employee record
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Employee not found"
            }

        Constraints:
            - employee_id must exist in the system.
            - The operation retrieves both active and inactive employees.
        """
        if not employee_id:
            return { "success": False, "error": "Employee ID cannot be empty" }

        employee = self.employees.get(employee_id)
        if not employee:
            return { "success": False, "error": "Employee not found" }

        return { "success": True, "data": employee }

    def get_employee_by_work_email(self, work_email: str) -> dict:
        """
        Retrieve employee information using their work email address.

        Args:
            work_email (str): The work email address of the employee to look up.

        Returns:
            dict: {
                "success": True,
                "data": EmployeeInfo  # Full employee record
            }
            or {
                "success": False,
                "error": str  # Reason for failure, e.g. employee not found
            }

        Constraints:
            - Work email is assumed to uniquely identify an employee.
            - This is a read-only query; no state changes occur.
        """
        for employee in self.employees.values():
            if employee["work_email"] == work_email:
                return {"success": True, "data": employee}
        return {"success": False, "error": "Employee with this work email not found"}

    def list_employees_by_department(self, department_id: str) -> dict:
        """
        Retrieve all employees assigned to a specific department.

        Args:
            department_id (str): The unique identifier of the department.

        Returns:
            dict: {
                "success": True,
                "data": List[EmployeeInfo]  # List of employee records in the department (can be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Department not found"
            }

        Constraints:
            - The department_id must exist in the system.
            - Employees' department field is expected to reference a valid department_id.
        """
        if department_id not in self.departments:
            return {"success": False, "error": "Department not found"}

        employees_in_department = [
            emp_info for emp_info in self.employees.values()
            if emp_info["department"] == department_id
        ]

        return {
            "success": True,
            "data": employees_in_department
        }

    def list_employees_by_job_title(self, job_title: str) -> dict:
        """
        Retrieve all employees who hold a specific job title.

        Args:
            job_title (str): The exact job title to search for (case-sensitive).

        Returns:
            dict: {
                "success": True,
                "data": List[EmployeeInfo]  # List of employees with the given job title (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., job title not found
            }

        Constraints:
            - The job_title must exist in the system (i.e., must be a key in job_positions).
            - Only exact match is performed (case-sensitive).
        """
        if job_title not in self.job_positions:
            return { "success": False, "error": "Job title not found" }

        result = [
            employee for employee in self.employees.values()
            if employee["job_title"] == job_title
        ]

        return { "success": True, "data": result }

    def list_employees_by_employment_status(self, employment_status: str) -> dict:
        """
        Retrieve a list of employees filtered by their current employment status.

        Args:
            employment_status (str): The employment status type to filter by (e.g., 'active', 'on leave', 'terminated').

        Returns:
            dict: {
                "success": True,
                "data": List[EmployeeInfo]  # List of employees with matching employment status (may be empty)
            }
            or
            {
                "success": False,
                "error": str  # Description of error, e.g., invalid status type
            }

        Constraints:
            - employment_status must be a predefined valid status type (must exist in employment_statuses).
        """
        if employment_status not in self.employment_statuses:
            return {
                "success": False,
                "error": "Invalid employment status type"
            }

        result = [
            employee for employee in self.employees.values()
            if employee["employment_status"] == employment_status
        ]

        return {
            "success": True,
            "data": result
        }

    def get_department_by_id(self, department_id: str) -> dict:
        """
        Retrieve information about a department using its department_id.

        Args:
            department_id (str): The unique identifier of the department.

        Returns:
            dict: {
                "success": True,
                "data": DepartmentInfo  # The department's information
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Department not found"
            }

        Constraints:
            - The department_id must exist in the system.
        """
        department = self.departments.get(department_id)
        if not department:
            return {"success": False, "error": "Department not found"}

        return {"success": True, "data": department}

    def get_department_by_name(self, department_name: str) -> dict:
        """
        Retrieve department details by matching the department name.

        Args:
            department_name (str): The name of the department to search for.

        Returns:
            dict: {
                "success": True,
                "data": DepartmentInfo  # Found department's information
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. department not found
            }

        Constraints:
            - The operation performs a case-sensitive exact match.
            - If multiple departments have the same name, the first match is returned.
        """
        if not department_name:
            return { "success": False, "error": "Department name cannot be empty" }

        for dept_info in self.departments.values():
            if dept_info["department_name"] == department_name:
                return { "success": True, "data": dept_info }

        return { "success": False, "error": "Department with the given name not found" }

    def get_job_position_by_title(self, job_title: str) -> dict:
        """
        Retrieve the job position details (including salary range and department) for a given job title.

        Args:
            job_title (str): The exact job title to look up.

        Returns:
            dict: {
                "success": bool,
                "data": JobPositionInfo  # If found
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Job title not found"
            }

        Constraints:
            - The job_title must exist in the system's job positions.
        """
        if not isinstance(job_title, str):
            return { "success": False, "error": "Job title must be a string" }

        if job_title not in self.job_positions:
            return { "success": False, "error": "Job title not found" }

        return { "success": True, "data": self.job_positions[job_title] }

    def get_employment_status_info(self, status_type: str) -> dict:
        """
        Retrieve details of a predefined employment status type.

        Args:
            status_type (str): The employment status type (e.g., 'active', 'terminated', 'on leave').

        Returns:
            dict: {
                "success": True,
                "data": EmploymentStatusInfo  # Contains description and is_active flag
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., status type not found
            }

        Constraints:
            - The status_type must be one of the predefined employment status types in the system.
        """
        if not status_type:
            return { "success": False, "error": "Status type cannot be empty" }

        status_info = self.employment_statuses.get(status_type)
        if status_info is None:
            return { "success": False, "error": "Employment status type not found" }

        return { "success": True, "data": status_info }

    def check_employee_eligibility_for_action(self, employee_id: str) -> dict:
        """
        Determine if an employee is eligible for HR actions (e.g., promotion, bonus) based on their employment status.

        Eligibility is granted only if the employee's employment status is marked as active in the system.

        Args:
            employee_id (str): The unique identifier of the employee.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "eligible": bool  # True if employee's status is active, False otherwise
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g., employee not found, status undefined)
            }

        Constraints:
            - Only employees with an 'active' employment status (where is_active=True) are eligible.
            - The employee's employment_status must be a valid predefined status type.
        """
        # Check if employee exists
        if employee_id not in self.employees:
            return { "success": False, "error": f"Employee with ID '{employee_id}' not found" }

        employee = self.employees[employee_id]
        status_type = employee["employment_status"]

        # Check if the employment status is defined in the system
        if status_type not in self.employment_statuses:
            return {
                "success": False,
                "error": f"Employment status '{status_type}' is not a valid status type"
            }

        # Determine eligibility based on is_active flag
        is_eligible = self.employment_statuses[status_type]["is_active"]

        return { "success": True, "data": { "eligible": is_eligible } }

    def validate_salary_against_job(self, job_title: str, salary: float) -> dict:
        """
        Check whether a given salary falls within the defined salary range for a specified job title.

        Args:
            job_title (str): The job title to validate against.
            salary (float): The salary value to check.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "is_valid": bool  # True if salary is within the min and max range for the job
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. job title not found
            }

        Constraints:
            - The job_title must exist in the HRIS.
            - The salary must be a non-negative number (conceptually, though enforcement depends on job range).
        """
        if job_title not in self.job_positions:
            return { "success": False, "error": f"Job title '{job_title}' does not exist" }

        job = self.job_positions[job_title]
        min_salary = job["salary_range_min"]
        max_salary = job["salary_range_max"]

        is_valid = min_salary <= salary <= max_salary

        return { "success": True, "data": { "is_valid": is_valid } }

    def list_all_departments(self) -> dict:
        """
        Retrieve a list of all departments in the organization.

        Returns:
            dict: {
                "success": True,
                "data": List[DepartmentInfo]  # List of all department records; empty list if none exist
            }

        Note:
            This operation does not require any parameters and always succeeds.
            It returns all departments regardless of whether they have a manager assigned or are empty.
        """
        return {
            "success": True,
            "data": list(self.departments.values())
        }

    def list_all_job_positions(self) -> dict:
        """
        Retrieve all defined job positions in the system.

        Returns:
            dict: {
                "success": True,
                "data": List[JobPositionInfo]  # List of all job position records; may be empty
            }

        Note:
            This operation returns all job positions regardless of current usage or department validity.
            It does not validate whether the associated department_id still exists.
        """
        all_job_positions = list(self.job_positions.values())
        return {
            "success": True,
            "data": all_job_positions
        }

    def add_employee(self, employee_data: EmployeeInfo) -> dict:
        """
        Add a new employee to the HRIS, validating all required constraints.

        Args:
            employee_data (EmployeeInfo): A dictionary containing all employee fields including
                employee_id, first_name, last_name, date_of_birth, gender, hire_date, job_title,
                department, manager_id, employment_status, salary, work_email, phone_number, address.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            } or {
                "success": False,
                "error": str  # On failure
            }

        Constraints Enforced:
            - employee_id must be unique.
            - employment_status must be a valid status type in the system.
            - hire_date cannot be in the future.
            - salary must fall within the defined range for the job_title.
            - department must exist in the system (by department_name).
        """
        emp_id = employee_data["employee_id"]
        hire_date = employee_data["hire_date"]
        job_title = employee_data["job_title"]
        department_name = employee_data["department"]
        salary = employee_data["salary"]
        employment_status = employee_data["employment_status"]

        # Check 1: Employee ID must be unique
        if emp_id in self.employees:
            return {
                "success": False,
                "error": f"Employee with ID {emp_id} already exists."
            }

        # Check 2: Employment status must be valid
        if employment_status not in self.employment_statuses:
            return {
                "success": False,
                "error": f"Invalid employment status: {employment_status}."
            }

        # Check 3: Department must exist (by department_name)
        if not any(dep["department_name"] == department_name for dep in self.departments.values()):
            return {
                "success": False,
                "error": f"Department '{department_name}' does not exist."
            }

        # Check 4: Job title must exist
        if job_title not in self.job_positions:
            return {
                "success": False,
                "error": f"Job title '{job_title}' is not defined in the system."
            }

        # Check 5: Salary must be within job's salary range
        job = self.job_positions[job_title]
        if salary < job["salary_range_min"] or salary > job["salary_range_max"]:
            return {
                "success": False,
                "error": f"Salary {salary} is out of range for job '{job_title}'. "
                         f"Allowed range: [{job['salary_range_min']}, {job['salary_range_max']}]."
            }

        # Check 6: Hire date cannot be in the future
        try:
            hire_dt = datetime.strptime(hire_date, "%Y-%m-%d")
            if hire_dt > datetime.now():
                return {
                    "success": False,
                    "error": "Hire date cannot be in the future."
                }
        except ValueError:
            return {
                "success": False,
                "error": "Invalid hire date format. Expected YYYY-MM-DD."
            }

        # All checks passed — add employee
        self.employees[emp_id] = employee_data
        return {
            "success": True,
            "message": "Employee added successfully."
        }

    def update_employee_info(self, employee_id: str, updates: dict) -> dict:
        """
        Modify non-status employee attributes such as phone number, address, work email, etc.
        Ensures data integrity by validating allowed fields and data formats.

        Args:
            employee_id (str): The unique ID of the employee to update.
            updates (dict): Dictionary of key-value pairs for fields to update.
                           Allowed fields: first_name, last_name, date_of_birth, gender,
                                          phone_number, work_email, address.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Description of validation or existence failure
            }

        Constraints:
            - Employee must exist.
            - Only allowed fields can be updated (excluding employment_status, salary, job_title, department, manager_id, hire_date, employee_id).
            - work_email must contain '@' if provided.
            - date_of_birth must be in YYYY-MM-DD format and not in the future.
        """
        # Check if employee exists
        if employee_id not in self.employees:
            return {"success": False, "error": f"Employee with ID {employee_id} not found."}

        employee = self.employees[employee_id]

        # Define modifiable fields (non-status, non-structural)
        allowed_fields = {
            'first_name', 'last_name', 'date_of_birth', 'gender',
            'phone_number', 'work_email', 'address'
        }

        # Validate requested fields
        for key in updates.keys():
            if key not in allowed_fields:
                return {
                    "success": False,
                    "error": f"Cannot update field '{key}'. Only non-status personal details can be updated."
                }

        # Validate work_email format if being updated
        if 'work_email' in updates:
            email = updates['work_email']
            if not isinstance(email, str) or '@' not in email:
                return {"success": False, "error": "Invalid email format."}

        # Validate date_of_birth if being updated
        if 'date_of_birth' in updates:
            dob_str = updates['date_of_birth']
            try:
                dob = datetime.strptime(dob_str, "%Y-%m-%d")
                if dob > datetime.now():
                    return {"success": False, "error": "Date of birth cannot be in the future."}
            except ValueError:
                return {"success": False, "error": "Invalid date format for date_of_birth. Use YYYY-MM-DD."}

        # Apply all updates (no constraint violation at this point)
        for key, value in updates.items():
            employee[key] = value

        # Persist updated employee info
        self.employees[employee_id] = employee

        return {"success": True, "message": "Employee info updated successfully."}

    def update_employee_job_title(self, employee_id: str, new_job_title: str) -> dict:
        """
        Update an employee's job title after validating salary alignment and department compatibility.

        Args:
            employee_id (str): Unique identifier of the employee.
            new_job_title (str): The new job title to assign.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Employee must exist.
            - New job title must exist in job_positions.
            - Employee's current salary must fall within the salary range of the new job title.
            - Employee's current department must match the department_id of the new job position.
        """
        # Check if employee exists
        if employee_id not in self.employees:
            return { "success": False, "error": f"Employee with ID {employee_id} not found." }

        employee = self.employees[employee_id]

        # Check if new job title exists
        if new_job_title not in self.job_positions:
            return { "success": False, "error": f"Job title '{new_job_title}' not found." }

        job_position = self.job_positions[new_job_title]

        # Check department alignment: employee's department must match job's department_id
        if employee["department"] != job_position["department_id"]:
            return {
                "success": False,
                "error": f"Employee's department ({employee['department']}) does not match "
                         f"the required department ({job_position['department_id']}) for job title '{new_job_title}'."
            }

        # Check salary alignment: current salary must be within new job's range
        if not (job_position["salary_range_min"] <= employee["salary"] <= job_position["salary_range_max"]):
            return {
                "success": False,
                "error": f"Employee's current salary ({employee['salary']}) is not within the "
                         f"salary range ({job_position['salary_range_min']}-{job_position['salary_range_max']}) "
                         f"for job title '{new_job_title}'."
            }

        # All validations passed — update job title
        employee["job_title"] = new_job_title

        return {
            "success": True,
            "message": "Employee job title updated successfully."
        }

    def transfer_employee_to_department(self, employee_id: str, new_department_id: str) -> dict:
        """
        Move an employee to a different department, ensuring the target department exists.

        Args:
            employee_id (str): The unique ID of the employee to transfer.
            new_department_id (str): The ID of the target department.

        Returns:
            dict: {
                "success": True,
                "message": str  # Describes the transfer action
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., employee not found, invalid department)
            }

        Constraints:
            - The employee must exist.
            - The target department must exist in the system.
            - After transfer, the employee's department is updated.
        """
        if not employee_id or not new_department_id:
            return { "success": False, "error": "Employee ID and department ID cannot be empty" }

        if employee_id not in self.employees:
            return { "success": False, "error": "Employee not found" }

        if new_department_id not in self.departments:
            return { "success": False, "error": "Target department does not exist" }

        # Perform the transfer
        self.employees[employee_id]["department"] = new_department_id

        return {
            "success": True,
            "message": f"Employee {employee_id} transferred to department {new_department_id}."
        }

    def update_employee_salary(self, employee_id: str, new_salary: float) -> dict:
        """
        Adjust an employee's salary, ensuring it falls within the range defined for their current job title.

        Args:
            employee_id (str): The unique ID of the employee.
            new_salary (float): The new salary to assign.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Explanation of failure
            }

        Constraints:
            - Employee must exist.
            - Employee's job title must exist in job_positions.
            - New salary must be within the min and max range for the job title.
            - New salary must be non-negative.
        """
        if employee_id not in self.employees:
            return { "success": False, "error": f"Employee with ID '{employee_id}' does not exist." }

        employee = self.employees[employee_id]

        if new_salary < 0:
            return { "success": False, "error": "Salary cannot be negative." }

        job_title = employee["job_title"]
        if job_title not in self.job_positions:
            return { "success": False, "error": f"Job title '{job_title}' is not defined in the system." }

        job = self.job_positions[job_title]
        if not (job["salary_range_min"] <= new_salary <= job["salary_range_max"]):
            return {
                "success": False,
                "error": (
                    f"Salary ${new_salary} is out of range for job '{job_title}'. "
                    f"Allowed range: ${job['salary_range_min']} - ${job['salary_range_max']}."
                )
            }

        # Update salary
        employee["salary"] = new_salary

        return { "success": True, "message": "Employee salary updated successfully." }

    def update_employment_status(self, employee_id: str, new_status: str) -> dict:
        """
        Change an employee's employment status to a new valid predefined type.

        Args:
            employee_id (str): The unique ID of the employee.
            new_status (str): The new employment status to assign (must be a predefined valid type).

        Returns:
            dict: {
                "success": bool,
                "message": str  # Describes success or error
            }

        Constraints:
            - The employee must exist.
            - The new_status must be a predefined valid status type in the system.
            - Only valid status types from self.employment_statuses are allowed.
        """
        if not employee_id:
            return { "success": False, "error": "Employee ID is required" }

        if not new_status:
            return { "success": False, "error": "New status is required" }

        if employee_id not in self.employees:
            return { "success": False, "error": f"Employee with ID '{employee_id}' does not exist" }

        if new_status not in self.employment_statuses:
            return { 
                "success": False, 
                "error": f"Invalid employment status: '{new_status}'. Must be one of the predefined status types." 
            }

        # Update the employment status
        self.employees[employee_id]["employment_status"] = new_status

        return { 
            "success": True, 
            "message": f"Employment status updated for employee {employee_id} to {new_status}." 
        }

    def deactivate_employee(self, employee_id: str) -> dict:
        """
        Deactivate an employee by setting their employment status to an inactive status (e.g., terminated).

        Args:
            employee_id (str): The unique ID of the employee to deactivate.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Success description or error details
            }

        Constraints:
            - The employee must exist.
            - A valid inactive employment status (is_active=False) must exist in the system.
            - employment_status must be one of the predefined valid status types.
        """
        # Check if employee exists
        if employee_id not in self.employees:
            return {
                "success": False,
                "error": f"Employee with ID '{employee_id}' not found."
            }

        # Find an inactive status (e.g., terminated) that exists in employment_statuses
        inactive_status = None
        for status_type, status_info in self.employment_statuses.items():
            if not status_info["is_active"]:
                inactive_status = status_type
                break

        if inactive_status is None:
            return {
                "success": False,
                "error": "No inactive employment status (e.g., terminated) defined in the system."
            }

        # Update the employee's employment status
        employee = self.employees[employee_id]
        employee["employment_status"] = inactive_status

        return {
            "success": True,
            "message": f"Employee '{employee_id}' has been deactivated with status '{inactive_status}'."
        }

    def reactivate_employee(self, employee_id: str) -> dict:
        """
        Restore a previously terminated employee to active status, if allowed by policy.

        Args:
            employee_id (str): The unique ID of the employee to reactivate.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - Employee must exist and currently have a terminated/inactive status.
            - Target status "active" must be a valid employment status.
            - Employee's department must still exist in the system.
        """
        # Check if employee exists
        if employee_id not in self.employees:
            return {"success": False, "error": "Employee not found"}

        employee = self.employees[employee_id]

        # Verify current status is inactive (e.g., terminated)
        current_status = employee["employment_status"]
        current_status_info = self.employment_statuses.get(current_status)
        if current_status_info and current_status_info["is_active"]:
            return {"success": False, "error": "Employee is already active"}

        # Ensure "active" status is defined and valid
        if "active" not in self.employment_statuses:
            return {"success": False, "error": "Active status is not defined in the system"}

        active_status_info = self.employment_statuses["active"]
        if not active_status_info["is_active"]:
            return {"success": False, "error": "Active status is not marked as active in the system"}

        # Ensure employee's department still exists
        department_id = employee["department"]
        if department_id not in self.departments:
            return {"success": False, "error": f"Employee's department '{department_id}' does not exist"}

        # Update employment status to active
        employee["employment_status"] = "active"

        return {"success": True, "message": "Employee reactivated successfully."}

    def remove_employee_record(self, employee_id: str) -> dict:
        """
        Permanently delete an employee's record from the HRIS.

        Args:
            employee_id (str): The unique identifier of the employee to remove.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": bool,
                "error": str  # On failure
            }

        Constraints:
            - The employee_id must exist in the system.
            - No additional checks (e.g., employment status) are required for deletion.
        """
        if not employee_id:
            return {"success": False, "error": "Employee ID is required."}

        if employee_id not in self.employees:
            return {"success": False, "error": "Employee not found."}

        del self.employees[employee_id]

        return {"success": True, "message": "Employee record removed successfully."}

