        }

    def check_condition_exists(self, condition_id: str = None, name: str = None) -> dict:
        """
        Check whether a medical condition with the given condition_id or name already exists in the database.

        Args:
            condition_id (str, optional): The unique ID of the condition to check.
            name (str, optional): The name of the condition to check.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "exists_by_id": bool,   # True if condition_id exists
                    "exists_by_name": bool  # True if name exists
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. missing parameters
            }

        Constraints:
            - Either condition_id or name must be provided.
            - condition_id and name are unique across the database.
        """
        if condition_id is None and name is None:
            return {
                "success": False,
                "error": "Either condition_id or name must be provided."
            }

        exists_by_id = False
        exists_by_name = False

        if condition_id is not None:
            exists_by_id = condition_id in self.conditions

        if name is not None:
            exists_by_name = any(cond["name"] == name for cond in self.conditions.values())

        return {
            "success": True,
            "data": {
                "exists_by_id": exists_by_id,
                "exists_by_name": exists_by_name
            }
        }

    def list_conditions_by_category(self, category_id: str) -> dict:
        """
        Retrieve all medical conditions belonging to a specific category.

        Args:
            category_id (str): The unique identifier of the medical category.

        Returns:
            dict: {
                "success": True,
                "data": List[MedicalConditionInfo]  # List of condition details in the category
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., category not found
            }

        Constraints:
            - The category_id must exist in the database.
            - The list of conditions is based on prior assignments (via assignment operations).
            - If no conditions are assigned, an empty list is returned (not an error).
        """
        # Check if the category exists
        if category_id not in self.categories:
            return {"success": False, "error": "Category does not exist"}

        # Initialize or assume existence of category-to-conditions mapping
        # In practice, this should be initialized in __init__, e.g.:
        # self.category_to_conditions = {}
        if not hasattr(self, 'category_to_conditions'):
            self.category_to_conditions = {}

        # Get condition IDs assigned to this category
        condition_ids = self.category_to_conditions.get(category_id, [])

        # Retrieve full condition info for each condition_id
        conditions_in_category = []
        for cond_id in condition_ids:
            if cond_id in self.conditions:
                conditions_in_category.append(self.conditions[cond_id])

        return {"success": True, "data": conditions_in_category}

