    def get_category_hierarchy(self, category_id: str) -> dict:
        """
        Return the full hierarchy path of category names from root to the specified category.

        Args:
            category_id (str): The ID of the category to retrieve the hierarchy for.

        Returns:
            dict: {
                "success": True,
                "data": List[str]  # List of category names from root to the given category
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g., category not found, invalid hierarchy)
            }

        Constraints:
            - The category_id must exist in the database.
            - The parent_category of each category must either be a valid category_id or empty.
            - Cycles in hierarchy are not allowed.
        """
        if not category_id:
            return {"success": False, "error": "Category ID cannot be empty"}

        if category_id not in self.categories:
            return {"success": False, "error": "Category not found"}

        hierarchy = []
        visited = set()
        current_id = category_id

        # Traverse upward until we reach the root (parent_category is empty or None)
        while current_id:
            if current_id in visited:
                return {"success": False, "error": "Circular reference detected in category hierarchy"}
            visited.add(current_id)

            category = self.categories[current_id]
            hierarchy.append(category["category_name"])

            current_id = category["parent_category"]

            # Defensive check: if parent_category is self-reference or not in DB (unless it's empty)
            if current_id and current_id not in self.categories:
                return {"success": False, "error": f"Parent category '{current_id}' does not exist"}

        # Reverse to get root -> ... -> target
        hierarchy.reverse()
        return {"success": True, "data": hierarchy}

