    def validate_classification_code(self, code_type: str, code_value: str) -> Dict:
        """
        Check whether a given classification code follows the valid format syntax for the specified standard.

        Args:
            code_type (str): The coding system (e.g., "ICD-10", "SNOMED CT").
            code_value (str): The code to validate (e.g., "A00.1").

        Returns:
            dict: {
                "success": bool,
                "data": {
                    "valid": bool,
                    "reason": str  # Optional, included if invalid
                }
            }

        Supported standards and formats:
            - "ICD-10": Format - Letter + two digits + optional decimal part (e.g., A00.1, B12)
            - "SNOMED CT": Format - 6 to 8 digits (e.g., 123456, 195967001)

        Note: This validates only syntax, not whether the code exists in the official system.
        """
        if not code_type or not isinstance(code_type, str):
            return { "success": False, "error": "code_type must be a non-empty string" }
        if not code_value or not isinstance(code_value, str):
            return { "success": False, "error": "code_value must be a non-empty string" }

        code_type = code_type.strip()
        code_value = code_value.strip()

        if code_type == "ICD-10":
            # ICD-10: Letter + 2 digits + optional decimal and digits (e.g., A00, A00.1)
            pattern = r"^[A-Z]\d{2}(\.\d+)?$"
            is_valid = re.fullmatch(pattern, code_value) is not None
            if not is_valid:
                return {
                    "success": True,
                    "data": {
                        "valid": False,
                        "reason": "ICD-10 code must be in format: letter + two digits + optional decimal (e.g., A00.1)"
                    }
                }
            return { "success": True, "data": { "valid": True } }

        elif code_type == "SNOMED CT":
            # SNOMED CT: 6 to 8 digits
            pattern = r"^\d{6,8}$"
            is_valid = re.fullmatch(pattern, code_value) is not None
            if not is_valid:
                return {
                    "success": True,
                    "data": {
                        "valid": False,
                        "reason": "SNOMED CT code must be 6 to 8 digits"
                    }
                }
            return { "success": True, "data": { "valid": True } }

        else:
            return {
                "success": True,
                "data": {
                    "valid": False,
                    "reason": "Unsupported code type. Supported types: 'ICD-10', 'SNOMED CT'"
                }
            }

    def search_conditions_by_symptom(self, symptom: str) -> dict:
