    def add_medical_condition(
        self,
        condition_id: str,
        name: str,
        description: str = "",
        symptoms: List[str] = None,
        diagnostic_criteria: str = "",
        treatments: List[str] = None,
        classification_codes: Dict[str, str] = None,
    ) -> Dict[str, Any]:
        """
        Add a new medical condition with validated attributes, auto-setting date_added and last_updated.

        Args:
            condition_id (str): Unique identifier for the condition.
            name (str): Full name of the medical condition (must be unique).
            description (str): Optional description of the condition.
            symptoms (List[str]): List of symptoms associated with the condition.
            diagnostic_criteria (str): Required criteria for diagnosis.
            treatments (List[str]): List of common treatments.
            classification_codes (Dict[str, str]): Mapping of standard codes (e.g., {"ICD-10": "A00.1"}).

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
                "error": str     # On failure
            }

        Constraints:
            - condition_id must be unique.
            - name must be unique.
            - name and diagnostic_criteria are required.
            - classification_codes must be valid (using standard formats like ICD-10).
            - date_added and last_updated are set automatically.
        """
        # Required fields presence check
        if not name:
            return {"success": False, "error": "Name is required."}
        if not diagnostic_criteria:
            return {"success": False, "error": "Diagnostic criteria is required."}

        # Uniqueness checks
        if condition_id in self.conditions:
            return {"success": False, "error": "Condition ID already exists."}

        # Check for duplicate name
        for cond in self.conditions.values():
            if cond["name"].lower() == name.lower():
                return {"success": False, "error": "A condition with this name already exists."}

        # Validate classification codes if provided
        if classification_codes:
            for system, code in classification_codes.items():
                validation = self.validate_classification_code(system, code)
                if not validation["success"]:
                    error_msg = validation.get("error", "Invalid classification code.")
                    return {"success": False, "error": f"Invalid {system} code: {error_msg}"}

        # Auto-set timestamps
        current_time = time.time()

        # Use empty lists if not provided
        symptoms = symptoms or []
        treatments = treatments or []
        classification_codes = classification_codes or {}

        # Create the new condition record
        new_condition: MedicalConditionInfo = {
            "condition_id": condition_id,
            "name": name,
            "description": description,
            "symptoms": symptoms,
            "diagnostic_criteria": diagnostic_criteria,
            "treatments": treatments,
            "classification_codes": classification_codes,
            "date_added": current_time,
            "last_updated": current_time,
        }

        # Add to the database
        self.conditions[condition_id] = new_condition

        return {"success": True, "message": "Medical condition added successfully."}


    def update_medical_condition(self, condition_id: str, updates: Dict[str, Any]) -> dict:
        """
        Modify an existing medical condition's attributes and update the last_updated timestamp.

        Args:
            condition_id (str): The unique ID of the medical condition to update.
            updates (dict): A dictionary of key-value pairs representing the fields to update.
                Allowed keys: name, description, symptoms, diagnostic_criteria, treatments,
                              classification_codes.
                Note: condition_id and date_added cannot be updated.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present if success is True
                "error": str     # Present if success is False
            }

        Constraints:
            - The condition must exist.
            - The name must remain unique if updated.
            - diagnostic_criteria must be non-empty if provided.
            - classification_codes must conform to valid formats (e.g., ICD-10, SNOMED CT).
            - last_updated timestamp is automatically refreshed on successful update.
        """
        # Check if condition exists
        if condition_id not in self.conditions:
            return {"success": False, "error": f"Condition with ID '{condition_id}' does not exist."}

        condition = self.conditions[condition_id]

        # Handle name uniqueness if name is being updated
        if "name" in updates:
            new_name = updates["name"]
            if not new_name:
                return {"success": False, "error": "Name cannot be empty."}
            # Check uniqueness
            for cond in self.conditions.values():
                if cond["name"] == new_name and cond["condition_id"] != condition_id:
                    return {"success": False, "error": f"Condition name '{new_name}' is already in use."}

        # Validate diagnostic_criteria if being updated
        if "diagnostic_criteria" in updates:
            criteria = updates["diagnostic_criteria"]
            if not criteria or not criteria.strip():
                return {"success": False, "error": "Diagnostic criteria cannot be empty."}
            updates["diagnostic_criteria"] = criteria.strip()

        # Validate classification_codes if being updated
        if "classification_codes" in updates:
            codes = updates["classification_codes"]
            if not isinstance(codes, dict):
                return {"success": False, "error": "classification_codes must be a dictionary."}
            for system, code in codes.items():
                validation = self.validate_classification_code(system, code)
                if not validation["success"]:
                    return {"success": False, "error": f"Invalid classification code: {validation['error']}"}

        # Apply updates
        for key, value in updates.items():
            if key in condition and key not in ["condition_id", "date_added"]:
                condition[key] = value

        # Update last_updated timestamp
        condition["last_updated"] = time.time()

        return {"success": True, "message": "Medical condition updated successfully."}

    def delete_medical_condition(self, condition_id: str) -> dict:
        """
        Remove a medical condition from the database by its condition_id.

        Args:
            condition_id (str): The unique identifier of the medical condition to delete.

        Returns:
            dict: {
                "success": True,
                "message": "Medical condition deleted successfully."
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. condition not found
            }

        Constraints:
            - The condition_id must exist in the database.
            - This operation performs a hard delete (permanent removal).
        """
        if not isinstance(condition_id, str) or not condition_id.strip():
            return { "success": False, "error": "Invalid condition_id: must be a non-empty string." }

        condition_id = condition_id.strip()

        if condition_id not in self.conditions:
            return { "success": False, "error": f"Condition with ID '{condition_id}' not found." }

        del self.conditions[condition_id]

        return { "success": True, "message": "Medical condition deleted successfully." }

    def add_medical_category(self, category_id: str, category_name: str, parent_category: str = "") -> dict:
        """
        Create a new category to classify medical conditions.

        Args:
            category_id (str): Unique identifier for the category.
            category_name (str): Name of the category (e.g., "Neurological Disorders").
            parent_category (str): ID of the parent category. Use empty string for root-level categories.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - category_id must be unique.
            - category_name must be non-empty.
            - parent_category, if specified and non-empty, must exist in the database.
        """
        if not category_id or not category_id.strip():
            return { "success": False, "error": "category_id is required and cannot be empty" }

        if not category_name or not category_name.strip():
            return { "success": False, "error": "category_name is required and cannot be empty" }

        category_id = category_id.strip()
        category_name = category_name.strip()

        if category_id in self.categories:
            return { "success": False, "error": f"Category with ID '{category_id}' already exists" }

        if parent_category:
            if parent_category not in self.categories:
                return { "success": False, "error": f"Parent category with ID '{parent_category}' does not exist" }

        # Create new category
        new_category: MedicalCategoryInfo = {
            "category_id": category_id,
            "category_name": category_name,
            "parent_category": parent_category
        }

        self.categories[category_id] = new_category

        return { "success": True, "message": "Medical category added successfully." }

    def update_medical_category(self, category_id: str, new_name: str = None, new_parent_id: str = None) -> dict:
        """
        Modify an existing medical category's name or parent relationship.

        Args:
            category_id (str): The unique ID of the category to update.
            new_name (str, optional): New name for the category. Must be unique if provided.
            new_parent_id (str, optional): The new parent category ID. Must be an existing category ID
                                          or None/empty string to set as root. Must not create a cycle.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present on success
                "error": str     # Present on failure
            }

        Constraints:
            - The category_id must exist.
            - Category names must remain unique.
            - Parent category must exist (if not root).
            - The hierarchy must remain acyclic.
        """
        if category_id not in self.categories:
            return {"success": False, "error": f"Category with ID '{category_id}' does not exist."}

        category = self.categories[category_id]

        # Check for name uniqueness if new_name is provided
        if new_name is not None and new_name != category["category_name"]:
            existing_names = {
                cat["category_name"] for cid, cat in self.categories.items() if cid != category_id
            }
            if new_name in existing_names:
                return {"success": False, "error": f"Category name '{new_name}' already exists."}
            category["category_name"] = new_name

        # Handle parent update
        if new_parent_id is not None:
            # Normalize empty string to None for consistency
            parent_id = new_parent_id if new_parent_id else None

            # If setting to root (None), no cycle check needed
            if parent_id is not None:
                if parent_id not in self.categories:
                    return {"success": False, "error": f"Parent category with ID '{parent_id}' does not exist."}

                # Prevent self-reference
                if parent_id == category_id:
                    return {"success": False, "error": "A category cannot be its own parent."}

                # Check for cycles: trace up the hierarchy from parent_id
                seen_ids = set()
                current = parent_id
                while current:
                    if current == category_id:
                        return {"success": False, "error": "Cannot set parent: would create a cycle in category hierarchy."}
                    if current in seen_ids:
                        return {"success": False, "error": "Invalid hierarchy: circular reference detected."}
                    seen_ids.add(current)
                    current = self.categories.get(current, {}).get("parent_category")

                category["parent_category"] = parent_id
            else:
                category["parent_category"] = ""

        return {"success": True, "message": "Medical category updated successfully."}

    def assign_condition_to_category(self, condition_id: str, category_id: str) -> dict:
        """
        Link a medical condition to a specific category.

        Args:
            condition_id (str): The unique ID of the medical condition.
            category_id (str): The unique ID of the medical category.

        Returns:
            dict: {
                "success": bool,
                "message": str  # Present if success=True
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - The condition_id must exist in the database.
            - The category_id must exist in the database.
            - The last_updated timestamp of the condition is updated upon assignment.
            - Duplicate assignments are ignored (idempotent).
        """
        # Input validation
        if not isinstance(condition_id, str) or not condition_id.strip():
            return { "success": False, "error": "Invalid condition_id: must be a non-empty string" }
        if not isinstance(category_id, str) or not category_id.strip():
            return { "success": False, "error": "Invalid category_id: must be a non-empty string" }
        condition_id = condition_id.strip()
        category_id = category_id.strip()

        # Check if condition exists
        if condition_id not in self.conditions:
            return { "success": False, "error": f"Condition with ID '{condition_id}' does not exist" }

        # Check if category exists
        if category_id not in self.categories:
            return { "success": False, "error": f"Category with ID '{category_id}' does not exist" }

        # Initialize condition-category mapping if not present
        if not hasattr(self, 'condition_category_map'):
            self.condition_category_map: Dict[str, List[str]] = {}

        # Get current categories for the condition, initialize if needed
        if condition_id not in self.condition_category_map:
            self.condition_category_map[condition_id] = []

        # Avoid duplicate assignment
        if category_id in self.condition_category_map[condition_id]:
            # Already assigned
            pass
        else:
            self.condition_category_map[condition_id].append(category_id)

        # Update the condition's last_updated timestamp
        self.conditions[condition_id]['last_updated'] = time.time()

        return { "success": True, "message": "Condition assigned to category successfully." }

    def register_healthcare_provider(
        self,
        provider_id: str,
        name: str,
        institution: str,
        role: str
    ) -> dict:
        """
        Add a new healthcare provider who can submit or approve condition data.

        Args:
            provider_id (str): Unique identifier for the provider.
            name (str): Full name of the healthcare provider.
            institution (str): Affiliation (e.g., hospital, clinic, university).
            role (str): Professional role (e.g., 'Physician', 'Researcher', 'Data Curator').

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # On failure
            }

        Constraints:
            - provider_id must be unique.
            - provider_id, name, institution, and role must be non-empty strings.
        """
        if not provider_id:
            return {"success": False, "error": "provider_id is required"}
        if not name:
            return {"success": False, "error": "name is required"}
        if not institution:
            return {"success": False, "error": "institution is required"}
        if not role:
            return {"success": False, "error": "role is required"}

        if provider_id in self.providers:
            return {"success": False, "error": "Provider with this provider_id already exists"}

        self.providers[provider_id] = HealthcareProviderInfo(
            provider_id=provider_id,
            name=name,
            institution=institution,
            role=role
        )

        return {"success": True, "message": "Healthcare provider registered successfully"}

    def update_condition_classification_codes(self, condition_id: str, classification_codes: Dict[str, str]) -> dict:
        """
        Add or revise standard classification codes (e.g., ICD-10, SNOMED CT) for an existing medical condition.

        Args:
            condition_id (str): The unique ID of the medical condition to update.
            classification_codes (Dict[str, str]): A dictionary of classification codes, 
                where keys are standard names (e.g., "ICD-10", "SNOMED CT") and values are the assigned codes.

        Returns:
            dict: {
                "success": True,
                "message": "Classification codes updated for condition [condition_id]."
            }
            or
            {
                "success": False,
                "error": str  # Description of the error (e.g., condition not found, invalid codes)
            }

        Constraints:
            - The condition_id must exist in the database.
            - classification_codes must be a dictionary of strings to strings.
            - The last_updated timestamp is automatically updated upon successful modification.
            - classification_codes should conform to standard formats (e.g., ICD-10, SNOMED CT); 
              basic structural validation is performed (non-empty keys/values).
        """
        # Check if condition exists
        if condition_id not in self.conditions:
            return { "success": False, "error": f"Condition with ID '{condition_id}' not found." }

        # Validate classification_codes
        if not isinstance(classification_codes, dict):
            return { "success": False, "error": "classification_codes must be a dictionary." }

        # Ensure all keys and values are strings and non-empty
        for key, value in classification_codes.items():
            if not isinstance(key, str) or not key.strip():
                return { "success": False, "error": "Classification code keys must be non-empty strings." }
            if not isinstance(value, str) or not value.strip():
                return { "success": False, "error": "Classification code values must be non-empty strings." }

        # Update the classification_codes
        self.conditions[condition_id]["classification_codes"] = {
            k.strip(): v.strip() for k, v in classification_codes.items()
        }

        # Update last_updated timestamp (assume current time is represented as a float Unix timestamp)
        self.conditions[condition_id]["last_updated"] = time.time()

        return {
            "success": True,
            "message": f"Classification codes updated for condition {condition_id}."
        }


    def bulk_import_conditions(self, conditions_list: List[Dict[str, Any]]) -> Dict[str, Any]:
        """
        Import multiple medical conditions into the database with validation.
        Each condition is validated before insertion. Errors are reported per condition,
        and partial imports are allowed.

        Args:
            conditions_list (List[Dict]): A list of condition dictionaries with keys:
                - condition_id (str)
                - name (str)
                - description (str, optional)
                - symptoms (List[str], optional)
                - diagnostic_criteria (str) [required]
                - treatments (List[str], optional)
                - classification_codes (Dict[str, str], optional)
                - Other fields are ignored.

        Returns:
            dict: {
                "success": bool,
                "message": str,
                "imported": List[str],  # list of imported condition_id(s)
                "failed": List[Dict]    # list of { condition_id, error }
            }
            or in case of total failure:
            {
                "success": False,
                "error": str,
                "failed": List[Dict]
            }

        Constraints:
            - condition_id must be unique (globally).
            - name must be unique (globally).
            - diagnostic_criteria is required.
            - classification_codes must conform to known formats (e.g., ICD-10, SNOMED CT).
            - date_added and last_updated are auto-generated.
        """
        imported: List[str] = []
        failed: List[Dict[str, str]] = []
        current_time = time.time()

        for cond in conditions_list:
            condition_id = str(cond.get("condition_id", "")).strip()
            name = str(cond.get("name", "")).strip()
            diagnostic_criteria = str(cond.get("diagnostic_criteria", "")).strip()

            # Required fields check
            if not condition_id:
                failed.append({"condition_id": condition_id, "error": "Missing condition_id"})
                continue
            if not name:
                failed.append({"condition_id": condition_id, "error": "Missing name"})
                continue
            if not diagnostic_criteria:
                failed.append({"condition_id": condition_id, "error": "Missing diagnostic_criteria"})
                continue

            # Uniqueness checks
            if condition_id in self.conditions:
                failed.append({"condition_id": condition_id, "error": "Duplicate condition_id"})
                continue

            if any(c["name"].lower() == name.lower() for c in self.conditions.values()):
                failed.append({"condition_id": condition_id, "error": "Duplicate condition name"})
                continue

            # Validate classification codes if present
            classification_codes = cond.get("classification_codes", {})
            if classification_codes:
                invalid_codes = []
                for code_type, code_value in classification_codes.items():
                    code_value_str = str(code_value)
                    if code_type == "ICD-10":
                        if not re.match(r"^[A-Z]\d{2}(\.\d+)?$", code_value_str):
                            invalid_codes.append(f"{code_type}:{code_value_str}")
                    elif code_type == "SNOMED CT":
                        if not (code_value_str.isdigit() and len(code_value_str) >= 6):
                            invalid_codes.append(f"{code_type}:{code_value_str}")
                    else:
                        invalid_codes.append(f"{code_type}:{code_value_str}")
                if invalid_codes:
                    failed.append({
                        "condition_id": condition_id,
                        "error": f"Invalid classification codes: {', '.join(invalid_codes)}"
                    })
                    continue

            # Build valid condition object
            condition_entry: Dict[str, Any] = {
                "condition_id": condition_id,
                "name": name,
                "description": cond.get("description", ""),
                "symptoms": cond.get("symptoms", []),
                "diagnostic_criteria": diagnostic_criteria,
                "treatments": cond.get("treatments", []),
                "classification_codes": classification_codes,
                "date_added": current_time,
                "last_updated": current_time
            }

            self.conditions[condition_id] = condition_entry
            imported.append(condition_id)

        if imported:
            message = f"{len(imported)} condition(s) imported successfully, {len(failed)} failed."
            return {
                "success": True,
                "message": message,
                "imported": imported,
                "failed": failed
            }
        else:
            return {
                "success": False,
                "error": "All conditions failed validation.",
                "failed": failed
            }


    def deprecate_condition(self, condition_id: str) -> dict:
        """
        Mark a medical condition as deprecated (no longer used) without deleting it.

        Args:
            condition_id (str): The unique ID of the medical condition to deprecate.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success: description of deprecation
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Side Effects:
            - Sets 'is_deprecated' = True in the condition's record.
            - Updates 'last_updated' timestamp.
            - Does not delete or modify condition_id, name, or other core fields.

        Constraints:
            - The condition must exist in the database.
            - The operation does not remove the condition.
            - last_updated is automatically updated.
        """
        if condition_id not in self.conditions:
            return { "success": False, "error": "Condition not found" }

        condition = self.conditions[condition_id]

        # Mark as deprecated
        condition["is_deprecated"] = True
        # Update timestamp
        condition["last_updated"] = time.time()

        return {
            "success": True,
            "message": f"Condition '{condition_id}' has been deprecated."
        }

