        if not code_type or not isinstance(code_type, str):
            return { "success": False, "error": "code_type must be a non-empty string" }
        if not code_value or not isinstance(code_value, str):
            return { "success": False, "error": "code_value must be a non-empty string" }

        code_type = code_type.strip()
        code_value = code_value.strip()

        if code_type == "ICD-10":
            # ICD-10: Letter + 2 digits + optional decimal and digits (e.g., A00, A00.1)
            pattern = r"^[A-Z]\d{2}(\.\d+)?$"
            is_valid = re.fullmatch(pattern, code_value) is not None
            if not is_valid:
                return {
                    "success": True,
                    "data": {
                        "valid": False,
                        "reason": "ICD-10 code must be in format: letter + two digits + optional decimal (e.g., A00.1)"
                    }
                }
            return { "success": True, "data": { "valid": True } }

        elif code_type == "SNOMED CT":
            # SNOMED CT: 6 to 8 digits
            pattern = r"^\d{6,8}$"
            is_valid = re.fullmatch(pattern, code_value) is not None
            if not is_valid:
                return {
                    "success": True,
                    "data": {
                        "valid": False,
                        "reason": "SNOMED CT code must be 6 to 8 digits"
                    }
                }
            return { "success": True, "data": { "valid": True } }

        else:
            return {
                "success": True,
                "data": {
                    "valid": False,
                    "reason": "Unsupported code type. Supported types: 'ICD-10', 'SNOMED CT'"
                }
            }"}, "search_conditions_by_symptom": {"signature": {"parameters": [{"name": "symptom", "type": "str", "default": null, "kind": "positional-or-keyword"}], "return": "dict"}, "doc": "Find all medical conditions associated with a specific symptom.

