from typing import Dict, List, TypedDict
import datetime
from datetime import datetime



class FinancialReportInfo(TypedDict):
    report_id: str
    report_type: str
    fiscal_period: str
    generation_date: str
    status: str  # 'draft' or 'final'
    version: int
    summary: str
    author_department: str

class FinancialStatementInfo(TypedDict):
    statement_id: str
    report_id: str
    statement_type: str  # 'income', 'balance_sheet', 'cash_flow'
    line_items: List[str]  # list of item_ids

class LineItemInfo(TypedDict):
    item_id: str
    statement_id: str
    category: str  # e.g., 'revenue', 'operating_expense', 'assets'
    value: float
    currency: str  # required
    time_period: str

class FiscalPeriodInfo(TypedDict):
    period_id: str
    start_date: str
    end_date: str
    period_type: str  # 'quarterly', 'annual'
    is_closed: bool

class CorporateFinancialReportingSystem:
    def __init__(self):
        """
        Stateful corporate financial reporting system.
        Manages financial reports, statements, line items, and fiscal periods.
        """

        # Financial reports: {report_id: FinancialReportInfo}
        self.reports: Dict[str, FinancialReportInfo] = {}

        # Financial statements: {statement_id: FinancialStatementInfo}
        self.statements: Dict[str, FinancialStatementInfo] = {}

        # Line items: {item_id: LineItemInfo}
        self.line_items: Dict[str, LineItemInfo] = {}

        # Fiscal periods: {period_id: FiscalPeriodInfo}
        self.fiscal_periods: Dict[str, FiscalPeriodInfo] = {}

        # Constraints (to be enforced in methods):
        # - Only finalized reports (status = "final") can be used for external communication
        # - Each fiscal period must be closed before a final report can be generated
        # - Financial statements in a report must align with the report’s fiscal period
        # - The "latest" report is determined by the most recent generation_date among finalized reports
        # - All monetary values must be recorded with a specified currency

    def get_all_finalized_reports(self) -> dict:
        """
        Retrieve all financial reports with status 'final', suitable for external use.

        Returns:
            dict: {
                "success": True,
                "data": List[FinancialReportInfo]  # List of finalized reports (may be empty)
            }

        Constraints:
            - Only reports with status 'final' are included.
            - This operation does not modify the system state.

        Note:
            The returned list may be empty if no finalized reports exist.
        """
        finalized_reports = [
            report_info for report_info in self.reports.values()
            if report_info["status"] == "final"
        ]

        return { "success": True, "data": finalized_reports }

    def get_latest_finalized_report(self) -> dict:
        """
        Identify and return the most recent finalized financial report based on generation_date.

        Returns:
            dict: {
                "success": True,
                "data": FinancialReportInfo  # The report with the latest generation_date where status == 'final'
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., no finalized reports
            }

        Constraints:
            - Only reports with status 'final' are considered.
            - The latest report is determined by the most recent generation_date.
        """
        final_reports = [
            report for report in self.reports.values()
            if report["status"] == "final"
        ]

        if not final_reports:
            return {"success": False, "error": "No finalized reports available"}

        # Find the report with the latest generation_date
        # Assuming generation_date is an ISO 8601 string (e.g., "2024-12-01T10:00:00")
        latest_report = max(final_reports, key=lambda r: r["generation_date"])

        return {"success": True, "data": latest_report}

    def get_report_summary(self, report_id: str) -> dict:
        """
        Retrieve the summary text of a given financial report.

        Args:
            report_id (str): The unique identifier of the financial report.

        Returns:
            dict: {
                "success": True,
                "data": str  # The summary text of the report
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Report not found"
            }

        Constraints:
            - This operation does not require the report to be finalized.
            - Returns the summary even if it is an empty string.
        """
        report = self.reports.get(report_id)
        if not report:
            return { "success": False, "error": "Report not found" }

        return { "success": True, "data": report["summary"] }

    def get_report_by_id(self, report_id: str) -> dict:
        """
        Fetch full details of a financial report by its report_id.

        Args:
            report_id (str): The unique identifier of the financial report.

        Returns:
            dict: {
                "success": True,
                "data": FinancialReportInfo  # The full report information
            }
            or
            {
                "success": False,
                "error": str  # Explanation of failure, e.g., "Report not found"
            }

        Constraints:
            - The report_id must exist in the system.
            - This operation retrieves both draft and final reports.
        """
        if not report_id:
            return {"success": False, "error": "Report ID cannot be empty"}

        report = self.reports.get(report_id)
        if not report:
            return {"success": False, "error": "Report not found"}

        return {"success": True, "data": report}

    def list_reports_by_fiscal_period(self, period_id: str) -> dict:
        """
        Retrieve all financial reports associated with a specific fiscal period.

        Args:
            period_id (str): The unique identifier of the fiscal period.

        Returns:
            dict: {
                "success": True,
                "data": List[FinancialReportInfo]  # List of reports linked to the fiscal period (can be empty)
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., fiscal period not found
            }

        Constraints:
            - The fiscal period must exist in the system.
            - No restriction on report status (draft/final) — all are returned.
        """
        if period_id not in self.fiscal_periods:
            return { "success": False, "error": "Fiscal period not found" }

        matching_reports = [
            report for report in self.reports.values()
            if report["fiscal_period"] == period_id
        ]

        return { "success": True, "data": matching_reports }

    def get_report_statements(self, report_id: str) -> dict:
        """
        Retrieve all financial statements linked to a specific financial report.

        Args:
            report_id (str): The unique identifier of the financial report.

        Returns:
            dict: {
                "success": True,
                "data": List[FinancialStatementInfo]  # List of statements associated with the report
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g. "Report not found"
            }

        Constraints:
            - The report must exist in the system.
            - Statements are returned regardless of report status (draft/final).
        """
        if report_id not in self.reports:
            return {"success": False, "error": "Report not found"}

        statements = [
            statement for statement in self.statements.values()
            if statement["report_id"] == report_id
        ]

        return {"success": True, "data": statements}

    def get_statement_line_items(self, statement_id: str) -> dict:
        """
        Retrieve all line items associated with a given financial statement.

        Args:
            statement_id (str): The unique identifier of the financial statement.

        Returns:
            dict: {
                "success": True,
                "data": List[LineItemInfo]  # List of line items in the statement; may be empty
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Financial statement not found"
            }

        Constraints:
            - The statement_id must correspond to an existing financial statement.
            - No additional constraints (e.g., report status) block retrieval of line items.
        """
        if statement_id not in self.statements:
            return { "success": False, "error": "Financial statement not found" }

        line_items = [
            item_info for item_info in self.line_items.values()
            if item_info["statement_id"] == statement_id
        ]

        return { "success": True, "data": line_items }

    def get_fiscal_period_by_id(self, period_id: str) -> dict:
        """
        Retrieve fiscal period details including start date, end date, period type, and closure status.

        Args:
            period_id (str): The unique identifier of the fiscal period.

        Returns:
            dict: {
                "success": True,
                "data": FiscalPeriodInfo  # Full fiscal period data
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure, e.g., "Fiscal period not found"
            }

        Constraints:
            - None beyond the existence of the fiscal period.
        """
        period = self.fiscal_periods.get(period_id)
        if not period:
            return { "success": False, "error": "Fiscal period not found" }

        return { "success": True, "data": period }

    def is_fiscal_period_closed(self, period_id: str) -> dict:
        """
        Check whether a given fiscal period is closed, a prerequisite for finalizing reports.

        Args:
            period_id (str): The unique identifier of the fiscal period.

        Returns:
            dict: {
                "success": True,
                "data": {
                    "is_closed": bool  # True if the period is closed, False otherwise
                }
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., "Fiscal period not found"
            }

        Constraints:
            - The fiscal period must exist in the system.
            - This status is used to determine eligibility for finalizing financial reports.
        """
        if period_id not in self.fiscal_periods:
            return {"success": False, "error": "Fiscal period not found"}

        is_closed = self.fiscal_periods[period_id]["is_closed"]
        return {"success": True, "data": {"is_closed": is_closed}}

    def validate_statement_period_alignment(self, report_id: str) -> dict:
        """
        Verify that all statements (and their line items) in a report correspond to the report’s fiscal period.

        Args:
            report_id (str): The unique identifier of the financial report to validate.

        Returns:
            dict: {
                "success": True,
                "data": bool  # True if all line items match the report's fiscal period, False otherwise
            }
            or
            {
                "success": False,
                "error": str  # Description of the error, e.g., report not found
            }

        Constraints:
            - All line items in the report's statements must have a time_period equal to the report's fiscal_period.
            - This ensures compliance with the rule: "Financial statements in a report must align with the report’s fiscal period."
        """
        if report_id not in self.reports:
            return {"success": False, "error": "Report not found"}

        report = self.reports[report_id]
        report_fiscal_period = report["fiscal_period"]

        # Get all statements linked to this report
        statements = [s for s in self.statements.values() if s["report_id"] == report_id]

        # If no statements, consider as valid (nothing to misalign)
        if not statements:
            return {"success": True, "data": True}

        # Check every line item in every statement
        for statement in statements:
            for item_id in statement["line_items"]:
                if item_id not in self.line_items:
                    # Orphaned reference — invalid state
                    return {"success": False, "error": f"Line item {item_id} referenced in statement {statement['statement_id']} not found"}
                line_item = self.line_items[item_id]
                if line_item["time_period"] != report_fiscal_period:
                    return {"success": True, "data": False}

        return {"success": True, "data": True}

    def list_all_currencies_used(self) -> dict:
        """
        Retrieve all unique currency codes used in line items across the system.
        Ensures compliance with the rule that all monetary values must have a specified currency.

        Returns:
            dict: {
                "success": True,
                "data": List[str]  # Sorted list of unique currency codes (e.g., ['USD', 'EUR'])
            }
            or
            {
                "success": False,
                "error": str  # Only if unexpected internal issue occurs
            }

        Constraints:
            - All monetary values must be recorded with a specified currency.
            - This method assumes that the `currency` field is always present and non-empty
              in every line item, as enforced by system invariants.
        """
        try:
            currencies = {item["currency"] for item in self.line_items.values() if item["currency"]}
            return {"success": True, "data": sorted(currencies)}
        except Exception as e:
            return {"success": False, "error": f"Failed to retrieve currencies: {str(e)}"}

    def create_draft_report(
        self,
        report_id: str,
        report_type: str,
        fiscal_period: str,
        author_department: str
    ) -> dict:
        """
        Initialize a new financial report with status 'draft' for a given fiscal period and department.

        Args:
            report_id (str): Unique identifier for the report.
            report_type (str): Type of the report (e.g., 'income_statement', 'balance_sheet', 'annual_report').
            fiscal_period (str): ID of the fiscal period this report covers.
            author_department (str): Department creating the report.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success, confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - report_id must be unique.
            - fiscal_period must exist in the system.
            - New report is created with:
                - status = 'draft'
                - version = 1
                - empty summary
                - current generation_date (simulated)
        """

        if report_id in self.reports:
            return {
                "success": False,
                "error": f"Report with ID '{report_id}' already exists."
            }

        if fiscal_period not in self.fiscal_periods:
            return {
                "success": False,
                "error": f"Fiscal period with ID '{fiscal_period}' does not exist."
            }

        # Simulate current timestamp
        generation_date = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

        new_report: FinancialReportInfo = {
            "report_id": report_id,
            "report_type": report_type,
            "fiscal_period": fiscal_period,
            "generation_date": generation_date,
            "status": "draft",
            "version": 1,
            "summary": "",
            "author_department": author_department
        }

        self.reports[report_id] = new_report

        return {
            "success": True,
            "message": "Draft report created successfully"
        }

    def update_report_summary(self, report_id: str, new_summary: str) -> dict:
        """
        Modify the summary field of a draft financial report.

        Args:
            report_id (str): The unique identifier of the report to update.
            new_summary (str): The new summary text to set.

        Returns:
            dict: {
                "success": True,
                "message": "Report summary updated successfully."
            }
            or
            {
                "success": False,
                "error": str  # e.g., "Report not found" or "Cannot modify a finalized report"
            }

        Constraints:
            - Only reports with status 'draft' can be modified.
            - Finalized reports are immutable.
        """
        if report_id not in self.reports:
            return {"success": False, "error": "Report not found"}

        report = self.reports[report_id]

        if report["status"] != "draft":
            return {"success": False, "error": "Cannot modify a finalized report"}

        report["summary"] = new_summary
        return {"success": True, "message": "Report summary updated successfully."}

    def finalize_report(self, report_id: str) -> dict:
        """
        Finalize a financial report by changing its status from 'draft' to 'final',
        only if the associated fiscal period is closed.

        Args:
            report_id (str): The unique identifier of the report to finalize.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            } or {
                "success": bool,
                "error": str  # On failure
            }

        Constraints:
            - The report must exist and be in 'draft' status.
            - The report's fiscal period must exist and be closed.
            - Only finalized reports can be used for external communication (not enforced here, but implied).
        """
        # Check if the report exists
        if report_id not in self.reports:
            return { "success": False, "error": f"Report '{report_id}' does not exist" }

        report = self.reports[report_id]

        # Check if the report is already final
        if report["status"] == "final":
            return { "success": False, "error": f"Report '{report_id}' is already finalized" }

        # Check if the report's fiscal period exists
        fiscal_period_id = report["fiscal_period"]
        if fiscal_period_id not in self.fiscal_periods:
            return { "success": False, "error": f"Fiscal period '{fiscal_period_id}' not found" }

        fiscal_period = self.fiscal_periods[fiscal_period_id]

        # Check if the fiscal period is closed
        if not fiscal_period["is_closed"]:
            return { "success": False, "error": f"Fiscal period '{fiscal_period_id}' is not closed. Cannot finalize report" }

        # All conditions met: finalize the report
        self.reports[report_id]["status"] = "final"

        return { "success": True, "message": f"Report '{report_id}' has been finalized." }

    def reopen_report(self, report_id: str) -> dict:
        """
        Revert a finalized financial report back to 'draft' status for corrections.

        Args:
            report_id (str): The unique identifier of the report to reopen.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Only reports with status "final" can be reopened.
            - The report must exist in the system.
        """
        if report_id not in self.reports:
            return { "success": False, "error": "Report not found" }

        report = self.reports[report_id]

        if report["status"] == "draft":
            return { "success": False, "error": "Only finalized reports can be reopened" }

        # Reopen: revert status to draft
        report["status"] = "draft"

        return {
            "success": True,
            "message": f"Report '{report_id}' has been reverted to draft."
        }


    def generate_report_version(self, report_id: str) -> dict:
        """
        Create a new version of an existing financial report by incrementing its version number.
        The new version is initialized as a draft with updated generation date.

        Args:
            report_id (str): The unique identifier of the report to version.

        Returns:
            dict: {
                "success": True,
                "message": str  # Description of the version generated
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure (e.g., report not found)
            }

        Constraints:
            - The report must exist.
            - The new version number is current version + 1.
            - The new version status is set to 'draft'.
            - The generation_date is updated to the current time.
        """
        if report_id not in self.reports:
            return { "success": False, "error": f"Report with ID '{report_id}' not found" }

        # Get current report
        current_report = self.reports[report_id]

        # Increment version
        new_version = current_report["version"] + 1

        # Create updated report info (same report_id, new version, draft status, new date)
        updated_report: FinancialReportInfo = {
            "report_id": report_id,
            "report_type": current_report["report_type"],
            "fiscal_period": current_report["fiscal_period"],
            "generation_date": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "status": "draft",  # New version starts as draft
            "version": new_version,
            "summary": current_report["summary"],
            "author_department": current_report["author_department"]
        }

        # Update in storage
        self.reports[report_id] = updated_report

        return {
            "success": True,
            "message": f"New version {new_version} generated for report '{report_id}' as draft"
        }

    def close_fiscal_period(self, period_id: str) -> dict:
        """
        Mark a fiscal period as closed, enabling final report generation.

        Args:
            period_id (str): The unique identifier of the fiscal period to close.

        Returns:
            dict: {
                "success": True,
                "message": str  # Confirmation message
            }
            or
            {
                "success": False,
                "error": str  # Explanation of failure (e.g., period not found)
            }

        Constraints:
            - Only existing fiscal periods can be closed.
            - Once closed, the period remains closed (idempotent: multiple calls are safe).
        """
        if period_id not in self.fiscal_periods:
            return { "success": False, "error": f"Fiscal period '{period_id}' does not exist." }

        period = self.fiscal_periods[period_id]

        if period["is_closed"]:
            return { "success": True, "message": f"Fiscal period '{period_id}' is already closed." }

        # Close the period
        self.fiscal_periods[period_id]["is_closed"] = True

        return { "success": True, "message": f"Fiscal period '{period_id}' has been closed." }

    def add_statement_to_report(self, report_id: str, statement_id: str) -> dict:
        """
        Attach a financial statement to a draft financial report.

        Args:
            report_id (str): The ID of the report to which the statement will be added.
            statement_id (str): The ID of the financial statement to attach.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - The report must exist and be in 'draft' status.
            - The statement must exist.
            - The statement's line items must all belong to the same fiscal period as the report.
            - Only draft reports can be modified.
        """
        # Check if report exists
        if report_id not in self.reports:
            return { "success": False, "error": f"Report '{report_id}' does not exist" }

        report = self.reports[report_id]

        # Check if report is in draft status
        if report["status"] != "draft":
            return { "success": False, "error": f"Cannot modify report '{report_id}': status is '{report['status']}', must be 'draft'" }

        # Check if statement exists
        if statement_id not in self.statements:
            return { "success": False, "error": f"Statement '{statement_id}' does not exist" }

        statement = self.statements[statement_id]

        # If statement already belongs to this report, this is a no-op
        if statement["report_id"] == report_id:
            return { "success": True, "message": f"Statement '{statement_id}' is already associated with report '{report_id}'" }

        # If statement already belongs to another report, disallow
        if statement["report_id"] and statement["report_id"] != report_id:
            return { "success": False, "error": f"Statement '{statement_id}' is already assigned to report '{statement['report_id']}'" }

        # Validate period alignment: all line items in the statement must have time_period == report.fiscal_period
        for item_id in statement["line_items"]:
            if item_id not in self.line_items:
                return { "success": False, "error": f"Line item '{item_id}' in statement '{statement_id}' does not exist" }
            line_item = self.line_items[item_id]
            if line_item["time_period"] != report["fiscal_period"]:
                return {
                    "success": False,
                    "error": f"Line item '{item_id}' in statement '{statement_id}' has time_period '{line_item['time_period']}', "
                             f"but report '{report_id}' is for period '{report['fiscal_period']}'. Periods must match."
                }

        # Now attach the statement to the report
        self.statements[statement_id]["report_id"] = report_id

        return {
            "success": True,
            "message": f"Statement '{statement_id}' successfully added to report '{report_id}'"
        }

    def update_line_item_value(self, item_id: str, new_value: float = None, new_currency: str = None) -> dict:
        """
        Modify the value or currency of a specific line item in a financial statement.

        Args:
            item_id (str): The unique identifier of the line item to update.
            new_value (float, optional): The new monetary value for the line item.
            new_currency (str, optional): The new currency code (e.g., "USD").

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Description of the error
            }

        Constraints:
            - The fiscal period associated with the line item must not be closed.
            - If updating value, the line item must have a valid currency (provided or existing).
            - All monetary values must be recorded with a specified currency.
        """
        # Check if line item exists
        if item_id not in self.line_items:
            return {"success": False, "error": f"Line item '{item_id}' not found."}

        line_item = self.line_items[item_id]
        statement_id = line_item["statement_id"]

        # Find the statement
        if statement_id not in self.statements:
            return {"success": False, "error": f"Statement '{statement_id}' associated with line item '{item_id}' not found."}

        statement = self.statements[statement_id]
        report_id = statement["report_id"]

        if report_id not in self.reports:
            return {"success": False, "error": f"Report '{report_id}' associated with statement '{statement_id}' not found."}

        report = self.reports[report_id]
        period_id = report["fiscal_period"]

        if period_id not in self.fiscal_periods:
            return {"success": False, "error": f"Fiscal period '{period_id}' associated with report '{report_id}' not found."}

        fiscal_period = self.fiscal_periods[period_id]

        # Constraint: Cannot modify data in a closed fiscal period
        if fiscal_period["is_closed"]:
            return {"success": False, "error": f"Cannot update line item '{item_id}': fiscal period '{period_id}' is closed."}

        # If no update is requested, fail
        if new_value is None and new_currency is None:
            return {"success": False, "error": "No update provided: at least one of 'new_value' or 'new_currency' must be specified."}

        # If updating value, ensure currency is specified (either new or already exists)
        current_currency = line_item["currency"]
        if new_value is not None:
            if (new_currency is None and not current_currency) or (new_currency == ""):
                return {"success": False, "error": "Currency must be specified when setting a monetary value."}

        # Apply updates
        if new_value is not None:
            line_item["value"] = new_value
        if new_currency is not None:
            if not new_currency.strip():
                return {"success": False, "error": "Currency cannot be empty."}
            line_item["currency"] = new_currency.strip()

        # Update in store (dictionary is mutable, but we reassign for clarity)
        self.line_items[item_id] = line_item

        return {
            "success": True,
            "message": f"Line item '{item_id}' updated successfully."
        }

    def delete_report(self, report_id: str) -> dict:
        """
        Remove a draft report from the system. Finalized reports cannot be deleted.

        Args:
            report_id (str): The unique identifier of the report to delete.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Only draft reports (status = 'draft') can be deleted.
            - Final reports (status = 'final') are immutable and cannot be deleted.
            - All associated statements and line items are deleted (cascade delete).
        """
        # Check if report exists
        if report_id not in self.reports:
            return {"success": False, "error": f"Report {report_id} not found."}

        report = self.reports[report_id]

        # Check if report is final
        if report["status"] == "final":
            return {"success": False, "error": f"Cannot delete report {report_id}: final reports cannot be deleted."}

        # Collect and delete all statements associated with the report
        statements_to_delete = [
            stmt_id for stmt_id, stmt in self.statements.items()
            if stmt["report_id"] == report_id
        ]

        # Collect and delete all line items associated with those statements
        for stmt_id in statements_to_delete:
            line_items_to_delete = [
                item_id for item_id, item in self.line_items.items()
                if item["statement_id"] == stmt_id
            ]
            for item_id in line_items_to_delete:
                del self.line_items[item_id]
            del self.statements[stmt_id]

        # Delete the report itself
        del self.reports[report_id]

        return {"success": True, "message": f"Report {report_id} deleted successfully."}

    def batch_finalize_reports(self, report_ids: List[str]) -> dict:
        """
        Finalize multiple eligible draft reports that belong to the same fiscal period.

        All reports must:
        - Exist in the system
        - Be in 'draft' status
        - Belong to the same fiscal period
        - Have their fiscal period marked as closed (is_closed == True)

        Args:
            report_ids (List[str]): List of report IDs to finalize.

        Returns:
            dict: {
                "success": bool,
                "message": str  # On success
            }
            or
            {
                "success": False,
                "error": str  # Reason for failure
            }

        Constraints:
            - Only draft reports can be finalized.
            - The fiscal period of the reports must be closed.
            - All reports must belong to the same fiscal period.
            - Operation is atomic: all or none are finalized.
        """
        if not report_ids:
            return { "success": True, "message": "Successfully finalized 0 reports." }

        fiscal_period_id = None
        period_checked = False

        # First, validate all reports
        for report_id in report_ids:
            if report_id not in self.reports:
                return { "success": False, "error": f"Report with ID '{report_id}' does not exist." }

            report = self.reports[report_id]
            if report["status"] != "draft":
                return { "success": False, "error": f"Report '{report_id}' is not in draft status." }

            if not fiscal_period_id:
                fiscal_period_id = report["fiscal_period"]
            elif fiscal_period_id != report["fiscal_period"]:
                return { "success": False, "error": "All reports must belong to the same fiscal period." }

        # Now check if fiscal period exists and is closed
        if fiscal_period_id not in self.fiscal_periods:
            return { "success": False, "error": f"Fiscal period '{fiscal_period_id}' does not exist." }

        if not self.fiscal_periods[fiscal_period_id]["is_closed"]:
            return { "success": False, "error": f"Fiscal period '{fiscal_period_id}' is not closed. Cannot finalize reports." }

        # All checks passed — finalize all reports
        for report_id in report_ids:
            self.reports[report_id]["status"] = "final"

        return { "success": True, "message": f"Successfully finalized {len(report_ids)} reports." }

function.description:
Check whether a given fiscal period is closed, a prerequisite for finalizing reports.

Args:
    period_id (str): The unique identifier of the fiscal period.

Returns:
    dict: {
        "success": True,
        "data": {
            "is_closed": bool  # True if the period is closed, False otherwise
        }
    }
    or
    {
        "success": False,
        "error": str  # Description of the error, e.g., "Fiscal period not found"
    }

Constraints:
    - The fiscal period must exist in the system.
    - This status is used to determine eligibility for finalizing financial reports.
